window.PSALMS = {"1": "المزمورُ الأولُ\n1 طوبى للرجل الذي لم يسلك في مشورة المنافقين،\nوفي طريق الخطاة لم يقف،\nوفي مجلس المستهزئين لم يجلس.\n2 لكن في ناموس الربّ إرادته،\nوفي ناموسه يلهج نهارًا وليلًا.\n3 ويكون كشجرة مغروسة على مجاري المياه،\nالتي تعطي ثمرها في حينه،\nوورقها لا ينتثر،\nوكل ما يصنعه ينجح فيه.\n4 ليس كذلك المنافقون، ليس كذلك،\nلكنهم كالهباء الذي تذريه الريح عن وجه الأرض.\n5 من أجل ذلك لا يقوم المنافقون في الدينونة،\nولا الخطاة في مجمع الصديقين.\n6 لأن الربّ يعرف طريق الأبرار،\nوطريق المنافقين تبيد.", "2": "المزمورُ الثانِى\n1 لماذا ارتجّت الأممُ وتفكّرت الشعوبُ بالأباطيل ؟\n\n2 قام ملوكُ الأرض ،\nواجتمع الرؤساءُ معاً ،\nعلى الربّ وعلى مسيحه . سلام.\n3 لنقطع أغلالهما ،\nوولنلقِ عنّا نيرهما .\n4 الساكنُ في السماوات يضحكُ بِهم ،\nوالربُّ يستهزئ بهم .\n5 حينئذٍ يُكلِّمُهم بغضبه،\nوبغَضبه يُقلقُهم.\n6 أنا أقمتُ منه ملكاً ،\nعلى صهيون جبل قدسه ،\n7 لأُخبر بأمره الرب\nالربُّ قال لي أنت ابني ،\nأنا اليوم ولدتُك .\n8 اسألني ، فأعطيك الأمم ميراثًا لك ،\nوسلطانك إلى أقطار الأرض .\n9 ترعاهم بقضيبٍ من حديد ،\nوكمثله آنية الفخاره تسحقُهم .\n11 والآن ، أيُها الملوكُ ، افهموا\n\nوتأدىبوا ، يا جميع قضاةه الأرض .\n11 اعبدوا الربّ بِهشيةٍ ،\nوهلِّلوا له برعدةٍٍٍ .\n12 اهلزموا الأدبر ، لئلا يغضبر الربُّ ،\nفتضلُّو ا عن سبيله الحق ،\nعندما يتىقدُ رجزُه سريعاً .\nطوبى لجميع المتوكلين عليه .", "3": "المزمورُ الثالثُ\nمزمورٌ لداود ، عندما هرب من وجه ابنه أبشالوم .\n2 يا ربُّ ، لماذا كثُرَ الذين يُحزنونني ؟\nكثيرون قاموا عليّ\n3 كثيرون يقولون لنفسي :\nليس له خلاصٌ بإله . سلام .\n4 فأنت ، يا ربُّ ، أنت هو ناصري ،\nمجدي ورافعُ رأسي .\n5 بصوتي إلى الربّ صرخت ،\nفاستجاب لي من جبل قدسه . سلام .\n6 أنا اضطجعت ونِمت\n\nثم استيقظتُ ، لأن الربّ ينصرني .\n7 لا أخافُ من ربوات الجموع\nالمحيطين بي القائمين عليّ .\n8 قُمْ ، يا ربُّ ، خلّصني يا إلهي\nلأنك ضربتَ كل من يعاديني باطلًا ،\nسحقْتَ أسنان الخطاة .\n9 للربِّ الخلاصُ ، وعلى شعبه بركته .", "4": "المزمورُ الرابعُ\nإلى النهاية ، مزمورٌ لداود ، في التسابيح .\n2 إذ دعوتُ استجاب لي إلهُ برّي ،\nفي الشدّة فرّجتَ عنِِّ\nتراءف عليّ ، يا ربُّ ، واسْْرعْ صلاتي .\n3 يا بني البشر ، حتَّى متى تثقُلُ قلوبُكم ؟\nلماذا تحبّون الباطل وتبتغونر الكذب ؟\n4 واعلموا أن الربّ قد مجّد قدوسه عجيبًا\nالربُّ يستجيبُ لي إذا ما صرخت إليه .\n5 اهغضبوا ولا تخطئوا\nالذي تقولونره في قلوبكم ، اندموا عليه في مضاجعكم .\n\n6 اذبَروا ذبيحةر البِهِّ ، وتوكىلوا على الرب .\n7 كثيرون يقولون : من يُرينا الخيرْاته ؟\nقد ارتسمر علينا نورُ وجهكر ، يا ربُّ\n8 أعطيتر سُ روراً لقلبِه ،\nمن ثَرةه الحنطةه وخَرهم وزيتهم قد كثُروا .\n9 فبالسلامةه أضطجعُ أيضاً وأنامُ\nلأنك أنت ، يا ربُّ ، وحدركر أسكنترني على الرجاءه .", "5": "المزمورُ الخامسُ\nإلى النهاية ، على الوراثةه مزمورٌ لداود .\n2 أرنْصهتْ ، يا ربُّ ، لكلماتهى ،\nو افهمْ صُراخى ،\n3 أرصْغهٍه إلى صوته طلبتَّه ،\nيا ملكى وإلهي\nلأني إليك أصلِّى ، يا ربُّ .\n4 بالغداةه تسمعُ صوتي\nبالغداةه أقفُ أمامركر وتراني .\n5 لأنك إلهٌ لا تشاءُ الإثُْر\nولا يُساكنُكر من يصنعُ الشر .\n\n6 ولا يثبتُ مُُالفو ال ناموسه قدىامر عينـريْكر\nيا ربُّ ، أبغضتر جميع فاعلى الإثُْه .\n7 وتُُلهكُ جميع الناطقينر بالكذبه\nرجلٍُر الدماءه والغاشُّ يُرذلُه الربُّ .\n8 وأما أنا فبكثرةه رحْْتهكر أدخلُ إلى بيتهكر ،\nوأسْجُدُ أمامر هيكله قدْسهكر بِهخافتهكر .\n9 يا ربُّ ، اهد ني بعدلهكر من أجله أعدايى ،\nسرهِّلْ طريقى أمامركر .\n11 لأن ليس في أفواهم صهدْقٌ ،\nباطلٌ هو قلبُهم\nحنجرتُُم قـربـْرٌ مفتوحٌ ،\nوبألسنتهم قد غرشُّوا .\n11 فدهنْْم ، يا اللهُ\nوليسقطوا من جَريع مؤامراتُهم\nوكركثْرة نفاقهم استأصهلْهم ،\nلأنْىم قد أغضبوكر ، يا ربُّ .\n12 وليفرحْ بكر جميع المتكلينر عليكر\nإلى الأبد يُسرُّونر ، وتُرلُّ فيهم .\nوليفتخرْ بكر كلُّ الذين يُُبُّونر اسْْركر ،\n\n13 لأنك أنت باركتر الصدِّيقر .\nيا ربُّ ، كما بتَسه المسرىةه كلىلْترنا .", "6": "المزمورُ السادسُ\nإلى النهاية ، في التسابيح ، على الثامن\nمزمورٌ لداود\n2 يا ربُّ ، لا تُبكِّتْني بغضبك ،\nولا تُؤدِّبْني بهسُخْطهكر .\n3 ارحْرْني ، يا ربُّ ، لأني ضعيفٌ\nاهشْفهني ، يا ربُّ ، فإنى عظامى قد اضطربتْ .\n4 ونفسي قد انزعجرتْ جداً\nوأنت ، يا ربُّ ، فإلِر متى ؟\n5 عُدْ ، يا ربُّ ، ونرجِّ نفسي ،\nأحْيهني من أجله رحْْتهكر .\n6 لأنه ليس في الموته من يذكُرُكر\nفرمن الذي يعتَفُ لكر في الِحيمه ؟\n7 تعبتُ في تنهُّدى ،\nأُعوِّمُ كُلى ليلةٍ سريرى ،\nوبدموعى أبهلُّ فراشى .\n\n8 تعكىرتْ من الغضبه عريـْنِرى ،\nهرهمرتْ من سايره أعدايى .\n9 ابعدوا عنِِّ يا جميع فاعلى الإثُْه ،\nلأن الربّ قد سْرعر صوتر بكايى\n11 الربُّ سْرعر تضرُّعى ،\nالربُّ لصلاتي قربهلر .\n11 فليرخْزر ويضطربْ جداً جميع أعدايى ،\nوليرتردُّوا إلى ورايهم بالخهزْىه سريعاً جداً .", "7": "المزمورُ السابعُ\nمزمورٌ لداود ، الذي سربىحر به الربّ\nمن أجله أقواله خوشى ابن يَريني .\n2 أيُها الربُّ إلهي ، عليكر توكىلتُ\nخلّصني من جميع الذين يطردونني ونجرِّني ،\n3 لئلا يَرطفوا نفسي كأسدٍ ،\nوليس من ينقذُ ولا من يَُلِّصُ .\n4 أيُها الربُّ إلهي ، إن كنتُ قد فعلتُ هذا ،\nوإن كان ظُلْمٌ في يردرىى ،\n5 إن جازيتُ الذين جازوني بالشروره ،\n\nأسقطُ إذاً من أعدايى خايباً .\n6 ويضطهدُ عدوى نفسي فيدركُها ،\nويدوسُ في الأرض حياتهى ،\nويُرطُّ إلى التَابه مَرده ى . سلام .\n7 قُمْ ، يا ربُّ ، برجْزهكر ،\nوارتفعْ في أقاصى أعدايى\nاستيقظْ ، يا ربُّ إلهي ، بالأمره الذي أروصيتر به .\n8 ومَرمعُ الشعوبه يحيط بك\nولأجله هذا ارجرعْ إلى العلاءه .\n9 الربُّ يدينُ الشعوبر\nاحكُمْ لي ، يا ربُّ ، بَهسبه برّي ،\nوعلى قدره عدمه شرِّى عليّ .\n11 ليرنتره شرُّ الخاطئ ،\nأما الصدِّيقُ فتُقوِّمُهُ\nفاحصُ القلوبه والكُلرى هو اللهُ .\n11 عادلةٌ هى معونتَّه من عنده الله ،\nالذي ينجِّى مستقيمى القلوبه\n12 اللهُ قاضٍ عادلٌ وقوىٌ وطويلُ الروحه ،\nولا يأتهى برجْزه في كلِّ يومٍ .\n\n13 إنْ لم ترجعوا ، ير صْ قُ لُ سيفرهُ\nأوتـر قـروْسرهُ ، وهيىأها\n14 وأعدى فيها آلاته الموته ،\nصرنرعر سهامرهُ للملتهبينر .\n15 هو ذا الإثُُْ قد ترخىضر ،\nحربهلر ورجرعاً وورلردر ظُلْماً\n16 حرفر جُبّاً وعرمىقرهُ ،\nسيسقطُ فيه وفي الهُوىةه التي صرنرعر\n17 يرتدُّ تعبُه على رأسه ،\nوعلى هامته يرهبطُ ظُلْمُهُ .\n18 أعتَفُ للربِّ حسبر عدله ،\nوأُرتِّلُ لاسم الربّ العلهىِّ .", "8": "المزمورُ الثامنُ\nإلى النهاية ، على المعاصره مزمورٌ لداود\n2 أيُها الربُّ ربىنا، مثلر عرجربٍ صار اسُْْكر على الأرض كلِّها\nلأنه قد ارتفعر عهظرمُ جلالهكر فوقر السماوات .\n3 مهن أفواه الأطفال والرُضْعانه هيىأتر سُبْحاً ،\nبسببه أعدايكر لتسكيته عدوٍّ ومنتقمٍ .\n\n4 لأني أرى السماوات أعمالر أصابعهكر ،\nالقمر والنجومر أنت أسىسترها\n5 فمن هو الإنسانُ لأنك تذكرُهُ ،\nأو ابنُ الإنسانه لأنك تفتقدُهُ ؟\n6 واضرعْتره قليلاً عن الملايكة ،\nبالمرجده والكرامةه توىجترهُ .\n7 وأقرمترهُ على أعماله يدريْكر\nأخضعتر كُلى ش ىءٍ وتحت قردرمريْه ،\n8 الغنمر والبقر جَريعاً ،\nوأيضاً بِرايمر الحقله ،\n9 وطيور السماء وأسْْاكر البرحره ،\nالسالكةر في سُبُله البحار .\n11 أيُها الربُّ ربىنا، مثلر عجبٍ صار اسُْْكر على الأرض كُلِّها .", "9": "المزمورُ التاسعُ\nإلى النهايةه ، من أجله أسراره الابنه\nمزمورٌ لداود\n2 أعتَفُ لكر ، يا ربُّ ، من كُلِّ قلبِه ،\nأُحدِّثُ بِهميعه عجايبك\n\n3 أفرحُ وأتُرلىلُ بك ،\nأُرتِّلُ لاسْْهكر ، أيُها العليُّ .\n4 عند ارتداده عدوِّى إلى خلفٍ ،\nيضعفونر ويرهلكونر جَريعاً من وجهكر ،\n5 لأنك صنعتر حُكْمى وانتقامى ،\nجلستر على العرش ، أيُها ال ديّانُ العادلُ .\n6 انتهرتر الأمم ، وهرلركر المنافقُ\nومُروتر اسْْرهم إلى الأبده وإلى أبده الأبده .\n7 فرنهيرتْ سيوفُ العدوِّ إلى الانقضاءه ، وهردرمْتر مُدُناً\nهرلركر ذكرُها بضجيجٍ\n8 أما الربُّ ، فإلى الدهره يدومُ\nأرعدى بالقضاءه مهنْبـرهُ .\n9 وهو يدينُ المسكونةر كلىها بالعدله ،\nويقضى للشعوبه بالاستقامةه .\n11 وكان الربُّ ملجأً للمسكين ،\nوعروْناً في الأوقاته الموافقةه في الضيقه .\n11 ويتىكلُ عليكر الذين يعرفونر اسْْركر ،\nفلا تتَْكْ طالبيكر ، يا ربُّ .\n12 رتِّلوا للربِّ الساكنه في صهيون ،\n\nوأخْبِهوا في الأممه بأعماله\n13 لأنه مُطالهبٌ بالدماءه وتذكىرهُم ،\nولم ينْسر صراخر البايسينر .\n14 ارحْرْني ، يا ربُّ وانْظُرْ إلى مذلىتَّه من أعدايى ،\nيا رافعهى من أبوابه الموته ،\n15 لكى ما أُخربـِّر بِهميعه تسابيحهكر .\nفي أبوابه ابنةه صهيون\nأبتهجُ بِهلاصهكر .\n16 انغرسرته الأممُ في الهلاكه الذي صنعوه ،\nوفي الفخِّ الذي أخفوه أُمْسهكرتْ أرجُلُهُم .\n17 سيـُعْر فُ الربُّ أنه صانعُ الأحكامه ،\nوالخاطئُ بعمله يردريْه أُخهذر نشيد . سلام .\n18 ليرجعه الخطاة إلى الِحيمه،\nوكُلُّ الأممه الذين نرسُوا الله .\n19 لأنه لا ينسرى المسكينر إلى الانقضاءه ،\nوصبـْرُ البايسه لا يـرهْلهكر إلى الدهره .\n21 قُمْ ، يا ربُّ ، لا يعتـرزى الإنسانُ ،\nولْتُحاكرمه الأممُ أمامركر .\n21 أرقهمْ ، يا ربُّ ، عليهم واضعر ناموسٍ ،\n\nليرعلرم الأممُ أنْىم بشرٌ . سلام .\n22 لماذا ، يا ربُّ ، تقفُ خارجاً من بعيدٍ ؟\nوتُُوِّلُ وجهكر في أوقاته الضيقه ؟\n23 عندما يستكبِهُ المنافقُ يلتهبُ المسكينُ\nيـُؤْخرذونر بالمشورة التي أشاروا بِها .\n24 لأن الخاطئر يَُتدرحُ بشهواته نفسه ،\nوالظالَهر يُباركُ .\n25 أغاظر الخاطئُ الربّ ،\nحسب كثْرةه غضبه لا يبحثُ\nليس اللهُ أمامرهُ .\n26 طُرُقُهُ نجرسةٌ في كُلِّ حينٍ\nأبادر أحكامركر عن وجه ،\nويسودُ على جميع أعدايه .\n27 لأنه قالر في قلبه إهنِِّ لا أزولُ من جيلٍ إلى جيلٍ\nبغريرْه سوءٍ\n28 فمُهُ مَرلوءٌ لعنةً ومرارةً وغشّاً ،\nوتحت لسانه عناءٌ ووجعٌ .\n29 جلسر في الكمينه مع الأغنياءه ،\nلقتله البِرىءه في خهفيةٍ\n\nعيناه تراقبانه البايسر .\n31 يكمنُ في الخفاءه ، مثلر الأسده في مرْبهضه\nيـر تَر صى دُ ليخطفر المسكينر ،\nيَرطفُ المسكينر إذا جرذربرهُ\n31 في فخِّه يُذهلُّهُ\nسينحني ويسقطُ عندر تسلُّطه على البايسينر .\n32 لأنه قالر في قلبه إنى الله قد نرسهىر ،\nصرفر وجههُ لئلا ينظر إلى الانقضاءه .\n33 قُمْ ، أيُها الربُّ الإلهُ ، لتَرتفعْ يردُكر\nولا تنسر المساكينر .\n34 لماذا أغضبر المنافقُ الله ؟\nلأنه قالر في قلبه ؟ إنه لا يفحصُ .\n35 أنت ترى ، لأنك للتعبه والغضبه تتأملُ ،\nإذا دُفهعُوا في يدريْكر .\nلكر تُرهكر المسكينُ ،\nأنت عوْنُ اليتيمه .\n36 حطِّمْ ذراعر الخاطئه والشرِّيره\nتُلتمسُ خطيئتُه فلا يُوجردْ من أجلها .\n37 الربُّ يَرلكُ إلى الأبده وإلى أبده الأبده\n\nأيُها الأممُ ، ستـرهْلركونر من أرضه .\n38 شهوةُ المساكينر سْرهعرها الربُّ ،\nوأصغرى بسمعه لاستعداد قلوبِهم ،\n39 لهيرحْكُمر لليتيمه والمتواضعه ،\nكى لا يعودر الإنسانُ يفتخهرُ بالعظايمه على الأرض .", "10": "المزمورُ العاشرُ\nإلى النهاية مزمورٌ لداود .\n1 على الربّ توكىلتُ كيف تقولونر لنفسي\nانتقلى على الِباله مثلر العصفوره ؟\n2 لأنه هو ذا الخطاة قد أوتروا قهسهيـىهُم ،\nوهيىأوا سهاماً في جعابِهم ،\nليرموا في الخفاءه مستقيمى القلوبه .\n3 لأن الذي هيىأتره أنت هم هدموه\nأما البارُ فماذا صرنرعر ؟\n4 الربُّ في هيكله قدسه\nالربُّ ، في السماء كُرْسهيُّهُ ،\nعيناه إلى المساكينهٍه تنظرانه ،\nأجفانُه تفحصُ بني البشر .\n\n5 الربُّ يَرتبِهُ الصدِّيقر والمنافقر\nوالذي يُُبُّ الظُلْمر فلنفْسه أربـْغرضر .\n6 يَُْطهرُ على الخطاة فهخاخاً\nناراً وكبِْيتاً وريُاً عاصفاً نصيبر كرأْسهم .\n7 لأن الربّ عادلٌ ويُُبُّ العدلر ،\nونرظر باستقامةه وجه .", "11": "المزمور الحادىَ عَشَرَ\nإلى النهاية ، من أجل الثامن مزمورٌ لداود .\n2 أرحْيهني ، يا ربُّ فإنى القديسر قد فرنِهر ،\nوالبِهُّ ترناقرصر من بني البشر .\n3 تكلىمر كلُّ واحدٍ مع صاحبه بالباطل ،\nشفاهٌ غاشىةٌ في قلوبِهم ، وبقلوبِهم تكلىموا .\n4 يستأصلُ الربُّ جميع الشفاه الغاشىةه وال لسانر الناطقر\nبالعظايمه،\n5 الذين قالوا نُعظِّمُ ألسنترنا ،\nشهفاهُنا هى مهنىا من هو ربٌّ لرنا ؟\n6 من أجله شقاءه المساكين وتنهُّده البايسينر ،\nالآنر أقومُ ، يقولُ الربُّ\n\nأكونُ في الخلاصه ، وأُظْهرُ ذاتهى فيه .\n7 كلامُ الربّ ه و كلامٌ نقىٌ ،\nهو فضةٌ مسبوكةٌ مُُتارةٌ في الأرض ،\nنقيةٌ سبعةر أضعافٍ .\n8 أنت ، يا ربُّ ، تُنجِّينا ،\nوتُرفظُنا من هذا الِيله وإلى الدهره .\n9 المنافقون حولرنا يتمشُّونر ،\nمثلر ارتفاعهكر أطلْتر عُمْر بني البشر .", "12": "المزمور الثانِى عَشَرَ\nإلى النهاية مزمورٌ لداود .\n2 إلى متى ، يا ربُّ ، تنساني إلى الانقضاءه ؟\nإلى متى تُرجبُ وجهكر عنِِّ ؟\n3 إلى متى أضعُ هذه المشوراته في نفسي ،\nوالأوجاعر في قلبِه النهار كُلىهُ ؟\nحتَّى متى يرتفعُ عدوِّى علىى ؟\n4 اُنْظُرْ واستجهبْ لي ، يا ربُّ إلهي\nأرنهرْ عريـْنِرى لئلاى أنامر في الموته ،\n5 لئلاى يقول عدُوِّى إنِِّ قد قويتُ عليه\n\nالذين يُحزنونني يتهلىلونر إن أنا زرلرلْتُ .\n6 أما أنا فعلى رحْْتهكر توكىلتُ\nيبتهجُ قلبِه بِهلاصهكر\nأُسبِّحُ الربّ الذي أحْسرنر إلِرى ،\nوأُرتِّلُ لاسمه الربّ العليّ .", "13": "المزمورُ الثالثُ عَشَرَ\nإلى النهاية مزمورٌ لداود .\n1 قالر الِاهلُ في قلبه ليس إلهٌ .\nفسدوا وتدنىسوا بأفعالهم ،\nليس من يعملُ صلاحاً ، حتَّى ولا واحدٌ .\n2 الربُّ من السماء اطىلرعر على بني البشر ،\nلينظر إن كان من يفهمُ أو يطلبُ الله .\n3 الكلُّ قد زاغوا وفسدوا معاً ،\nليس من يعملُ صلاحاً ، حتَّى ولا واحدٌ .\nحنجرتُُم قبـْرٌ مفتوحٌ ،\nبألسنتهم قد غرشُّوا\nسُمُّ الأفاعى وتحت شفاهم ،\nفمُهُم مَرلوءٌ لعنةً ومرارةً\n\nأرجلُهُم سريعةٌ إلى سرفْكه الدماءه\nالانكسارُ والشقاءُ في سُبُلهم ،\nوطريقُ السلامه لم يعرفوه\nليس خوفُ الله قدىامر عيونْهم .\n4 ألا يعلمُ جميع عاملى الإثُْه ،\nالذين يأكلونر شعبِه كأكله الخُبْزه؟ وإلى الربّ لم يدْعُوا .\n5 هناك خافوا خروْفاً حيثُ ليس خروْفٌ\nلأن الله في جيله الأبرار .\n6 رأىٍُر المسكينر أرذرلتُمْ ،\nلأن الربّ هو رجاؤه .\n7 من يُعطى مهن صهيون خلاصاً لإسراييلر ؟\nإذا ما ردى الربُّ سربِْر شعبه ،\nفليتهلىلْ يعقوبُ ويفرحْ إسراييلُ .", "14": "المزمور الرابعََُ عَشَرَ\nمزمورٌ لهداو در .\n1 يا ربُّ ، من يسكنُ في مسكنهكر ؟\nأو من يستَيحُ في جبل قدسهكر ؟\n2 إلاى السالكُ بلا عريْبٍ ويعملُ البِهى ،\n\nويتكلىمُ الحق في قلبه\n3 الذي لم يغشى بلسانه ،\nولم يصنعْ بقريبه سوءاً ،\nولم يقبلْ عاراً على جيرانه ه\n4 فاعلُ الشرِّ مرذولٌ أمامرهُ ،\nويَُجِّدُ الذين يتىقون الربّ\nالذي يُرلفُ لقريبه ولا يغدرُ به\n5 لم يـُعْطه فضترهُ بالرهبا ،\nولم يقبله الرشْورةر على الأبرياءه\nالذي يصنعُ هذا لا يترزعزعُ إلى الدهره .", "15": "المزمور الخامسََُ عَشَرَ\nنقْشٌ عل ى عمودٍ لداود\n1 احفظني ، يا ربُّ ، فإنِِّ عليكر توكىلْتُ .\n2 قـُلْتُ للربِّ أنت ربَِّ ، ولستر تُرتاجُ إلى خريرْاتهى .\n3 أظهر عجايبرهُ لقدِّيسيه الذين في أرضه ،\nوصرنرعر فيهم كلى مشيئاته .\n4 كثـُرتْ أمراضُهُم ،\nومن بعد هذا أسرعوا\n\nلا أجَْعُ مَرامعرهم من الدماءه ،\nولا أذكُرُ أسْْاءرهُم بشفتَّرى .\n5 الربُّ هو نصيبُ ميراثهى وكأسهى\nأنت الذي ترُدُّ إلِرى ميراثهى .\n6 حهبالُ المساحرةه وقعرتْ لي من الأعزّاءه ،\nوإن ميراثهى لثابتٌ لي .\n7 أباركُ الربّ الذي أفهرمرني\nوأيضاً إلى الليل أدىبـرتْني كُلْيرتاىر .\n8 تقدىمتُ فرأيتُ الربّ أمامي في كلِّ حينٍ .\nلأنه عن يَريني لكى لا أتزعزعر .\n9 من أجله هذا فرهحر قلبِه ،\nوتُرلىلر لساني ،\nوأيضاً جسدى يسكنُ على الرجاءه .\n11 لأنك لا تتَْكُ نفسي في الِحيمه ،\nولا تردرعُ قدوسر كر يرى فساداً .\n11 قد عرفيـْترني طُرُقر الحياةه\nترلأُني فرحاً مع وجهكر\nالبهجةُ في يمينك إلى الانقضاءه .", "16": "المزمور السادسََُ عَشَرَ\nصلاةٌ لداود .\n1 استرمعْ ، يا اللهُ ، لحهرقِّى ،\nوأنصتْ إلى طلبتَّه ،\nأرصْغه إلى صلاتي من شف تـرينْه بلا غهشٍّ .\n2 من قهبرله ورجْهكر لهيرخرجْ قضايى ،\nعيناىر لتنظرا المستقيماته .\n3 جرىبتر قلبِه ، تعهىدترني ليلاً\nمُرىصترني فلرم تَّردْ فىهى ظُلْماً .\n4 لكى لا يتكلىمر فمى بأعماله البشر ،\nمن أجله كلامه شفتـريْكر أنا حفظتُ طُرُقاً صعبةً .\n5 ثـربِّتْ خُطواتهى في سُبُلهكر ،\nلئلاى تزلى قدماىر .\n6 أنا صرخت ، لأنك سْرعترني ، يا اللهُ\nأرمهلْ أُذنـريْكر إلِرى ، يا ربُّ ، واسترمعْ كلامى .\n7 فليُتـرعرجىبْ من مراحْهكر ،\nيا مُُلِّصر المتكلين عليكر\nمن الذين يُقاومون يَرينركر .\n8 احفظْني ، يا ربُّ ، مثلر حدقرةه العرينْه\n\nوبظلِّ جرناحريْكر استـُرْني\n9 من ورجْه المنافقين الذين يُضعفونرني .\nأعدايى لهنفسي قد اكتنفوا ،\n11 أغلقوا أحشاءرهُم ،\nأفواهُهُم قد تكلىمرتْ بالكبِْياءه\n11 قد أخرجوني والآنر أحاطوا بي ،\nنصبوا أعينرهم لكى يَُيلوني إلى الأرض\n12 أخذوني مثلر الأسده المتهيِّئ للصيده ،\nوكالأشباله التي تركْمُنُ في أماكنر خفيةٍ .\n13 قُمْ ، يا ربُّ ، تقدىمْهُم واصْرعْهُم ،\nنرجِّ نفسي من المنافقه ،\n14 وسيفركر من أعداءه يدريْكر\nيا ربُّ ، عن قليلٍ شتِّتـْهُم في الأرض ،\nأرقْسهمْهُم في حياتُهم\nامتلأتْ بطونـُهُم من خفياتهكر ،\nأرفعموا بطونـرهُم من لحرْمه الخنازيره ،\nوتركوا ما فرضهلر عنـْهُم لأطفالهم .\n15 وأنا بالبِهِّ أتراءرى لوجهكر ،\nوأشبرعُ عندما يظهرُ مَرْدُكر .", "17": "المزمور السابعََُ عَشَرَ\nإلى النهاية ، لداود فتَّر الربّ الذي تكلىم مع الربّ\nبكلامه هذه التسبحةه في اليوم الذي أنقذرهُ فيه الربُّ\nمن أيدى كُلِّ أعدايه ومن يده شاولر\n2 وقال\nأُحهبُّكر ، يا ربُّ ، يا قوىتهى .\n3 الربُّ ثباتهى وملجأى ومُنقذى\nإلهي عوني ، وعليه أتىكلُ\nالمقاتهلُ عنِِّ وقرنُ خلاصى ، وناصري .\n4 أُسبِّح الربّ وأدعوهُ ، فأنجو من أعدايى .\n5 اكتنفتْني أوجاعُ الموته ،\nوسيولُ إثمي أفزعتْني\n6 أوجاعُ الِحيمه أحاطتْ بي ،\nأدركتْني فهخاخُ الموته .\n7 عندر شهدىتهى دعوتُ الربّ ،\nوإلى إلهي صرخت\nفسرمهعر صوتي من هيكله المقدىسه ،\nوصراخى قُدىامرهُ يدخلُ إلى مسامعه .\n8 تزلزلرته الأرضُ فصارتْ مرتعدةً ،\n\nواضطربتْ أساساتُ الِباله ،\nوتزعزعتْ لأنى الربّ غرضهبر عليها .\n9 صرعهدر دخانٌ من غضبه ،\nوالنارُ اتىقدرتْ قُدىامرهُ ،\nو الِرمْرُ اشتعلر منه .\n11 طأطأر السرماءر ونرزهلر ،\nوالضبابُ تُتر رهجْلريْه .\n11 ركهبر على الشاروبيمر وطار ،\nطار على أجنحةه الرياحه .\n12 مجّد الظُلْمةر حهجاباً له ،\nمظلتره مُُيطةً به ،\nماءر ظُلْمةٍ في سُحُبه الهواءه .\n13 من ضياءه وجه جازتْ السُحُبُ قُدىامرهُ ،\nبـردٌ وجَرْرُ نارٍ .\n14 وأرْعردر الربُّ من السرماءه ،\nوالعليُّ أعطرى صوترهُ\n15 أرسرلر سهامرهُ ففرىقـرهُم ،\nوأكثـر بُروقرهُ فأقـْلرقرهُم .\n16 وظهرتْ عيونُ المياه ،\n\nوأساساتُ المسكونةه انكشفتْ\nمن انتهارهكر ، ي ا ربُّ ،\nمن نسمةه ريحه رهجْزهكر .\n17 أرسرلر من العلاءه وأخرذرني ،\nانـْترشرلرني من مياهٍ كثيرةٍ .\n18 يُنقهذُني من أعدايى الأقوياءه\nومن أيدى الذين يُبغضونرني ،\nلأنْىم تقوُّوا أكثـر منِِّ .\n19 أدركوني في يومه مُهْنرتَّه ،\nوكان الربُّ سرنردهى ،\n21 وأخرجرني إلى السهعرةه\nيُنجِّيني ، لأنه أرادرني .\n21 يَُلِّصُني من أعدايى الأشدىاءه\nومن أيدى مُبْغضىى .\nيُكافئُني الربُّ حسب برّي ،\nوحسب طهارةه يردرىى يُكافئُني .\n22 لأني حفظتُ طُرُقر الربّ ،\nولم أرعْصه إلهي\n23 لأن جَري عر أحكامه قُدىامى ،\n\nوحقوقره لم أُبْعهدْها ع.\n24 وأكونُ معه بلا عريْبٍ ،\nوأتُرفىظُ من إثمي .\n25 ويُكافئُني الربُّ حسب برّي\nوكطهارةه يدرىى\nأمامر عينـريْه .\n26 مع البارِّ باراً تكونُ ،\nومع الإنسان الزكىّ تكونُ زكيّاً ،\n27 ومع المُختاره تكونُ مُُتاراً ،\nومع المعوجِّ تتغريـىرُ .\n28 لأنىكر أنت يا ربُ تُنجِّى شعباً متواضعاً ،\nوتُذهلُّ أعْينُر المتعظِّمينر\n29 لأنىكر أنت تُضىءُ سراجى ، يا رب\nإلهي ، يُنيرُ ظُلْمرتَّه .\n31 لأني بك أنجو من الترجربةه ،\nوبإلهر ى أرثهبُ السور .\n31 إلهي ، طريقُهُ نقيىةٌ ،\nكلامُ الربّ مُُْتربـرٌ بالناره ،\nوهو ناصرُ جميع المُتىكلينر عليه .\n\n32 لأنىه من هو إلهٌ غريـْرُ الربّ ؟\nومن هو الإلهُ سورى إلهرهنا ؟\n33 اللهُ الذي يَُنطقُني بالقوىةه ،\nومجّد طريقى بلا عريْبٍ\n34 الذي يـُثربِّتُ رهجْلرىى كالأيّله ،\nويُقيمُني على مرتفعاته\n35 الذي يُعلِّم يردرىى القتالر ،\nومجّد ذراعرىى أقواساً من نُُاسٍ\n36 أعطيترني نُصْرةر خلاصى ،\nويَرينُكر عرضىدرتْني\nوأدبُكر قـروىمرني إلى المُنتهى ،\nو حهكْمتُكر تُعلِّمُني .\n37 أوسعتر خُطواتهى تُرتَّه ،\nوخُطواتهى لا تضعُفُ .\n38 أُطاردُ أعدايى فأدركُهُم ،\nولا أرجعُ حتَّى يفنـروْا\n39 أُضريِّقُ عليهم ، فلا يستطيعونر الوقوفر ،\nيسقطونر وتحت قردرمرىى .\n41 منطرقْترني قوىةً في الحربه ،\n\nوقيىدْتر كُلى الذين قاموا عليّ تُرتَّه .\n41 أعطيترني أعدايى مرطروحينر على ظهورهم ،\nومُبغضىى أستأصلتر .\n42 صرخوا فلم يكنْ لهرم مُُلِّصٌ\nإلى الربّ ، فلم يستمعْ إليهم .\n43 أُذرِّيهم كالهرباءه قُدىامر وجه الريحه ،\nومثلر طينه الأزقىةه أدوسُ هُم .\n44 نجرِّني من مقاوماته الشعبه ،\nوتُقيمُني رأساً على الأُمرمه\nالشعبُ الذي لم أعرفْه تـرعربىدر لي ،\n45 وبهسرمْعه الأُذُنه أطاعرني\nبنو الغرباءه كرذىبوني ،\n46 بنو الغرباءه ترعتىقوا ،\nوترعرىجوا من سبيلهم .\n47 حىٌ هو الربُّ ، ومباركٌ هو إلهي ،\nويتعالِر إلهُ خلاصى\n48 الله الذي يُعطيني الانتقامر ،\nوأرخْضرعر الشعوبر تُرتَّه ،\n49 مُنْقذى من أعدايى الحانقينر\n\nمن الذين يقومونر عليّ تـرْفـرعُني ،\nومن الرجُله الظالَه تُنجِّيني .\n51 من أجله هذا أعتَفُ لكر يا ربُّ في الأُمرمه ،\nوأُرتِّلُ لاسْْهكر\n51 يا مُعرظِّمر خلاصه مرلهكه ،\nوصانعر الرحْْةه مع مسيحه ،\nداود وزرعه إلى الأبده .", "18": "المزمورُ الثامنََُ عَشَرَ\nإلى النهاية ، مزمورٌ لداود .\n2 السماوات تُُدِّثُ بِهجده الله ،\nالفرلركُ يَُربـِّرُ بهعمله يدريْه .\n3 يومٌ إلى يومٍ يـُبْدى كلمةً ،\nوليلٌ إلى ليلٍ يُظْهرُ عهلْماً .\n4 ليس أقوالٌ ولا كلامٌ الذين لا يُسْمرعُ صوتـُهُم\n5 في كُلِّ الأرض خرجر منطهقُهُم ،\nوإلى أقاصهى المسكونةه بلغرتْ أقوالهُُم .\n6 مجّد في الشمسه مهظرلىترهُ\nوهى مثلُ ا لخرتَره الخارجه من خهدْره ،\n\nيتهلىلُ مثلر الِبىاره الذي يُسْرهعُ في طريقه .\n7 من أقصرى السماء خروجُهُ ،\nومنتهاهُ إلى أقصرى السماء\nوليس من يَرْتفي من حرارته .\n8 ناموسُ الربّ طاهرٌ ، يـرُدُّ النفوسر\nشهاداتُ الربّ صادقةٌ ، تُعلِّمُ الأطفالر .\n9 حقوقُ الربّ مستقيمةٌ تُفرِّحُ القلبر\nوصيةُ الربّ مُضيئةٌ ، تُنيرُ العينـرينْه عن بـُعْدٍ .\n11 مُرافةُ الربّ طاهرةٌ ، دايمةٌ إلى أبده الأبده\nأحكامُ الربّ أحكامُ حقٍّ عادلةٌ كُلُّها ،\n11 شهواتُ قلبه مُُتارةٌ أفضلُ من الذهبه والحجره الكثيره الثمنه،\nوأحلرى من العسله والشهده .\n12 وإن عربْدركر يُرفظُها\nوفي حهفْظها مَُازاةٌ كثيرةٌ .\n13 من يقدرُ أنْ يتفهىمر الهفواته\nطرهِّرْني يا ربُّ من خرفيىاتهى ،\n14 ومن الغرباءه أرشْفهقْ على عربْدهكر\nإذا لم يتسلىطوا عليّ ، حينئذٍ أكونُ بلا عريْبٍ ،\nوأتنقىى من خطيةٍ عظيمةٍ .\n\n15 وتكونُ جميع أقواله فمى بِهسرىةٍ ،\nوتلاوةُ قلبِه أمامركر في كُلِّ حينٍ ،\nالربُّ هو مُعيني ومُُلِّصى .", "19": "المزمورُ التاسعََُ عَشَرَ\nإلى النهاية ، مزمورٌ لداود\n2 يستجيبُ لكر الربُّ في يومه شدىتهكر ،\nينصرُكر اسمُ إله يعقوب .\n3 يـُرْسهلُ لكر عروْناً من القدسه ،\nومن صهيون يـرعْضُدُكر\n4 يذكُرُ جميع ذبايحهكر ،\nومُُرقاتُكر درسْهةٌ عندرهُ . سلام .\n5 يُعطيكر الربُّ حسب قلبك ،\nويـُترمِّمُ كُلى مشوراتهكر .\n6 نعتَرفُ لكر ، يا ربُّ ، بِهلاصهكر ،\nوباسمه إلهرهنا ننمو .\nيُكرمِّلُ الربُّ كُلى سُؤالهكر .\n7 الآنر علمتُ أنى الربّ قد خرلىصر مسيحرهُ\nيستجييبُ له من سْراءه قدسه ،\n\nبِهبِروته خلاصه يَرينه .\n8 هؤلاءه بِهركباتٍ وهؤلاءه بِهيلٍ ،\nونُن باسمه الربّ إلهرهنا ننمو .\n9 هم عرثروا وسرقرطوا ،\nأما نُن فقُمْنا واستـرقرمْنا .\n11 يا ربُّ ، خرلِّصْ مرلهكركر ،\nواسترجهبْ لنا يومر ندعوكر .", "20": "المزمورُ العشرونَ\nإلى النهاية مزمورٌ لداود\n2 يا ربُّ ، بقوىتهكر يفرحُ المرلهكُ ،\nوبِهلاصهكر يتهلى لُ جداً .\n3 شهوةر نفسه أعطيترهُ ،\nومُلترمرسر شفتـريْه لم ترْنـرعْهُ . سلام .\n4 لأنك تقدىمْترهُ بهبِركاته صلاحهكر ،\nووضعتر على رأسهٍه إكليلاً من حجرٍ كريمٍ .\n5 حياةً سألركر ، فأعطيترهُ ،\nطولر الأيامه إلى الأبده وإلى أبده الأبده .\n6 مَردُهُ عظي مٌ بِهلاصهكر ،\n\nمَرداً وبِراءً عظيماً جرعرلْتر عليه\n7 لأنك تُعطيه بركةً إلى أبده الأبده ،\nتـُبْهجُهُ بهفرحٍ مع وجهكر .\n8 لأن المرلهكر تروكىلر على الربّ ،\nوبرحْْةه العليِّ لا يترزعزعُ .\n9 تظفرُ يدُكر بِهميعه أعدايهكر ،\nويَرينُكر تظفرُ بكُلِّ الذين يـُبْغضونركر .\n11 تَّرعلُهم مثلر تـرنُّوره نارٍ في زمانه وجهكر\nيا ربُّ ، بغضبك تـُقْلهقُهُم ، وتأكلُهُم النارُ .\n11 تُبيدُ ثَرتـرهُم من الأرض ،\nونسلرهُم من بـرينْ بني البشر .\n12 لأنْىم مرالوا عليكر بالشروره ،\nوتشاوروا مشورةً لم يقدروا أن يُقيمُوها .\n13 لأنك ترصْرعُهُم على ظهرهم ،\nفي البقيىةه التي لكر تُُيِّئُ وجوهرهُم .\n14 ارترفعْ يا ربُّ بهقوىتهكر ،\nنُسبِّحُ ونُرتِّلُ لِهبِروتهكر .", "21": "المزمورُ الحادِى والعشرونَ\nإلى النهاية ، من أجل معونةه الصباحه مزمورٌ لداود\n2 إلهي إلهي ، اهلْترفهتْ إلِرى لماذا تركْترني ؟\nكلامُ زرلاىتهى هو بعيدٌ عن خلاصهى .\n3 إلهي ، بالنهار أصرخُ إليك فلا تستجيبُ لي ،\nوفي الليل ، ولم يكنْ ذلكر جهلاً منِِّ .\n4 وأنت حالٌّ في القدِّيسينر ، يا فخر إسراييلر .\n5 بك آمر نر آباؤنا ،\nعليكر اتىكلوا فنجىيتـرهُم\n6 إليك صرخوا فخلُصوا ،\nعليكر اتىكلوا فلم يَرزروْا .\n7 وأما أنا فدودةٌ أنا ، ولستُ إنساناً ،\nعارٌ للبشره ورذالةٌ للشعوبه .\n8 كلُّ الذين رأوني استهزأوا بي ،\nتكلىموا بشفاهم وحرىكوا رؤوسرهُم .\n9 وقالوا : إنْ كانر آمرنر واتىكرلر على الربّ ، فليُخلِّصْهُ\nوليـُنرجِّه ، إنْ كانر أرادرهُ .\n11 لأنك أنت الذي جرذربـْترني من البطنه ،\nرجايى مُذْ كُنْتُ أرضعُ ثدىه أمي\n\n11 عليكر أُلْقهيْتُ وأنا في الرحْمه ،\nومُذْ كُنْتُ في بطنه أمي أنت إلهي\n12 لا تتباعدْ عنِِّ ، فإنى الشدىةر قريبةٌ ،\nوليس مهن مُعينٍ .\n13 أحاطرتْ بي عجولٌ كثيرةٌ ،\nثيرانٌ سْهانٌ اكتنفتْني\n14 فتحوا علىى أفواهرهُم ،\nمثلر الأسده الذي يَرطفُ ويزأرُ .\n15 انسكبتُ مثلر الماءه ،\nتفرىقرتْ جميع عظامى ،\nصار قلبِه مثلر شَرْعٍ مُذابٍ في وسطه بطني .\n16 يبسرتْ مثلر شرقْفرةٍ قوىتهى ،\nوالتصقر لساني بَهنجرتهى ،\nوإلى أرضه الموته أحْدرْترني .\n17 أحاطرتْ بي كلابٌ كثيرةٌ ،\nمَرمعُ الأشراره اكتنفتْني\nثقبوا يدىى ورهجْلرىى .\n18 أحصوا كُلى عهظامى\nوهُم تأمىلوني ونظروا إلِرى ،\n\n19 اقتسموا ثيابي بينرهم ،\nوعلى لهباسى ألقوا قـُرْعرةً .\n21 أما أنت ، يا ربُّ ، فلا تـُبْعهدْ مرعونتَّه عنِِّ ،\nاهلْترفهتْ إلى نُصرتهى .\n21 أرنْقهذْ من السيفه نفسي ،\nومن يده الكلبه بنوىتهى الوحيدةر .\n22 خرلِّصْني من فمه الأسده ،\nوتواضعى من قرنه ذوى القرنه الواحده .\n23 أتكلىمُ باسْْهكر بـرينْر إخوتهى ،\nوفي وسطه الكنيسةه أُسربِّحُكر .\n24 يا خايفي الربّ سربِّحوه\nمَرِّدوه يا جميع نسله إسراييلر .\nوليرخْشرهُ كُلُّ نسله يعقوب ،\n25 لأنه لم يُرتقرْ ولم يُرذهلْ دُعاءر المسكينه ،\nولم يصرفْ وجههُ عنِِّ ،\nبل عندما صرخْتُ إليه استجاب لي .\n26 من قهبرله يكونُ افتخارى في كنيسةٍ عظيمةٍ ،\nوصلواتهى أُعطيها قدىامر خايفيه .\n27 يأكلُ المساكينُ ويشبعونر ،\n\nويُسبِّحُ الربّ الذين ي لتمسونرهُ\nتُريا قلوبـُهُم إلى أبده الأبده .\n28 تذكُرُ وترجهعُ إلى الربّ كُلُّ أقطار الأرض ،\nوتسجُدُ قُدىامره كُلُّ أبوىاته الأُمرمه .\n29 لأنى المُلْكر هو للربِّ ،\nوهو يسودُ الأُمرمر .\n31 أكلر وسرجردر كُلُّ سْهانه الأرض ،\nقُدىامرهُ َرثو كُ لُّ الذين يُرلُّونر على الأرض\nونفسي أيضاً له تُريا .\n31 وزرْعهى يتعبىدُ له\nيَُربـىرُ بالربّ الِيلُ الآتهى ،\n32 ويُُدِّثونر بهبِهِّه الشعبر الذي يـُوْلردُ ،\nالذي صرنـرعرهُ الربُّ .", "22": "المزمورُ الثانِى والعشرونَ\nمزمورٌ لداود\n1 الربُّ يرعاني ، ف لا يُعوزُني ش ىءٌ .\n2 في مكانه خُضرةٍ أرسْكرنرني ،\nعلى ماءه الراحةه ربىاني\n\n3 ردى نفسي .\nهرداني إلى سُبُله البِهِّ\nمن أجله اسْْه .\n4 وإن أنا سرلركْتُ في وسطه ظلِّ الموته ،\nفلا أخافُ شرّاً ، لأنك أنت معى\nعصاكر وقضيبُ كر هُُا اللذان عزىيانرني .\n5 هيىأتر قُدىامى مايدةً تَُّاهر مُضايقىى\nمرسرحْتر بالزيته رأسي ،\nوكأسُكر أرسْكرتْني مثلر الصرْفه .\n6 ورحْْتُكر تُدركُني جميع أيامه حرياتهى ،\nوسُكْناىر في بيته الربّ إلى مدرى الأيامه .", "23": "المزمورُ الثالثُ والعشرون\nمزمورٌ لداود في أحد السبوت\n1 للربِّ الأرضُ وملؤُها ،\nالمسكونةُ وجميع الساكنين فيها .\n2 هو على البحار أسّسها ،\nوعلى الأنهار هيّأها .\n3 من يصعد إلى جبل الربّ ؟\n\nومن يقومُ في موضعه قدسه ؟\n4 الطاهرُ اليدين ، والنقىُّ القلب ،\nالذي لم يحمل نفسه إلى الباطل ،\nولم يحلف لقريبه بغشّ .\n5 هذا ينالُ بركة من الربّ ،\nورحمة من الله مخلّصه .\n6 هذا هو جيلُ الذين يطلبون الربّ ،\nويبتغون وجه إله يعقوب . سلام .\n7 ارفعوا أيُها الرؤساءُ أبوابكم ،\nوارتفعى ، أيتها الأبوابُ الدهريةُ ،\nفيدخلر مرلهكُ المرجْده .\n8 من هو هذا مرلهكُ المرجْده ؟\nالربُّ العزيزُ القديرُ ،\nالربُّ القوىُّ في الحروبه .\n9 ارفعوا أيُها الرؤساءُ أبوابكم ،\nوارتفعى ، أيتها الأبوابُ الدهريةُ ،\nفيدخلر مرله كُ المرجْده .\n11 من هو هذا مرلهكُ المرجْده ؟\nربُّ القوىاته ، هذا هو مرلهكُ المرجْده .", "24": "المزمورُ الرابعُ والعشرونَ\nمزمورٌ لداود\n1 إليك ، يا ربُّ ، رفعتُ نفسي ،\n2 يا إلهي عليكر توكىلْتُ ، فلا تُُْزهني إلى الأبده ،\nولا ترشْمرتْ بي أعدايى .\n3 لأنى جميع الذين ينتظرونركر لا يَُْزروْنر ،\nليرخْزر الذين يصنعونر الإثُْر باطلًا .\n4 أرظْهرْ لي ، ياربُّ ، طُرُقركر ،\nوعرلِّمْني سُبـُلركر\n5 أرهْدهني إلى حرقِّكر\nوعرلِّمْني ، لأنك أنت هو اللهُ مُُلِّصى ،\nوإيىاكر انتظرتُ ال نهار كُلىهُ .\n6 اُذْكُرْ ، يا ربُّ ، رأفتركر ،\nومراحْهركر ، لأنْىا ثابتةٌ منذُ الأزله .\n7 خطايا شبابي وجهالاتهى لا تذكُرْ\nكرحْْتهكر اُذْكُرْني أنت\nمن أجل صلاحهكر ، يا ربُّ .\n8 صالهحٌ ومستقيمٌ هو الرب\nلذلكر يضعُ ناموساً للذينر يَُطئونر في الطريقه .\n\n9 يـُهْدهى الودعاءر في الحُكْمه ،\nيـُعرلِّمُ الودعاءر طُرُقرهُ .\n11 جميع سُبُله الربّ رحْْةٌ وحرق\nللذين يبتغون عرهْدرهُ وشهاداته .\n11 من أجله اسْْهكر يا ربُّ ،\nأنت تغفرُ لي خطيئتي لأنْىا كثيرةٌ .\n12 من هو الإنس انُ الخايفُ الربّ ؟\nيضعُ له ناموساً في الطريقه التي ارتضاها\n13 نفسُهُ في الخيرْاته تثبتُ ،\nونسلُهُ يرثُ الأرضر .\n14 الربُّ عزٌّ لخهايفيه ، واسمُ الربّ لأتقيايه ،\nولهرم يـُعْلهنُ عرهْدرهُ .\n15 عيناىر تنظرانه إلى الربّ في كلِّ حينٍ ،\nلأنه َر تذبُ من الفخِّ رهجْلرىى .\n16 اُنْظُرْ إلِرى وارحْرْني ،\nلأني ابنٌ وحيدٌ أنا ومسكينٌ .\n17 أحزانُ قلبِه قد كثـُرتْ ،\nأرخْرهجْني من شدايدى .\n18 اُنْظُرْ إلى تواضعى وتـرعربِه ،\n\nواغْفهرْ لي جميع خطاياىر .\n19 اُنْظُرْ إلى أعدايى ، فإنْىم قد كثُروا ،\nوأبغضوني ظُلْماً .\n21 اهحْفرظْ نفسي ونجرِّني\nلا تردرعْني أرخْزرى ، لأني عليكر توكىلتُ .\n21 الذين لا شرى فيهم والمستقيمونر لصقوا بي ،\nلأني انتظرتُكر ، يا ربُّ .\n22 يا اللهُ ، أرنْقهذْ إسراييلر من جميع شدايده .", "25": "المزمورُ الخامسُ والعشرونَ\nلداوده\n1 اُحْكُمْ لي ، يا ربُّ ، فإنِِّ بهدهعرتَّه سرلركرتُ ،\nوعلى الربّ توكىلتُ فلا أضعفُ .\n2 جرِّبْني ، يا ربُّ ، وامترحهنِِّ ،\nنرقِّ كما بنارٍ قلبِه وكُلْيرتَّرى .\n3 لأنى رحْْتركر أمامر عينِرى هى ،\nوقد ارتضيتُ بَهقِّ كر .\n4 لم أجلسْ مع مُرفلٍ باطلٍ ،\nومع مُُالهفي الناموس لم أدخل .\n\n5 أبغضتُ مَرمعر الأشراره ،\nومع المنافقين لم أجلسْ .\n6 أغسلُ يدرىى بالنقاوةه ،\nوأطوفُ بِهذبَرهكر ، يا ربُّ\n7 لكى ما أسْْرعر صوتر تسبحتهكر ،\nوأتكلىمر بِهميع عجايبك .\n8 يا ربُّ ، أحببتُ جَرالر بيتهكر ،\nوموضهعر مسكنه مَردهكر .\n9 لا تـُهْلهكْ مع المنافقين نفسي\nولا مع رهجاله الدماء حياتهى\n11 الذين في أيديهم الإثُُْ ،\nويَرينُهم امتلأتْ رهشوةً .\n11 أما أنا فبهدهعرتَّه سرلركْتُ\nأرنْقهذْني وارحْرْني .\n12 لأن رهجْلرىى ورقـرفرتْ في الاستقامةه\nفي الكنايس أًباركُكر ، يا ربُّ .", "26": "المزمورُ السادسُ والعشرون\nلداود ، قـربْلر أن يَُْسرحر\n1 الربُّ نورى وخلاصى ، فرمن أخافُ ؟\nالربُّ عاضدُ حياتهى ، مَهىنْ أرتعبُ ؟\n2 عند اقتَهابه الأشراره منِِّ ليأكل وا لحرْمى ،\nمُضايقىى وأعدايى هم ضعفوا وسقطوا .\n3 إنْ يُُاربُني جيشٌ فلرنْ يَرافر قلبِه ،\nوإنْ قامر علىى قتالٌ ، ففي هذا أنا أطْمرئهنُ .\n4 واحدةً سألتُ من الربّ ، وإياها ألتمسُ\nأن أرسْكُنر في بيته الربّ كلى أيامه حياتهى .\nلكى أنظر نعيمر الربّ ،\nوأتفرىسر في هيكله المقدىس .\n5 لأنه أخفاني في خيمته في يومه شدىتهى\nستـرني بهسهتَْه مهظرلىته ،\nعلى صخرةٍ رهفـرعرني .\n6 والآن ، هو ذا قد رفرعر رأسي على أعدايى\nطُفْتُ وذبَرتُ في مهظرلىته ذبيحةر التهليل ،\nأُسربِّحُ وأُرتِّلُ للربِّ .\n7 استرمعْ ، يا ربُّ ، صوتي الذي به صرخت\n\n8 ارحمني واستجبْ لي ، أنت الذي لكر قال قلبِه .\nطلبتُ وجهكر\nلوجهكر ، يا ربُّ ، ألترمسُ .\n9 لا تصرفْ وجهكر عنِِّ ،\nلا ترهلْ عن عبدهكر بغضبٍ\nكُنْ لي مُعيناً ، لا تُرْذه لْني\nولا تـرْفُضْني ، يا الله مُُلِّصى .\n11 فإنى أبي وأمي قد تركاني ،\nوأما الربُّ فقد قربهلرني .\n11 ضرعْ لي ، يا ربُّ ، ناموساً في سُبُلهكر ،\nواهْدهني في سبيلٍ مستقيمٍ من أجل أعدايى .\n12 لا تُسرلِّمْني إلى أنفسه الذين يُضايقونرني ،\nلأنه قد قامتْ علىى شهاداتُ ظُلْمٍ ،\nوكرذهبر الظُلْمُ لهذاته .\n13 وأنا أو منُ أنِِّ أُعايهنُ خيرْاته الربّ في أرضه الأحياءه .\n14 اهنـْترظهره الربّ\nتـرقروى ، وليتشدىدْ قلبُكر ، واهنـْترظهره الربّ .", "27": "المزمورُ السابعُ والعشرونَ\nلداود\n1 إليك يا ربُّ صرخت ،\nإلهي ، لا تسكتْ عنِِّ\nلئلاى تسكتر عنِِّ فأُشابهر الهابطينر في الُِبِّ .\n2 استرمعْ يا ربُّ صوتر تضرُّعى إذْ أبتهلُ إليك ،\nعندما أرفعُ يدرىى إلى هيكلهكر المقدىسه .\n3 لا تَّرْذهبْ نـرفْسى مع الخطاة ،\nولا تـُهْلهكْني مع ف اعهلهى الإثُْه ،\nالذين يتكلىمون بالسلام مع أصحابِهم ،\nوالشرورُ في قلوبِهم .\n4 أرعْطهم حسب أعمالهم ،\nومثلر خُبْثه صنايعهم\nأرعْطهم كأعماله أيديهم ،\nأرعْطهم مَُازاةر أفعالهم .\n5 لأنْىم لم يفهموا أعمال الربّ ،\nولا صنايعر يدريْه ،\nتـر هْدهمُهُمْ ولا تـربْنهيهم .\n6 مُباركٌ الربُّ الإلهُ ، لأنه سْرهعر صوتر تضرُّعى .\n\n7 الربُّ هو مُعيني وناصري\nعليه اهتىكرلر قلبِه ، فأعانرني ،\nوله أرزْهر جسدى\nوبإرادتهى أرعتَرفُ له .\n8 الربُّ عزٌّ لهشعبه ،\nوهو مؤازرُ خلاصه مسيحه .\n9 خرلِّصْ شعبركر وباركْ ميراثركر ،\nوارْعرهُمْ وارفـرعْهم إلى الأبد .", "28": "المزمورُ الثامنُ والعشرونَ\nمزمورٌ لداود عن الخروج من المهظرلىةه\n1 قردِّموا للربِّ ، يا أبناء الله ،\nقردِّموا للربِّ ، أبناء الكباشه\nقردِّموا للربِّ مَرداً وكرامةً ،\n2 قردِّموا للربِّ مَرداً لاسْْه\nاسجُدُوا للربِّ في داره قدسه .\n3 صوتُ الربّ على المياه ،\nإلهُ المرجده أرْعردر ،\nالربُّ على المياه الكثيرةه .\n\n4 صوتُ الربّ بقوىةٍ ،\nصوتُ الربّ بِهلالٍ عظيمٍ .\n5 صوتُ الربّ يُُرطِّمُ الأرْ زر\nالربُّ يكسهرُ أرْزر لبنانر ،\n6 ويسحقُها مثلر عهجْله لبنانر\nوالحبيبر مثلر ابنه وحيده القرنه .\n7 صوتُ الربّ يقطعُ لهيبر الناره .\n8 صوتُ الربّ يُزلزلُ القرفْر ،\nالربُّ يُزلزلُ برِّيةر قادشر .\n9 صوتُ الربّ يُرتِّبُ الأيايلر ،\nويكشفُ الغابا ته\nوفي هيكله المقدىس كلُّ واحدٍ ينطقُ بالمرجده .\n11 الربُّ يسكُنُ في الطوفانه\nوَرلهسُ الربُّ مرلهكاً إلى الأبده .\n11 الربُّ يُعطى شعبرهُ قوىةً ،\nالربُّ يباركُ شعبرهُ بالسلامه .", "29": "المزمورُ التاسعُ والعشرونَ\nإلى النهاية مزمورٌ تسبحةُ تدشينه البيته ، لداود\n2 أُعظِّمُكر ، يا ربُّ ، لأنك احتضرنترني ،\nولم تُشْمهتْ بي أعدايى .\n3 أيُها الربُّ إلهي ، صرخت إليك فشفيترني\n4 يا ربُّ ، أرصْعردْتر من الِحيمه نفسي ،\nخرلىصْترني من الهابطينر في الُِبِّ .\n5 رتِّلوا للربِّ ، يا جميع قدِّيسيه ،\nواعتَرفوا لهذهكْره قدسه .\n6 لأنى سُخْطاً في غضبه ،\nوحياةً في رهضاه\nفي المساءه يُرهلُّ البكاءُ ،\nوفي الصباحه السرورُ .\n7 أنا قـُلْتُ في نعيمهى لا أترزعزعُ إلى الدهره .\n8 يا ربُّ ، بِهسرىتهكر أرعْطريْتر جَرالي قوىةً\nصر فتر وجهكر عنِِّ ، فصرتُ قرلهقاً .\n9 إليك يا ربُّ أصرخُ ،\nوإلى إلهي أتضرعُ .\n11 أيىةُ منفعةٍ في دمى إذا هبطتُ إلى الهلاكه ؟\n\nهل يعتَرفُ لكر التَُابُ ،\nأو يَُْبِهُ بَهرقِّكر ؟\n11 سْرهعر الربُّ ، فـرحْهرني ،\nالربُّ صار لي عروْ ناً .\n12 حروىلْتر نوحى إلى فـرحٍ لي ،\nمرزىقْتر مهسْحى ومنطرقْترني سُروراً ،\n13 لكى يُرتِّلر لكر مجدي ، ولا يُرزنُ قلبِه .\nأيُها الربُّ إلهي ، إلى الأبده أعتَرفُ لكر .", "30": "المزمورُ الثلاثونَ\nإلى النهاية مزمورٌ لداود ، في الدرهرشه\n2 عليكر ، يا ربُّ ، توكىلتُ ، فلا تُُْزهني إلى الأبده\nبهعردْلهكر نجرِّني وأرنْقهذْني .\n3 أرمهلْ إلِرى أُذنركر ،\nأرسْرهعْ إلى خلاصى\nكُنْ لي إلهراً ناصراً ،\nوبيتر ملجأٍ لتُخلِّصرني .\n4 لأنك أنت هو قوىتهى وملجأى ،\nمن أجل اسْْهكر تـرهْديني وتعولُني .\n\n5 تُُْرهجُني من هذا الفخِّ الذي أخفوه لي ،\nلأنك أنت هو ناصري .\n6 في يدريْكر أستودعُ روحى\nفردريـْترني ، يا ربُّ إلهر الحقِّ .\n7 أبغضتر الذين يُرفظونر أباطيلر كاذبةً\nأما أنا فعليكر يا ربُّ توكىلتُ .\n8 أتـرهرلىلُ وأفرحُ برحْْته كر ،\nلأنك نظرتر إلى تواضعى ،\nوخلىصتر من الشدايده نفسي\n9 ولم تُربسْني في يده العدوِّ ،\nأقرمْتر في السهعرةه رهجْلرىى .\n11 ارحْرْني ، يا ربُّ ، فإنِِّ حزينٌ\nتعكىرتْ من الغضبه عريـْنِرى ،\nونفسي وبطني .\n11 لأنى حياتهى قد فنيتْ بوجعه القل به ،\nوسنيني بالتنهُّده\nضرعُفرتْ بالمسكنةه قوىتهى ،\nوعظامى اضطربرتْ .\n12 صهرْتُ عاراً بـرينْر جميع أعدايى ،\n\nوبالأكثره لِهيراني ،\nوخروْفاً لهمعارفىه\nالذين رأوني خارجاً هربوا عنِِّ\n13 نُسهيتُ من قلبهم مثلر الميِّته ،\nصهرْ تُ مثلر إناءٍ قد ترلهفر .\n14 لأني سْرْعْتُ المرذمىةر من كثيرينر يسكنون حولِه\nحينر اجتمعوا معاً عليّ ،\nتآمروا أنْ يأخُذوا نفسي .\n15 أما أنا ، يا ربُّ ، فعليكر توكىلتُ\nقـُلْتُ إنكر أنت إلهي .\n16 في يدريْكر أرنْصهبرتَّه\nنجرِّني من أيدى أعدايى ،\nومن الذين يطردونرني .\n17 لهيُنهرْ وجهُكر على عبدهكر ،\nخرلِّصْني برحْْتهكر .\n18 يا ربُّ ، لا تُُْزهني ، لأني دعوتُكر\nلهيرخْزر المنافقون ويُساقونر إلى الِحيمه .\n19 لهترصهرْ خرساءر الشفاهُ الغاشىةُ ،\nالمتكلِّمةُ على الصدِّيقه بالإثم ،\n\nبكبِياءر وتعييرٍ.\n21 ما أعظرمر كثْرةر صلاحهكر ، يا ربُّ ،\nالذي ذرخرْترهُ لخهايفيكر\nوصنعتره للمتىكلينر عليكر ،\nأمامر بني البشر .\n21 تُُْفيهم في خفاءه وجهكر\nمن مضايقةه الناسه\nتُظلِّلُهم في مهظلىتهكر من مقاومةه الشعوبه .\n22 مباركٌ الربُّ ، لأنه جعلرهم يتعجىبونر من رحْْته\nفي مدينةٍ حصينةٍ .\n23 أما أنا فقُلْتُ في درهْشتَّه\nإنِِّ قد طُرهحْتُ من قُدىامه عينـريْكر\nمن أجل هذا سْرهعْتر ، يا ربُّ ،\nصوتر تضرُّعى إذ صرخت إليك .\n24 أحهبُّوا الربّ ، يا جَريع قدِّيسيه ،\nلأنى الربّ يطلبُ الحق ،\nوَُازى الذين يعملون بكبِهياءر مُفْرهطٍ .\n25 تعزُّوا وليتشدىدْ قلبُكم ،\nيا جميع المتوكلين على الربّ .", "31": "المزمورُ الحادى والثلاثونَ\nفـرهْمٌ لداود\n1 طوباهُم الذين غُفهرتْ لهرم أثامُهم ،\nوالذين سُتَهر تْ خطاياهُم .\n2 طوبى للرجل الذي لم يُرسهبْ له الربُّ خطيئةً ،\nوليس في فمه غهشٌّ .\n3 لأني أنا سركرتُّ ، فبرلهيرتْ عظامى\nمن صُراخى اليوم كلىهُ .\n4 لأنى يدركر ثـرقُلرتْ علىى نْراراً وليلاً ،\nرجعتُ إلى الشقاءه عندما انغرسته الأشواكُ فىهى . سلام .\n5 أظهرتُ خطيئتي ،\nولم أكتُمْ إثمي\nقـُلْتُ أعتَرفُ بإثمي قُدىامر الربّ ،\nوأنت صفحتر لي عن نفاقاته قلبِه . سلام .\n6 وعلى هذه يُصلِّى إليك كلُّ القدِّيسينر في زمانٍ مستقيمٍ\nبل في طوفانه مياهٍ كثيرةٍ لا يقتربون إليك .\n7 أنت ملجأ ى من الضيقه المُحيطه بَه\nيا فرحى ، أرنْقهذْني من المحيطين بي . سلام .\n8 أُفـرهِّمُكر وأُعرلِّمُكر الطريق التي تسلُكُ فيها ،\n\nوأُثـربِّتُ عريـْنِرى عليكر .\n9 لا تكونوا كالفرسه والبغله اللذريْن لا فـرهْمر لهرما\nبلجامٍ وزمامٍ تركْ برحُ فكوكر الذين لا يدنونر إليك .\n11 كثيرةٌ هى ضرباتُ الخطاة ،\nأما الذي يتىكهلُ على الربّ فالرحْْةُ تُُيطُ به .\n11 اهفرحوا بالربّ وابتهجوا ، أيُها الصدِّيقونر\nوافتخروا ، يا جَريع مستقيمى القلوبه .", "32": "المزمورُ الثانِى والثلاثونَ\nلداود\n1 ابتهجوا ، أيُها الصدِّيقونر ، بالربّ\nبالمستقيمينر يليقُ التسبيحُ .\n2 اعتَرفوا للربِّ بقيثارةٍ ،\nوبكنىارةٍ ذاته عرشْرةه أوتارٍ رتِّلوا له\n3 سبِّحوه تسبيحاً جديداً ،\nرتِّلوا له حرسرناً بتهليلٍ .\n4 لأنى كلمةر الربّ مستقيمةٌ ،\nوكلى أعماله بالأ مانةه\n5 يُُهبُّ الرحْْةر والحُكْمر ،\n\nالأرضُ مَُتلئةٌ من رحْْةه الرب .\n6 بكلمةه الربّ تشدىدرته السماواتُ ،\nوبهروحه فهيه كلُّ قوىاتُها\n7 الذي َرمعُ مياهر البحره كأنْىا في زهقٍّ ،\nومجّد الأعماقر في خزاينر .\n8 فـرلْترترقه الربّ كلُّ الأرض ،\nولْتـرْترعهدْ منه كلُّ سُكانه المسكونةه .\n9 لأنه هو قال ، فكانوا\nوهو أرمر ، فرخُلهقُوا .\n11 الربُّ يُشرتِّتُ آراءر الأُمرمه ،\nويـرُدُّ أفكار الشعوبه ،\nويـُبْطهلُ مؤامرةر الرؤساءه .\n11 أما رأىُ الربّ فهو يدومُ إلى الأبده ،\nوأفكارُ قلبه من جيلٍ إلى جيلٍ .\n12 طوبى للأُمىةه التي الربُّ إلهرُها ،\nالشعبُ الذي اختارهُ ميراثاً له .\n13 نرظر الربُّ من السماء ،\nفرأى جميع بني البشر\n14 من مسكنه المُهريىأ\n\nتطلىعر إلى جَريع سُكانه الأرض ،\n15 الذي هو وحدره خرلرقر قلوبِرم ،\nالذي يفهمُ جميع أعمالهم .\n16 لا يَرْلُصُ مرلهكٌ من أجله عهظرمه القوىةه ،\nولا ينجو جربىارٌ بكثرة جربِروته\n17 باطلٌ هو الفرسُ للخلاصه ،\nوبكثرة قوّته لا يـُنرجِّى .\n18 هوذا عريْنا الربّ على خايفهيه ،\nوالرىاجينر رحْْترهُ ،\n19 ليـُنرجِّىر من الموته أنفسرهم ،\nويعولهرم في المرجاعةه .\n21 نـرفْسُنا تنتظرُ الربّ في كلِّ حينٍ ،\nلأنه هو مُعينُنا وناصرُنا\n21 وبه يفرحُ قلبُنا ،\nلأننا على اسْْه القُدُّوسه اتىكلْنا .\n22 فلْتركُنْ رحْْتُكر ، يا ربُّ ، علينا ،\nكرمه ثْله اتِّكالهنا عليكر .", "33": "المزمورُ الثالثُ والثلاثونَ\nلداود ،\nعندما غريـىر وجههُ قُدىامر أبيمالكر ، وأطلقرهُ فمضرى .\n2 أُباركُ الربّ في كلِّ وقتٍ ،\nوفي كلِّ حينٍ تسبحتُهُ في فمى .\n3 بالربّ تفتخرُ نفسي\nليرسْمرعر الودعاءُ ويفرحونر .\n4 عرظِّمواالربّ معى ،\nولْنـرْفرعْ اسْْرهُ جَريعاً .\n5 طلبتُ الربّ ، فاستجاب لي ،\nومن جميع مساكني نجرىاني .\n6 تقدىموا إليه واستنيروا ،\nووجوهُكم لا تُرْزرى .\n7 هذا المسكينُ صرخر ، فاسْترمعرهُ الربُّ ،\nومن جَريع أحزانه خرلىصرهُ .\n8 يـُعرسْكهرُ ملاكُ الربّ حولر جميع خايفهيه ويـُنرجِّيهم .\n9 ذوقوا وانظروا ما أطيبر الرب !\nطوبى للإنسان المتىكهله عليه .\n11 اتىقوا الربّ يا جميع قدِّيسيه ،\n\nفإنى الذين يتىقونرهُ لا يـُعْوهزُهم ش ىءٌ .\n11 الأغنياءُ افتقروا وجاعوا ،\nأما الذين يبتغون الربّ فلا يـرعْدرمونر خريرْاً . سلام .\n12 هلُمى ، أيُها الأبناءُ ، اسْْعوني ،\nلأُعرلِّمركم مُرافةر الربّ .\n13 من هو الإنسان الذي يُريدُ أن يُريا ،\nويُُهبُّ أنْ يـرى أياماً صالحهةً ؟\n14 صُنْ لهسانركر عن الشرِّ ،\nوشرفرتـريْ كر عن النُطْقه بالغهشِّ\n15 حهدْ عن الشرِّ واصْنرعه الخريـْر ،\nاُ طْلُبه السلامةر واتـْبـرعْها .\n16 فإنى عيـْنِره الربّ على الصديقين ،\nوأُذُنـريْه مُصْغيتانه إلى طلبتهم .\n17 أما ورجْهُ الربّ فعلرى الذين يعملونر الشر ،\nلهيرمْحُور من الأرض ذه كْرهم .\n18 الصدِّيقونر صرخوا ، والربُّ استجاب لهرم ،\nومن جميع شدايدهم نجرىاهُم .\n19 قريبٌ هو الربُّ من المنسحقى القلب ،\nويَُرلِّصُ المتواضعينر بالروحه .\n\n21 كثيرةٌ هى أحزانُ الصدِّيقين ،\nومن جميعها يـُنرجِّيهم الربُّ .\n21 يُرْفرظُ الربُّ جميع عهظامهم ،\nواحدةٌ منها لا تنكسرُ .\n22 موتُ الخطاة شرِّيرٌ ،\nومُبْغضو الصدِّيقه سيندمونر .\n23 الربُّ يَُرلِّصُ نفوسر عبيده ،\nولا يـرنْدرمُ جميع المتوكلين عليه .", "34": "المزمورُ الرابعُ والثلاثونَ\nلداود\n1 دهنْ ، يا ربُ ، الذين يرظلمونرني ،\nوقاتهله الذين يُقاتهلونرني\n2 خُذْ سلاحاً وتـُرْساً ، وانـْهرضْ إلى معونتَّه\n3 استلى سيفركر وسيِّجْ مُقابهلر الذين يضطهدونرني\nقُلْ لنفسي إنِِّ أنا هو خلاصُكه .\n4 فلْيرخْزر ويَرجلْ جميع الذين يطلبون نفسي ،\nولْيـرْتردى إلى الوراءه ويَرْزر الذين يتآمرونر عليّ بالسوءه .\n5 ليكونوا مثلر الهباءه أمامر وجه الريحه ،\n\nوملاكُ الربّ يُضايقُهم .\n6 لتكنْ طريقُهم ظُلْمرةً وعرثـْرةً ،\nوملاكُ الربّ يُطاردُهم .\n7 لأنْىم بلا سببٍ أخفوا لي هلاكر فرخِّهم ،\nوعيرىوا ن فسى باطلًا .\n8 فلْيرأتُهم الفخُّ الذي لا يرعلمونره ،\nوالمصيدةُ التي أخفوها تـُعرقلُهم ،\nوفي الفخِّ يسقطونر .\n9 أما نفسي فتفرحُ بالربّ ،\nوتبتهجُ بِهلاصه .\n11 جميع عظامى تقولُ ، يا ربُّ ، من مهثـْلُكر ؟\nالمُنْقهذُ المسكينر من يدرىه من هو أ قورى منه ،\nوالفقير والبايسر من الذين يَرتطفونرهُ .\n11 قامر عليّ شُهودُ زورٍ وعرمىا لا أعلمُ كانوا يسألونرني\n12 جازوني بدلر الخيرْاته شُروراً ،\nوعُقْماً لنفسي\n13 وأنا إذ كانوا يُعاندونرني لبستُ مهسْحاً ،\nوأذلرلْتُ بالصومه نفسي ،\nوصلاتي إلى حضني ترجعُ .\n\n14 ومثل صاحبٍ وأخٍ هكذا كُنْتُ أُرْضيه\nومثل النايحه والحزينه هكذا أذلرلْتُ نفسي .\n15 لكنهم فرحوا فىهى واجتمعوا ،\nاجتمعرتْ عليّ السياطُ ولم أعلمْ ،\nتفرىقوا ولم يندموا .\n16 جرىبوني ، واستهزأوا بي هُزْءاً ،\nوصرُّوا عليّ بأسنانْهم .\n17 يا ربُ ، متى تنظرُ ؟\nرُدى نفسي من شرِّ فهعْلهم ،\nومن بـرينْه الأُسُده بهنـُوىتهى الوحيدةر .\n18 أعتَرفُ لكر يا ربُّ ، في جَراعةٍ كثيرةٍ ،\nوفي شعبٍ عظيمٍ أُسربِّحُكر .\n19 لا يرشْمرتْ بي الذين يُعادونرني ظُلْماً ،\nالذين يـُبْغضونرني مَرىاناً ويتغامزونر بالأعينُهٍه .\n21 لأنْىم كانوا يتكلىمونر معى بكلماته سلامٍ ،\nوبهغهشِّ تفكىروا في الغضبه\n21 فـرغروا عليّ أفواهرهُمْ ،\nوقالوا نهعهمى ا نهعهمى ا ، قد رأتْ أعينُنا .\n22 قد رأيتر ، يا ربُّ ، فلا ترصْمهتْ\n\nيا ربُّ ، لا تبتعدْ ع .\n23 استيقظْ ، يا ربُّ ، وانْظُرْ إلى حُكْمى ،\nوإلى دعواىر ، يا ربَِّ وإلهي .\n24 أقضه لي حسب عردْلهكر ، يا ربُّ إلهي ،\nفلا يرشْمرتُو ا بي .\n25 ولا يقولوا في قلوبِهم نهعهمى ا نهعهمى ا لأنفسنا\nولا يقولو ا قد ابتلعناه .\n26 ليرخْزر ويَرجلْ معاً الذين يفرحونر بِهضرىاتهى\nليلْبرسه الخهزْىر والعار الذين يتعظىمونر عليّ بكلامهم .\n27 ليبتهجْ ويفرحه الذين يريدونر برّي ،\nوليقولوا في كلِّ حينٍ ليتعظىمه الربُّ ،\nالذين يريدونر السلامةر لهعبدكر .\n28 لساني يـرلْهرجُ بهعردْلهكر ،\nواليوم كلىهُ بَهرمْدهكر .", "35": "المزمورُ الخامسُ والثلاثونَ\nإلى النهاية لفتَّر الربّ داود\n2 يقولُ مُُالهفُ الناموسه إنىني أُخطئُ في نفسي ،\nليس خوفُ الله أمامر عينـريْه\n\n3 لأنه صرنرعر الغهشى قُدىامر هُ ،\nلكى يظفر بإثَْه ويـُبْغهضر .\n4 كلامُ فمه إثٌُْ وغهشٌّ ،\nلم يُرهدْ أنْ يفهرمر لكى يعملر الخيـْر .\n5 فركىر إثَْاً على مضجعه ،\nورقرفر في كلِّ طريقٍ غيرْه صالهحٍ ،\nوعن الشرِّ لم يـُعْرهضْ .\n6 يا ربُّ ، في السماء رحْْتُكر ،\nوحقُّكر إلى السحابه\n7 وعدلُكر مثلُ جباله الله ،\nأحكامُكر مثلُ العُمْقه العظيمه .\nالناسر والبهايمر تُُلِّصُهُم ، يا ربُّ .\n8 مثلما أكثرتر رحْْتركر يا اللهُ\nبنو البشر في ظهلِّ جناحيْكر يتىكلونر .\n9 من درسرمه بيتهكر يرسْكرونر ،\nومن نْره نعيمهكر تُرويهم .\n11 لأنى عندكر ينبوعر الحياةه ،\nبنورهكر نُعاينُ النور .\n11 اهبْسهطْ رحْْتركر على الذين يعرفونركر ،\n\nوعدلركر على المستقيمى القلوبه .\n12 لا تَّرعلْ رهجْلر الكبِْياءه تأتيني ،\nولا تردرعْ يدر الخُطاةه تُزحزحُني .\n13 هناكر سرقرطر جَر يعُ عاملى الإثُْر ،\nدُفهعُوا فلم يستطيعوا القيامر .", "36": "المزمورُ السادسُ والثلاثونَ\nلداود\n1 لا تـرغرْ مهنْ فاعلى الشرِّ ،\nولا تُرْسهده الذين يعملونر الإثُْر\n2 فإنْىم مثلر العُشْبه سريعاً َرهفُّونر ،\nومثلر البقوله الخضراءه يسقطونر .\n3 اهتىكهلْ على الربّ واصْنرعه الخريـْر ،\nواسْكُنْ على الأرض ،\nفتـرْعرى في غناها .\n4 اهفرهحْ بالربّ ، فيُعطيركر مطلوباته قلبك ،\n5 اهكشفْ للربِّ طريقكر ،\nواتىكهلْ عليه ، وهو َُْرهى\n6 ويَُْرهجُ مثلر النوره بهرىكر ،\n\nومثلر الظهيرة أحكامركر .\n7 اهخضرعْ للربِّ وتضرىعْ إليه\nلا تـرغرْ من الذي طريقُهُ ناجهحرةٌ في حياته ،\nمن إنسانٍ يصنعُ الإثُْر .\n8 كُفي عن الرهجْزه ، واتـْرُكه الغضبر ،\nلا تـرغرْ لئلاى تفعلر الشر .\n9 لأنى عاملى الشرِّ يُقطرعونر ،\nأما الذين ينتظرونر الربّ هم يرثونر الأرضر .\n11 عن قليلٍ لا يُوجردُ الخاطئُ ،\nتـرلْترمهسُ مكانرهُ فلا تَّرهدُهُ\n11 أما الودعاءُ فيرثونر الأرضر ،\nويـرتـرنـرعىمونر بكثْرةه السلامه .\n12 الخاطئُ يـرْصُدُ الصدِّيقر ،\nويُصهرُّ عليه بأسنانه\n13 والربُّ يضحكُ به ،\nلأنه سربرقر فرأر ى أنى يومره آتٍ .\n14 استلى الخطاة سيفرهم ،\nوأوتروا قوسرهم ،\nليصرعوا المسكينر والفقير ،\n\nويذبَروا المستقيمى القلب .\n15 سريـْفُهم يدخلُ في قلبهم ،\nوقهسيُّهم تنكسرُ .\n16 القليلُ الذي للصهدِّيقه خريـْرٌ من غهنِر كثيرٍ للخطاةه .\n17 لأنى سواعدر الخطاة تنكسرُ ،\nأما الصهدِّيقونر فالربُّ يـرعْضُدُهم .\n18 الربُّ يعرفُ طريق الذين لا عريْبر فيهم ،\nوميراثُهم إلى الأبده يكونُ\n19 لا يَرْزروْنر في زمنه السوءه ،\nوفي أيامه الِوعه يشبرعونر .\n21 لأنى الخطاةر يـرهْلركونر ،\nوأعداءُ الربّ ف يما هم يتمجىدونر ويرتفعونر\nفرنوا فناءً مثلر الدُخانه إذا فرنِهر .\n21 يقتَضُ الخاطئُ ولا يُوفىه .\nأما الصهدِّيقُ فيتَأفيُ ويُعطى .\n22 لأنى الذين يُباركونره يرثونر الأرضر ،\nأما الذين يلعنونرهُ فيُبادونر .\n23 من قهبرله الربّ تستقيمُ خطواته ا نسانه ،\nوفي طريقه يُسرُّ\n\n24 إذا سرقرطر لا يضطربُ ،\nلأنى الربّ يسندُ يدرهُ .\n25 كنتُ شابّاً وقد شهخْتُ ،\nولم أر صهدِّيقاً تُرلىى الربُّ عرنْهُ ،\nولا ذرِّيةً له تـرلْترمهسُ خُبْزاً .\n26 النهار كلىهُ يرحرمُ ويُقرضُ ،\nونسلُهُ أيضاً يكونُ مُباركاً .\n27 حهدْ عن الشرِّ واصْنرعه الخريـْر ،\nواسْكُنْ إلى دهره الدهره .\n28 لأنى الربّ يُُبُّ الحُكْمر ،\nولا يتخلىى عن قدِّيسيه ،\nإلى أبده الأبده يُرفظُهم\nالذين بلا عريْبٍ يأخذونر انتقامرهم ،\nونسلُ المنافقين يربيدُ .\n29 أما الصهدِّيقونر فإنْىم يرثونر الأرضر ،\nويسكنونر فيها إلى دهره الدهره .\n31 فرمُ الصهدِّيقه يتلو الحهكْمةر ،\nولسانُهُ ينطقُ بالحُكْمه\n31 ناموسه الله في قلبه ،\n\nوخرطرواتُهُ لا تتقلقلُ .\n32 الخاطئُ يُراقهبُ الصهدِّيقر ، ويلتمسُ أن يقتلرهُ\n33 لكن الربّ لا يُبقيه في يدريْه ،\nولا يطرحُهُ في الحُكْمه إذا تقاضرى معه .\n34 انتظره الربّ واحفظْ طريقهُ ،\nفيرفعر كر لهتَرثر الأرضر ،\nوتُعايهنر الخطاةر حينر يُستأصرلونر .\n35 رأيتُ المنافقر يتزايدُ رهفـْعرةً ،\nويتعالِر مثلر أرزه لبنانر\n36 وجُزْتُ فإذ ليس هو\nوالترمستُهُ فلم أجدْ مكانرهُ .\n37 اهحْفرظه الدهعرةر ، وانْظُره الاستقامةر ،\nفإنى البقيةر ستكونُ للرجله المسالَه .\n38 أما مُُالفو الناموسه فيُبادونر معاً ،\nوبقيةُ المنافقين يُستأصلونر .\n39 خلاصُ الصهدِّيقينر من قهبرله الرب ،\nوهو ناصرهم في زمانه الضيقه\n41 ويُعينُهم الرب ، ويُنجِّيهم ،\nويُنقذُهم من الخطاة ويَُلِّصُهم ، لأنْىم توكىلوا عليه .", "37": "المزمورُ السابعُ والثلاثونَ\nمزمورٌ لداود تذكارٌ من أجله السبته\n2 يا ربُّ ، تُبكِّتُني بغضبك ،\nولا تُؤدِّبُني بسُخْطهكر .\n3 لأنى سهامركر قد انغرسرتْ فىهى ،\nواشتدىتْ يدُكر عليّ\n4 ليستْ في جسدى صحىةٌ من وجه غضبك ،\nولا سلامةٌ لهعظامى من وجه خطاياى .\n5 لأنى آثامى قد تعالرتْ فوقر رأسي ،\nمثلر حْهْلٍ ثقيلٍ قد ثـرقُلرتْ عليّ .\n6 قد نـرتـرنرتْ وقاحرتْ جهراحاتهى\nمن قهبرله جرهالرتَّه .\n7 شقيتُ وانُْنيْتُ إلى الانقضاء ،\nواليوم كلىهُ أمشى حزيناً\n8 لأنى نفسي قد امتلأرتْ مرهازئر ،\nوليسرتْ في جسدى صهحىةٌ .\n9 تعبتُ وتذلىلتُ جداً ،\nوكنتُ أيهنُّ من تنهُّده قلبِه .\n11 أمامركر هى كلُّ شهوتهى ،\n\nوتنهُّدى عنكر لم يَرْفر .\n11 قلبِه قد اضطربر ،\nوفارقـرتْني قوىتهى ،\nونورُ عينِرى ليسر معى .\n12 أصدقايى وجيراني اقتَربوا ووقفوا مُقابلى ،\nوأقاربي وقفوا بعيداً\n13 وأجهدرني الذين يطلبون نفسي ،\nوالمُلتمسونر لي السوءر تكلىموا بالأباطيل ،\nواليوم كلىهُ كانوا يلهجونر بالغشِّ .\n14 وأما أنا فكأرصرمى لا يسمعُ ،\nومه ثْ لر أرخْرسر لا يفتحُ فراهُ\n15 وصهرْتُ مه ثْ لر إنسانٍ لا يسمعُ ،\nوليسر في فمه تبكيتٌ .\n16 لأني عليكر يا ربُّ توكىلتُ\nأنت تستجيبُ ، يا ربُّ إلهي .\n17 لأني قـُلْتُ لئلاى يرشْمرتر بي أعدايى ،\nوعند زلله قدمرىى عظىموا الكلامر عليّ .\n18 أما أنا فمُستعدٌ للسياطه ،\nووجعى مُقابلى كلى حينٍ .\n\n19 أنىني أُخْبِهُ بإثمي ،\nوأرغترمُّ من أجله خطيىتَّه .\n21 وأما أعدايى فأحياءٌ وه م أشدُّ منِِّ ،\nوقد كرثـُر الذين يبغضونرني ظُلْماً .\n21 الذين جازوني عهورضر الخريرْاته شهروراً .\nافتَروا عليّ ، لأني كنتُ أرسعرى نُرور العدله .\n22 رفضوني أنا الحبيبر مثلر ميِّتٍ مرذولٍ ،\nومسامير جعلوا في جسدى .\nفلا تـُهْمهلْني ، يا ربَِّ وإ لهرى ،\nولا تتباعدْ عنِِّ\n23 اهلْترفهتْ إلى مرعونتَّه ياربى خلاصى .", "38": "المزمورُ الثامنُ والثلاثونَ\nإلى النهاية ، لإيديثونر ، تسبحةٌ لداود\n2 قـُلْتُ إنِِّ أحفظُ طريقى لكى لا أُخطئر إليك بلساني\nوضعتُ على فمى حافظاً\nإذْ ورقرفر الخاطئُ مُقابلى .\n3 صرمرمْتُ واتضعتُ وسكتُّ عن الخيرْاته ،\nفتجدىدر ورجرعى .\n\n4 حْرهىر قلبِه في باطني ،\nوفي هذيذى تتىقهدُ النارُ\n5 تكلىمتُ بلساني عرِّفْني ، يا ربُّ ، نْهايتَّه ،\nوعدردر أيامى كرمْ هى ،\nلكى أعلمر ماذا يُعوزني .\n6 هو ذا قد جعلتر أيامى باليةً ،\nوقـرورامى كرلار شئٍ أمامركر\nبل إنى كلى شئٍ باطلٌ لكلِّ إنسانٍ حىٍّ . سلام .\n7 إنِىا بالشبه يـرترمشىى الإنسانُ ،\nبل إنه باطلًا يضطربُ\nيَرْزهنُ ، ولا يدرى لهمن َرْمعُهُ .\n8 والآنر من هو انتظارى ؟ أليسر هو الربّ ؟\nوقهوامى هو مه ن قهبرله . سلام .\n9 طرهِّرني من جميع آثامى ،\nجعلترني عاراً للجاهله .\n11 صرمرمْتُ ولم أفتحْ فمى ، لأنك أنت صنعترني .\n11 اهنـْزرعْ سياطركر ع\nلأني من قوىةه يدهكر قد فنيتُ .\n12 أدىبْتر الإنسانر بالتوبيخاته من أجله الإثُْه ،\n\nوجعلتر نفسه تنحلُّ مثلر العنكبوته\nإنِىا باطلًا اضطربر كلُّ إنسانٍ . سلام .\n13 استمهعْ صلاتي وتضرُّعى ،\nوأرنْصهتْ لهدموعى .\nلاتسكتْ عنِِّ لأني أنا غريبٌ على الأرض\nومَُتازٌ ، مثلر جميع آبايى .\n14 اغفرْ لي لكيما أستَيحُ ،\nقبلر أنْ أذهبر فلا أُوجردُ بعدُ .", "39": "المزمورُ التاسعُ والثلاثونَ\nإلى النهاية مزمورٌ لداود\n2 انتظاراً انتظرتُ الربّ ، فأصغرى إلِرى\nوسْرهعر تضرُّعى\n3 وأرصْعردرني من جُبِّ الشقاءه\nومن طينه الحرمأةه ،\nوأقامر على الصخرةه رهجْلرىى ،\nوسرهىلر خرطرواتهى\n4 ومجّد في فمى تسبيحاً جديداً ،\nوسُبْحاً لإلهرنا\n\nكثيرون يرونر ويَرافونر ، ويتوكىلونر على الرب .\n5 طوبى للرجله الذي اسمُ الربّ رجاؤُهُ ،\nولم ينظرْ إلى الأباطيل والوساوسه الكاذبةه .\n6 وأنت ، أيُها الربُّ إلهي ، جعلتر عجايبركر كثيرةً ،\nوفي أفكارهكر ليس من يُشْبهُكر\nأخبِرتُ وتكلىمتُ ، كرثُروا أكثـر من العدده .\n7 ذبيحةً وقرباناً لم تُرهدْ ،\nولكن هيىأتر لي جسداً\nوالمُحرقاتُ التي من أجله الخطيئةه لم تُسرى بِها .\n8 حينئذٍ قـُلْتُ ها أنا آتهى ،\nفي درْجه الكتابه مركتوبٌ من أجلى\n9 سُرهرتُ أنْ أعملر مشيئتركر يا اللهُ ،\nوناموسُكر في وسطه بطني .\n11 بشىرتُ بعدلهكر في كنيسةٍ عظيمةٍ\nهو ذا لا أمنعُ شفتَّرى .\n11 أنت ، يا ربُّ ، قد عرٍه له مْتر برّي\nلم أكتُمْ عردْلركر في قلبِه ،\nوبِهلاصهكر تكلىمتُ\nورحْْتركر وحقىكر لم أرخْفهما عن مُرفلٍ عظيمٍ .\n\n12 وأنت أيُها الربُّ إلهي ، لا تبعدْ رأفاتهكر ع\nرحْْتُكر وحقُّكر هُُا اللذانه اقتبلاني في كلِّ حينٍ .\n13 لأنى شروراً لا تُُصرى قد أرحاطرتْ بي ،\nأردْركرتْني آثامٌ ، ولم أسترطهعْ أنْ أُبْصهر\nكرثـُرتْ أكثـر من شرعْره رأسي ،\nوقلبِه تـركرني .\n14 اهرْترضه ، يا ربُّ ، بأنْ تـُنرجِّيني\nيا ربُّ اهلْترفهتْ إلى معونتَّه .\n15 لهيرخْزر ويـُعريـىرْ جميع الذين يطلبون نفسي ليُبهيدوها\nيرتدْ إلى خلفٍ ويفتضحه الذين يلتمسونر لي الشرور .\n16 لهيـرنرلْ الخزىُ س ريعاً الذين يقولون لي نهعهمى ا نهعهمى ا .\n17 ليتهلىلْ ويفرحْ بك الذين يلتمسونركر ، يا ربُّ ،\nوليـرقُلْ في كلِّ حينٍ مُُبُّو خلاصهكر ،\nفليعظُمه الربُّ في كلِّ حينٍ .\n18 أما أنا فمسكينٌ وضعيفٌ ، الربُّ هو الذي يرهتم بَه\nمعيني وناصري أنت هو ، يا إلهي ، فلا تُبطئْ .", "40": "المزمورُ الأربعونَ\nإلى النهاية مزمورٌ لداود\n2 طوبى لهمن يتعطفيُ على المسكينه والفقيره ،\nفي يومه الشرِّ يُنجِّيه الربُّ .\n3 الربُّ يُرْفظُهُ ويُُيهيه ، وَرعلُهُ في الأرض مغب وطاً ،\nولا يُسرلِّمُهُ لأيدى أعدايه .\n4 الربُّ يُعينُهُ على سريره ورجرعه ،\nردردْتر مضجعرهُ كلىه في مرضه .\n5 أنا قـُلْتُ يا ربُّ ارْحْرْني\nاهشْفه نفسي ، لأني قد أخطأتُ إليك .\n6 أعدايى تقاولوا عليّ شرّاً ،\nمرتَّر يَروتُ ويربيدُ اسُْْهُ ؟\n7 كان يدخُلُ لينظر فكان يتكلىمُ باطلًا\nوقلبُهُ جَرعر له إثَْاً ،\n8 ثم كان يَرُجُ خارجاً ويتكلىمُ عليّ معهم .\nتردرمْدرمر عليّ جميع أعدايى\nوتشاوروا عليّ بالسوءه\n9 كلاماً مُُالهفاً للناموسه رتىبوا عليّ ،\nهل النايمُ لا يعودُ أنْ يقومر ؟\n\n11 وأنى إنسانر سلامتَّه الذي وثقتُ به ،\nالذي أركرلر خُبْزى رفرعر عليّ عرقهبرهُ .\n11 وأنت ، يا ربُّ ، ارحمني وأرقهمْني فأجازهيرهم .\n12 بِهذا عرلهمتُ أنكر سُرهرّتر بي ،\nلأنى عردُوِّى لن يرشْمرتر بي .\n13 وأنا فمن أجله دهعرتَّه قربهلْترني ،\nوثـربىتىني أمامركر إلى الأبده .\n14 مُباركٌ الربُّ إلهُ إسراييلر\nمن الأزله وإلى الأبده يكونُ ، يكونُ .", "41": "المزمورُ الحادى والأربعونَ\nإلى النهاية فـرهْمٌ لبني قورح\n2 كما يشتاقُ الإهيىلُ إلى ينابيعه المياه\nهكذا تشتاقُ نفسي أنْ تأتهىر إليك ، يا اللهُ .\n3 عطشرتْ نفسي إلى الله الحى\nمرتَّر أج ىءُ وأظهرُ أمامر وجه الله ؟\n4 صارتْ دموعى لي خُبْزاً نْراراً وليلاً ،\nفيما يقولون لي كلى يومٍ أينر هو إلهرُكر ؟\n5 هذه تذكىرتُُا فسركربْتُ نفسي عليّ\nلأنى ني سأجوزُ في مكانه مهظرلىةٍ عجيبةٍ إلى بيته الله ،\nبصوته التهليل والاعتَهافه ، صوته الذي يـُعريِّدُ .\n6 لماذا أنته حزينةٌ يا نفسي ، ولماذا تُزعجينرني ؟\nتوكىلى على الله ، فإنِِّ أعتَرفُ له\nخلاصُ وجهى هو إلهي .\n7 اضطربرتْ نفسي في ذاتهى\nلذلك أذكرُكر يا ربُّ في أرضه الأردنه وحرمونر ،\nمن الِبله الصغيره .\n8 العُمْقُ نادرى العُمْقر بصوته مريرازهيبك\nجميع أهوالهكر وأمواجهكر أرترتْ عليّ .\n\n9 بالنهار يأمُرُ الربُّ برحْْرته ، وبالليل يُظْهرُها\nعهندى صلاةٌ لإ لر ه حياتهى .\n11 أقولُ لله أنت هو ناصري ، لماذا نرسهيترني ؟\nولماذا تركْترني عرنْكر ؟\nلماذا أمشى كئيباً إذْ يُُزنُني عدوِّى ؟\n11 عهنْدر ترضيضه عظامى عريـىرني مُضايقهىى ،\nبقروْله م لي كلى يومٍ أينر هو إلهرُكر ؟\n12 لماذا تُرزنينر يا نف سى ، ولماذا تُزعجينرني ؟\nتوكىلى على الله ، فإنِِّ أعتَرفُ له\nخلاصُ وجهى هو إلهي .", "42": "المزمور الثانِى والأربعونَ\nمزمورٌ لداود\n1 اُحْكُمْ لي ، يا ربُّ ، وانتقمْ لهمرظْلرمتَّه من أُمىةٍ غريرْه بارىةٍ\nومن إنسانٍ ظالَهٍ وغاشٍّ نجرِّني .\n2 لأنك أنت هو إلهي وقوىتهى\nلماذا أقصيترني ؟\nولماذا أسلُكُ كئيباً من مُضايقةه عردُوِّى ؟\n3 أرْسهلْ نوركر وحقىكر\n\nفهما اللذانأرشرداني وأصعرداني إلى جربر له كر المُقدىسه\nوإلى مسكنهكر .\n4 فأدخُلر إلى مذبرحه الله ،\nتَّهاهر وجه الله الذي يـُفرِّحُ شبابَه\nأعتَرفُ لكر ، يا اللهُ إلهي ، بالقيثارةه .\n5 لماذا أنته حزينةٌ ، يا نفسي ، ولماذا تُزعجينرني ؟\nتـرجِّى الله ، فإنِِّ أعتَرفُ له\nخلاصُ وجهى هو إلهي .", "43": "المزمورُ الثالثُ والأربعونَ\nإلى النهاية مزمورٌ لهبني قورح للفرهْمه\n2 اللهُمى بآذانهنا قد سْرهعْنا ،\nوآباؤنا أخبِرونا ،\nبالعمله الذي عملترهُ في أيامهم ، في الأيامه الأولِر .\n3 يدُكر استأصرلرتْ أمَراً ، وغرسْترهم ،\nآلرمْتر شعوباً وطردْتُرم .\n4 لأنه ليس بسريْفه م ورثوا الأرضر ،\nولا ذراعُهم خرلى صرتـْهُ م\nلكن يَره ينركر وذراعركر ونور وجهكر ،\n\nلأنك سُرهرْتر بِه م .\n5 إنكر أنت هو مرلهكهى وإلهي ،\nالذي تأمرُ بِهلاصه يعقوب .\n6 بك نذبرحُ أعداءرنا ،\nوباسْْهكر ندوسُ كلى الذين يقومونر علينا .\n7 لأني لستُ أتىكهلُ على قـروْسى ،\nوسريْفي لرنْ يَُرلِّصرني\n8 لأنك أنت الذي خلىصْترنا من الذين يحزنوننا ،\nوأرخْزريْتر الذين يـُبْغضونرنا .\n9 بإلهرهنا نفتخرُ اليوم كلىهُ ،\nوباسْْهكر نعتَرفُ إلى الأبده . سلام .\n11 لكنكر الآنر قد أقصيْترنا عرنْكر وأرخْزريـْترنا ،\nولم تُرْ رُجْ معنا في قـُوىاتهنا .\n11 ردردترنا إلى الوراءه عن أعدايه نا ،\nومُبغضونا هُم الذين اهختطفونا لأنفسهم\n12 درفرعترنا مثلر الغنمه للأكله ،\nوشرتىتىنا في الأممه\n13 بهعْتر شعبر كر بلا ثَرنٍ ،\nولم يكُنْ الذي أُعْطهىر عليهم كثيرٌ .\n\n14 جرعلترنا عاراً لِهيرانهنا ،\nوهُزُؤاً وسُخريةً للذين حروْلرنا .\n15 جعلترنا مرثرلاً في الأممه ،\nوهرزى الرأسه في الشعوبه .\n16 اليوم كلىهُ خرجرلهى أمامي هو ،\nوخهزْىُ ورجهى قد غرطىاني ،\n17 من صوته المُعريرِّه والثالهبه ،\nومن ورجه عردُوٍّ يطردُني .\n18 هذه كُلُّها أرترتْ علينا ، وما نسيناكر ،\nولا غردرْنا بهعرهْدهكر\n19 ولم يرتردى قلبُنا إلى وراءٍ ،\nفمريـىلْتر خرطرواتهنا عن طريقهكر .\n21 لأنك أذلرلْترنا في مكانه الشقاءه ،\nوظهلى الموته الذي جرعرلْتره يـُغرطِّينا .\n21 إنْ كُنىا قد نرسريْن ا اسمر إلهرهنا ،\nوإنْ كُنىا برسرطْنا أيدهينا إلى إلهٍ غريبٍ ،\n22 أفليسر اللهُ هو المُطالبر بِهذه ؟\nلأنه هو الذي يعرفُ خفايا القلوبه .\n23 لأننا من أجلهكر نُِاتُ كلى النهاره ،\n\nقد حُسهبْنا ومثل غرنرمٍ للذبْحه .\n24 استيقظْ ، يا رب ، لماذا تنامُ ؟\nقُمْ ولا تـُقْصهنا عرنْكر إلى الانقضاءه .\n25 لماذا تصرفُ ورجهركر عرنىا ؟\nوقد نرسريْتر مسكنتر نا وضيقترنا ؟\n26 لأنى نفسرنا قد اتىضعرتْ حتَّى التَُابه ،\nولرصهقرتْ في الأرض بطنُنا .\n27 قُمْ ، يا ربُّ ، أرعهنىا ،\nوأنقذْنا من أجله اسْْهكر .", "44": "المزمورُ الرابعُ والأربعونَ\nإلى النهاية ، على الذين يتغيرىونر\nفـرهْمٌ لبني قورحر ، تسبحةٌ من أجله الحبيبه\n2 فاضر قلبِه كلمةً صالحهةً ،\nأقولُ أعمالي أنا للمرلهكه\nلساني قـرلرمُ كاتبٍ سريعه الكتابةه .\n3 بِرىٌ في حُسْنه أفضر لُ من بني ال بشره ،\nانسكبته النعمةُ من شرفرتـريْكر\nمن أجله هذا باركركر اللهُ إلى الدهره .\n\n4 تقلىدْ سريـْفركر على فرخْذهكر ، أيُها القوىُّ ،\nبَهُسْنهكر وبِرايهكر ،\n5 اهسْتـرلىهُ ، وانجْرحْ وامْلُكْ\nمن أجله الحقِّ والدهعرةه والعردْله ،\nوتـرهْدهيكر بالعرجربه يَرينُكر .\n6 نـربـْلُكر مسنونةٌ ، أيُها الِبىارُ\nفي قلبه أعداءه المرلهكه ،\nشُعوبٌ وتحتكر يسقطونر .\n7 كُرسيُّكر ، يا اللهُ ، إلى دهره الدهوره ،\nقضيبُ الاستقامةه هو قضيبُ مُلْكهكر .\n8 لأنك أحببتَ البِهى وأبغضتر الإثُْر\nمن أجله هذا مر سرحركر اللهُ ، إلهرُكر ،\nبزيته البـرهْجرةه أفضر لر من رُفقايه كر .\n9 المُرُّ والمريـْعرةُ والسليخرةُ من ثيابك ،\nمن العاجه الكريمه ، الذي جعلوكر تُسرُّ به ه .\n11 بناتُ الملوكه في كرامتهكر\nقامته الملكةُ عن يمينك ، بثوبٍ مُوشىى بالذهبه\nمُزريىنةً بأنواعٍ كثيرةٍ .\n11 اسْْرعى ، يا ابنتَّه ، وانْظُرى وأرمهيلى أُذُنركه ،\n\nوانْسرىْ شرعْبركه وبـريْتر أبهيكه\n12 فإنى المرلهكر قد اشتهرى حُسْنركه ،\nلأنه هو ربُّكه .\n13 وله تسجُدُ بناتُ صور بالهدايا ،\nويتَجىى وجههُ أغنياءُ شعبه الأرض .\n14 كلُّ مَرْده اهبنةه المرلهكه من داخلٍ\nمُشترملةٌ بأطرافٍ مُوشى اةٍ بالذهبه مُترزيِّنةٌ بأشكالٍ كثيرةٍ .\n15 يُدْخهلونر إلى المرلهكه عذارى في إثْرها ،\nجميع قريباتُها إليه يـُقردىمْنر\n16 يُؤترى بِهنر بهفرحٍ وابتهاجٍ ،\nيردْخُلْنر إلى هيكله المرله كه .\n17 ويكونُ لكه أبناءٌ عهوهضاً عن الآباءه\nتُقهيمُهُم رؤساءر على سايره الأرض .\n18 ويذكُرونر اسْْركر جيلاً بعدر جيلٍ\nمن أجل ذلكر تعتَرفُ لكر الشعوبُ ، يا اللهُ ،\nإلى الدهره وإلى دهره الدهوره .", "45": "المزمورُ الخامسُ والأربعونَ\nإلى النهاية لهبرني قورحر ، من أجله الخفايا\n2 إلهرُنا مرلْجرأُنا وقـُوىتُنا ،\nومُعهينُنا في شدايدهنا التي أصابـرتْنا جداً .\n3 لذلكر لا نَرْشرى إذا تزعزعرته الأرضُ ،\nوانتقلته الِبالُ إلى قلبه البحاره .\n4 عرجىته المياهُ واضطربرتْ ،\nتزعزعرته الِبالُ بهعهزىته ه . سلام .\n5 مجاري الأنهار تـُفرِّحُ مدينةر الله\nلقد قردىسر العليُّ مسكرنرهُ .\n6 اللهُ في وسطها لا يزولُ\nيُعهينُ اللهُ ورجْهرها .\n7 اضطربرته الأُمرمُ ، وماجرته المرمالهكُ\nأربْدرى صوترهُ فتزلزلرته الأرضُ .\n8 الربُّ إلهُ القوىاته معنا ،\nناصرُنا هو إلرهُ يعقوب . سلام .\n9 هرلُمىوا فانْظُروا أعمالر الربّ ،\nالعجايبر التي مجّدها على الأرض\n11 الذي يـُبْطهلُ الحروبر إلى أقصرى الأرض ،\n\nيسحقُ قهسهيـىهُ م ويكسهرُ سلاحرهُ م ،\nويُرهقُ أتراسرهُ م بالناره .\n11 ثابهروا ،واعْلرموا أنِِّ أنا هو اللهُ\nأرْترفهعُ في الأُمرمه ، وأترعالِر على الأرض .\n12 الربُّ إلهُ القوىاته معنا ،\nناصهرُنا هو إلرهُ يعقوب .", "46": "المزمورُ السادسُ والأربعونَ\nإلى النهاية مزمورٌ لهبني قورحر\n2 يا جميع الأُمرمه صرفِّقوا بأيدهيكُم ،\nهرلِّلو ا لله بصوته الابتهاجه .\n3 لأنى الربّ عالٍ ومرهوبٌ ،\nمرلهكٌ عظيمٌ هو على الأرض كُلِّها .\n4 أرخْضرعر الشعوبر لنا ، والأُمرمر تُتر أقدامهنا\n5 اختار لنا ميراثره ،\nجَرالر يعقوب الذي أحبىهُ . سلام .\n6 صرعهدر اللهُ بتهليلٍ ،\nوالربُّ بصوته البوق .\n7 رتِّلوا لإلهرهنا ، رتِّلوا\n\nرتِّلوا لهمرلهكهنا ، رتِّلوا\n8 لأنى الربّ هو مرلهكُ الأرض كُلِّها ،\n9 رتِّلوا بهفرهْمٍ، لأنى الربّ مرلركر على جميع الأُمرمه ،\nاللهُ جالهسٌ على كُرْسهيِّه المقدىسه .\n11 رؤساءُ الشعوبه اج تمعوا مع إلره إبراهيمر ،\nلأنى أعزاءر الله قد ارتفعوا في الأرض جداً .", "47": "المزمورُ السابعُ والأربعونَ\nمزمورٌ تسبحةٌ لهبرني قورحر ، في ثاني السبته\n2 عظيمٌ هو الربُّ ومُسربىحٌ جداً\nفي مدينهةه إلهره نا ، على جبله المقدىسه ،\n3 ترتلئُ الأرضُ كُلُّها ب التهليل\nجبالُ صهيون ، جوانبُ الشماله ،\nمدينةُ المرلهكه العظيمه .\n4 اللهُ يـُعْرفُ في قُصورها ،\nإذا ما قربهلرها .\n5 لأنه هوذا الملوكُ قد اجتمرعوا ، وأتوا معاً\n6 هُم أربْصروا وهكذا تـرعرجىبوا ،\n7 اضطربوا وقلقوا. أرخرذرتـْهُ م الرهعْدرةُ ،\n\nهناكر أرخرذرهُم المُخاضُ كالتي ترلهدُ .\n8 بريحٍ عاصفةٍ تُُرطِّمُ سُفُنر تر شيشر .\n9 كرما سْرهعْنا هكذا رأريْنا\nفي مدينةه ربِّ القوىاته ،\nفي مدينةه إلهرهنا\nاللهُ أسّسها إلى الأبده . سلام .\n11 قربهلْنرا ، يا اللهُ ، رحْْتركر في وسطه شعبه كر .\n11 كراهسْْهكر يا اللهُ ، كذلك أيضاً هو تسبيحُكر ،\nمن أقصرى الأرض\nيَرهينُكر ملآنةٌ بهرّاً .\n12 فليفرحْ جبلُ صهيون ،\nولْتتهلىلْ بناتُ اليهوديةه ،\nمن أجله أحكامهكر ، يا ربُّ .\n13 طوفوا بصهيون وأرحهيطوا بِها ،\nتُردىثوا في أبْراجها\n14 ضرعوا قلوبركم في قوىتُها ،\nواقتسموا قُصورها ،\nلكى ما تُُبِِّوا بِها جيلاً آخر .\n15 أرنى هذا هو إلهرُنا\n\nإلى الأبده وإلى أبده الأبده ،\nوهو الذي يرعانا إلى الدهره .", "48": "المزمور الثامنُ والأربعونَ\nإلى النهاية مزمورٌ لهبرني قورحر\n2 اسْْعوا هذه ، يا معشر الأُمرمه ،\nأرمهيلوا آذانركُم ، يا جميع السُكىانه على الأرض ،\n3 أولادر الأرض وبرني البشر ،\nالغرنِهى والفقير معاً .\n4 فمى ينطقُ حهكْمةً ،\nوتلاوةُ قلبِه فـرهْمٌ .\n5 أُمهيلُ إلى الأمثاله أُذُنِرى ،\nوأفتحُ بِهزمارٍ فاتُه ةر كلامى .\n6 لماذا أخافُ في يومه السوءه ؟\nإثُُْ عرقربِه يحيط بي ،\n7 الذين يتىكلونر على قوىتُه م ،\nوبكثرةه غناهُم يفتخرونر .\n8 الأخُ لرنْ يفدى (+) الإنسانر فداءً ،\n\n)+( الأخُ لرنْ يفتدى ، أفيفتدهىر إنسانٌ ؟\n\nولا يُعطى الله كرفىارةً عن ذاته ،\n9 وثَرنر خلاصه نفسه\n11 ترعهبر إلى الأبده ، ويُريا إلى الانقضاءه ،\n11 لأنه لا يُعايهنُ فساداً ، إذا رأرى الحُكرماءر يَروتونر .\nالِاهلُ والذي لا عقلر له يـرهْلركانه معاً ،\nويتَْكانه ثـرْوتُرما لآخرينر .\n12 قبورُهم تصيرُ لهرم بيوتاً إلى الأبده ،\nومرسْكرناً لهرُ م إلى جيلٍ فجي لٍ\nدعوا أسْْاءرهم على الأرض .\n13 الإنسانُ إذا كان في كرامةٍ ولم يـرفْهرمْها\nقهيسر بالبرهايمه التي لا معرفةر لهرا وشُبِّهر بِها .\n14 هذا طرهيقُهم صار شركّاً لهرُم ،\nوبعد هذا يُبارهكونر بأفواه م . سلام .\n15 جُعهلوا مثلر الغنمه في الِحيمه ، ا وتُ يرعاهُم\nويسودُ عليه م المستقيمونر بالغداةه ،\nومعونتـُهُ م تـربـْلرى في الِحيمه من مَرْدهم .\n16 إنِىا اللهُ يَُرلِّصُ نفسي\nمن يده الِحيمه إذا أخرذرها . سلام .\n17 لا تُرفْ إذا استغنِر إنسانٌ ،\nوإذا كرثـُر مَرْدُ بيته\n\n18 لأنه عندر موته فلا يأخُذُ منه شيئاً ،\nولا يـرنْزهلُ معه مَرْدُهُ إلى الِحيمه .\n19 لأنى نفسه في حياته تـُبراركُ ،\nيعتَرفُ لكر إذا ما أحسنْتر إليه .\n21 يَرضى إلى جيله آبايه ،\nولا يُعايهنُ النور إلى الدهره .\n21 الإنسانُ إذا كان في كرامةٍ ولم يـر فْهرمْها ،\nقهيسر بالبرهايمه التي لا معرفةر لهرا وشُبِّهر بِها .", "49": "المزمورُ التاسعُ والأربعونَ\nمزمورٌ لأسافر\n1 إلرهُ الآلهةه الربُّ تكلىمر ، ودعا الأرضر\nمن مشارقه الشمسه إلى مرغارهبِها\n2 حُسْنُ بِرايه من صهيون .\n3 اللهُ يأتهى جرهراراً ، وإلهرُنا لا يسكتُ\nالنارُ قُدىامرهُ تتىقهدُ ،\nوحروْلرهُ عاصفٌ جداً .\n4 يدعو السرماءر من فوقُ ،\nوالأرضر ، ليدينر شرعبرهُ .\n\n5 اهجَْرعوا إليه أبْرارهُ ،\nالذين قرىروا عهدرهُ على الذبايحه .\n6 وتُُربـِّرُ السماواتُ بهعردْله ،\nلأنى الله هو ا لديىانُ . سلام .\n7 اهسْْرعْ ، يا شعبِه ، فأُكرلِّمركر\nويا إسراييلُ ، فأرشْهردر لركر\nإنِِّ أنا هو اللهُ إلهرُكر .\n8 لستُ أُوربُِِّكر على ذبايحهكر ،\nمُُرقاتُكر هى قُدىامى في كلِّ حينٍ\n9 لستُ أقبلُ من بيتهكر عُجولاً ،\nولا من قُطْعانهكر جهداءً .\n11 لأنى لي هى كلى وحوشه البـرِّية ،\nالبرهايمر التي على الِباله والبقر\n11 جميع طيوره السماء أنا أعرفُها ،\nوبِراءُ الحقله هو معى .\n12 إنْ جُعْتُ ، فلا أقولُ لكر\nلأنى لي المسكونةر ومهلأرها .\n13 هل آكُلُ لحرْمر الثيرانه ؟\nأو أشربُ دمر ا لتيوسه ؟\n\n14 اهذْبرحْ لله ذبيحةر التسبيح ،\nوأُوْفه العرلهىى نُذوركر\n15 اُدْعُني في يومه شدىتهكر ،\nأُنْ قه ذْ كر فتُمرجِّدرني . سلام .\n16 للخاطئه قالر اللهُ :\nلماذا أنت تُُردِّثُ بهعردْلي ؟\nوتفتحُ فرمركر بهعرهْدهى ؟\n17 وأنت قد أبغضتر تعليمى ،\nوطرحتر كلامى خرلْفركر .\n18 إنْ رأيتر سارقاً ، سرعريْتر معه ،\nومع الفرسرقةه جرعرلْتر نصيبركر\n19 فرمُكر أركْثـر من الشرِّ ،\nولسانُكر ضرفر غهشّاً\n21 إذا جرلرسْتر تقعُ بأخهيكر ،\nولابنه أُمِّكر وضعتر معثرةً .\n21 هذه صرنـرعْترها وسركرتُّ ،\nفرظرنـرنْتر إثَْاً أنىني أكونُ مهثـْلركر\nأُوربُِِّكر وأُقهيمُها أمامر ورجهكر .\n22 اهفـْهرموا هذه ، أيُها الذين نسوا الله ،\n\nلئلاى يَرطفر ولا يكونُ مُنْقهذٌ .\n23 ذبيحةُ التسبيح تُرجِّدُني ،\nوهناكر الطريقُ التي أُره يكر إياها ، خلاصر الله .", "50": "المزمورُ الخمسونَ\nإلى النهاية مزمورٌ لداود ،\nعندما جاء إليه ناثانُ النبي ، بعدما دخل إلى بَثْشَبع\n3 ارحمني ، يا اللهُ ، كعظيم رحمتك ،\nومثل كثرة رأفتك امحُ إثمي\n4 تغسلُني كثيراً من إثمي ،\nو من خطيئتي تطهرني .\n5 لأني أنا عارفٌ بإثمي ،\nوخطيئتي أمامي في كلِّ حينٍ .\n6 لك وحدك أخطأتُ ، والشر قدامك صنعتُ\nلكى تتبرر في أقوالك ،\nوتغلب إذا حوكمت .\n7 لأني هأنذا بالإثم حُبل بي ،\nوبالخطايا اشترتني أمي .\n8 لأنك هكذا قد أحببتَ الحق ،\n\nإذْ أوضحتَ لي غوامض حكمتك ومستوراتها .\n9 تنضحُ عليّ بزُوفاكر فأطهُرُ ،\nتغسلُني فأربـْيرضُّ أكْثـر من الثلجه .\n11 تُسْمهعُني سُروراً وفرحاً\nفتبتهجُ العظامُ المتواضعةُ .\n11 اهصْرهفْ ورجهركر عن خطاياىر ،\nوامْحُ كلى آثامى .\n12 قلباً نقيّاً اهخْلهقْهُ فىهى ، يا اللهُ ،\nوروحاً مستقيماً جردِّدْهُ في أحشايى .\n13 لا تطرحْني من قُدىامه ورجهكر ،\nوروحركر القدُّوسر لا تـرنْزعْهُ مهنِِّ .\n14 اهمْنرحْني بِرجةر خلاصهكر ،\nوبروحه رياسى أرعْضُدْني .\n15 فأُعرلِّمر الأثَرةر طُرُقركر ،\nوالمنافقون إليك يرجعونر .\n16 نجرِّني من الدماءه ، يا اللهُ إلرهر خلاصى\nفيبتهجر لساني بهعردْلهكر ،\n17 يا ربُّ ، تفتحُ شرفرتَّرى ،\nفيُخربـِّرُ فرمى بتسبحتهكر .\n\n18 لأنك لو آثرتر الذبيحةر ل كنتُ أُعطى أيضاً\nولكنكر لا تُسرُّ بالمُحرقاته .\n19 فالذبيحةُ لله هى روحٌ منسحقٌ ،\nالقلبُ المنكسرُ والمتواضعُ لا يُرذلُهُ اللهُ .\n21 أرنْعهمْ ، يا ربُّ ، بِهسرىتهكر على صهيون ،\nولْتُبْْر أسوارُ أورُشليمر .\n21 حينئذٍ تُسرُّ بذبايحه العدله ،\nقرباناً ومُُْرهقاتٍ\nحينئذٍ يـُقرِّبونر على مذبَرهكر العجولر .", "51": "المزمورُ الحادى والخمسونَ\nإلى النهاية فـرهْمٌ لداود ،\nحين جاء دويغ الأدومى وعرفير شاولر\nوقال له إن داود جاء إلى بيت أبيمالك\n3 لماذا تفتخرُ ، أيُها القوىُّ ، بالشرِّ ،\nواليوم كُلى هُ بالإثم ؟\n4 لسانُكر فركىر بالظُلْمه\nصرنـرعْتر الغهشى مثلر الموسى المسنونةه .\n5 أحببّتر الشر أكثـر من الخريرْه ،\nوالظُلْمر أفضرلر من التكلُّمه بالعردْله . سلام .\n\n6 أحببّتر كلى كلامٍ مُغْرهقٍ ،\nولهساناً غاشّاً .\n7 لذلكر يـرهْده مُكر اللهُ إلى الانقضاءه\nيقتلعُكر وينقُلُكر من مسكنهكر ،\nوأصلهكر من أرضه الأحياءه . سلام .\n8 يُبصهرُ الصدِّيقونر ويَرافونر ،\nويضحكونر عليه ، ويقولون :\n9 هو ذا الإنسانُ الذي لم َرعله الله مُعيناً له ،\nبل اتىكرلر على كثرة غناهُ ،\nوتـرقروى ى بأباطيله .\n11 أما أنا فمثلُ شجرةه الزيتونه المُثْمهرةه\nفي بيته الله\nتوكىلتُ على رحْْرةه الله إلى الأبده\nوإلى أبده الأبده\n11 أعتَرفُ لكر ، يا ربُّ ، إلى الدهره ، لأنك صنعتر هذا\nوأترسىكُ باسْْهكر ، فإنه صالهحٌ قُدىامر أبرارهكر .", "52": "المزمورُ الثانِى والخَمسونَ\nإلى النهاية على مالاته (+) فـرهْمٌ لداود\n2 قالر الِاهلُ في قلبه ليس إلهٌ .\nفسدوا وتنجىسوا بالآثامه ،\nليس من يعملُ صلاحاً .\n3 اللهُ من السماء اطىلرعر على برني البشر ،\nلهينظُر إنْ كانر من يفهمُ أو يطلبُ الله .\n4 الِرميعُ زاغوا وفسدوا معاً من هذا إلى ذاكر ، وقلقوا ،\nليس من يعملُ صلاحاً ، ليس ولا واحدٌ .\n5 ألم يعلرمْ كلُّ الذين يعملونر الإثُْر ،\nالذين يأكلونر شعبِه كأكله الخُبْزه ؟\nوإلى الله لم يصرخوا .\n6 هناكر خافوا خروْفاً حيثُ ليس خر وْفٌ ،\nلأنى الله يـُبردِّدُ عهظامر الذين يـُرْضونر الناسر\nخرزروْا لأنى الله رذرلهرُ م .\n7 من يُعطى الخلاصر لإسراييلر من صهيون ؟\nإذا ما ردى الربُّ سربِْر شرعبه\nفليتهلىلْ يعقوبُ ويفرحْ إسراييلُ .\n\n)+( خورس ترانيم ، يُشهيرُ إلى الرُسُل .", "53": "المزمورُ الثالثُ والخمسو نَ\nإلى النهاية ، في التسابيح فـرهْمٌ لداود ،\nحينر جاء الزيفيونر وقالوا لهشاولر إنى داود مُُتفٍ عندنا .\n3 اللهُمى ، باسْْهكر خرلهصْني ،\nوبهقوىتهكر أُحْكُمْ لي .\n4 اهسْتمعْ ، يا اللهُ ، صلاتي ،\nأرنْصهتْ إلى كلامه فرمهى .\n5 فإنى الغرباءر ق د قاموا عليّ ،\nوالأقوياءر طلبوا نفسي\nلم يسبقوا أن َرعلوا الله أمامرهُمْ . سلام .\n6 هو ذا اللهُ أعانرني ،\nوالربُّ هو ناصرُ نفسي .\n7 يـرُدُّ الشرور على أعدايى\nوبَهرقِّكر اهستأْصهلْهم .\n8 أذبرحُ لكر طايعاً ،\nوأعتَرفُ لاسْْهكر ، يا ربُّ ، فإنه صالهحٌ\n9 لأنك من جميع الشدايده نجرىيْترني ،\nوبأعدايى نرظرتْ عينراىر .", "54": "المزمورُ الرابعُ والخَمسونَ\nإلى النهاية ، في التسابيح فـرهْمٌ لداود\n2 أرنْصهتْ ، يا اللهُ ، لهصلاتي ،\nولا تغفلْ عن تضرُّعى ،\n3 اهلْترفهتْ إلِرى و اسْْرعْني .\nفإنِِّ قد حزنتُ في تكلُّمى ، وقلقتُ\n4 من صوته العدوِّ ومَهىا أحزنرني به الخاطئُ\nلأنْىم قد مالوا عليّ بالإثم ، وبالرهجْزه حرنرقوا عليّ .\n5 قلبِه قد اضطربر فىهى ، وجرزرعُ الموته أترى عليّ\n6 خروْفٌ ورهعْدرةٌ أتيا عليّ ، وغرشه يرتْني الظُلْمةُ .\n7 فقُلْتُ من يُعطيني جرناحرينْ كالحمامةه ، فأطير وأستَريحر ؟\n8 هاأنذا قد ابتعدتُ هارباً ، وسكنتُ في البـرِّيةه . سلام .\n9 وانتظرتُ الذي يَُلِّصُني من صهغره النفسه\nومن الريحه العاصفةه .\n11 غرِّقـْهُمْ ، يا ربُّ ، وفـرِّقْ أل سنتـرهُمْ ،\nلأني قد رأيتُ إثَْاً ومناقضةً في هذه المدينةه .\n11 نْراراً وليلاً مُُيطٌ بِها على أسوارها ،\n12 إثٌُْ وشقاءٌ وظُلْمٌ في وسطها ،\nولم يَرْلُ من شوارعها التعبُ والغهشُّ .\n\n13 فلو كان الذي عريـىرني عردُوّاً ، لاحْتمرلْتُ ،\nولو أنى مُبْغهضهى عرظىمر عليّ الكلامر ، لاخْتـرفريْتُ منه .\n14 بل أنت ، أيُها الإنسانُ عديلُ نفسي ،\nعظيمى(+) الذي أعرفُهُ\n15 كنتر معى ، وجعلتر الأطعمةر حُلْوةً عندى ،\nوقد سهرْنا معاً في بيته الله بقلبٍ واحدٍ .\n16 فلْيُوافهم الموتُ ، ولْين حدروا إلى الِحيمه أحياءً\nلأنى الشرور في مساكنه م وفي ورسْطه م .\n17 أما أنا فإلى الله صرخت ، والربُّ استجاب لي .\n18 عشيةً وباكراً ووقتر الظُهْره كلامى أقولُهُ\nفيسمعُ صوتي .\n19 يَُرلِّصُ بالسلامةه نفسي من الذين يقتربون إلِرى ،\nلأنْى م في أشياءر كثيرةٍ كانوا معى .\n21 يسمعُ اللهُ ، ويُذهلهُُّم الكاينُ قبلر الدهوره . سلام .\nلأنى ليس لهرُ م عهوضاً يُعطونره ،\nولم يَرافوا الله .\n21 برسرطر يردرهُ لهيُعطى\nفدرنىسوا عرهْدرهُ ،\n\n)+( مُرشدى وأليفي أو صاحبِه .\n\n22 تفرىقوا من غضبه ورجه ، واقتَربر قلبُهُ\nكلامُهُ ألينرُ من الدُهْنه ، وهو نهصالٌ .\n23 أرلْقه على الربّ هُرىكر ، وهو يعولُكر\nولا يردرعُ الصدِّيقر يتزعزعُ إلى الأبده .\n24 أنت ، يا اللهُ ، تُُْدهرُهُ م إلى بئره الهلاكه\nرجالُ الدماءه والغشِّ لرنْ يـرنْصُفوا أيامرهُ م\nأما أنا فعليكر ، يا ربُّ ، توكىلْتُ .", "55": "المزمورُ الخامسُ والخمسونَ\nإلى النهاية ، على الشعبه الذي تباعردر عن القدِّيسينر\nكتابةٌ على عمودٍ لداود ، حين أمسكرتْهُ القبايلُ الغريبةُ في جات .\n2 ارحمني ، يا ربُّ ، فقد ورطهئرني الإنسانُ ،\nاليوم كلىهُ أحزنرني بالقتاله .\n3 ورطهئرني أعدايى اليوم كلىهُ\nلأنى الذين يُقاتهلونرني كثيرون ،\n4 من ارتفاعه النهاره يَرافونر .\nأما أنا فعليكر توكىلتُ ، يا ربُّ .\n5 بالله أفتخرُ بأقوالي النهار كُلىهُ\nعلى الله توكىلتُ ، فلا أخافُ ماذا يصنعُهُ بي ذو الِسده .\n\n6 النهار كُلىهُ كانوا يُدرنِّسونر أقوالي ،\nجميع مؤامراتُهم كانت عليّ بالشروره .\n7 يتغرىبونر ويَرتفونر\nوهُم لهعرقهبِه يرصدونر ، مثلما صبِهتُ في نفسي\n8 من أجله لا ش ىءر تُُرلِّصُهم ،\nتطرحُ شعوباً بالغضبه .\n9 اللهُمى ، إنِِّ قد أظْهرتُ لكر حياتهى ،\nجعلتر دموعى أمامر كر هكذا كمثله موعدهكر .\n11 يرجعُ أعدايى إلى ورايه م ،\nفي اليومه الذي أدعوكر فيه ،\nهو ذا قد علمتُ أنكر أنت هو إلهي .\n11 أُسربِّحُ الله بالقوله ،\nوأُباركُ الربّ بالكلامه .\n12 على الله توكىلتُ فلا أخافُ ، ماذا يصنعُ بي الإنسانُ .\n13 اللهُمى ، عليّ نذورٌ أُقدِّمُها لكر تسبحةً\n14 لأنك نجريىتر نفسي من الموته ،\nوعريـْنِرى من الدموعه ورهجْلرىى من الزرلرقه ،\nلأُرْضهى الله أمامرهُ في نوره الأحياءه .", "56": "المزمورُ السادسُ والخم سونَ\nإلى النهاية لا تـُهْلهكْ كتابةٌ على عمودٍ لداود ،\nعندما هرب من ورجه شاولر إلى المغارةه .\n2 ارحمني ، يا اللهُ ، ارحمني\nفإنه عليكر توكىلرتْ نفسي ،\nوبهظهلِّ جناحريْكر أرعْتصمُ\nإلى أنْ يعبـُر الإثُُْ .\n3 أصرُخُ إلى الله العلي ،\nالإله الذي أحْسرنر إلِرى . سلام .\n4 أرسلر من السماء وخلىصرني ،\nومجّد العار على الذين يطأونرني\nأرسلر اللهُ رحْْرترهُ وحرقىهُ ،\n5 وخرلىصر نفسي من بـرينْ الأشباله .\nنِهتُ مُضطرباً\nأسنانُ أبناءه البشر سلاحٌ وسهامٌ ،\nولسانُْم سيفٌ مُرهرفٌ .\n6 اهرْترفهعه اللهُمى على السماوات ،\nومَرْدُكر على سايره الأرض .\n7 نصبوا لهرهجْلرىى فهخاخاً ،\n\nوأحنوا نفسي.\nحفروا قُدىامر ورجهى حُفرةً ،\nوسقطوا فيها . سلام .\n8 مستعدٌّ قلبِه ، يا اللهُ ، مُستعدٌّ قلبِه ،\nأُسبِّحُ وأُرتِّلُ في ترجيده ى .\n9 اهستيقهظْ يا مَرده ى ،\nاهستيقهظْ أيُها المزمارُ والقيثارةُ\nأنا أقومُ باكراً .\n11 أعتَرفُ لكر في الشعوبه ، يا ربُّ ،\nوأُرتِّلُ لكر في الأُمرمه\n11 لأنى ر حْْتركر قد عرظُمرتْ إلى السماوات ،\nوإلى السحابه عردْلُكر .\n12 اهرْترفهعه اللهُمى على السماوات ،\nومَرْدُكر على سايره الأرض .", "57": "المزمورُ السابعُ والخَمسونَ\nإلى النهاية لا تـُهْلهك كتابةٌ على عمودٍ لداود\n2 إنْ كُنتُمْ حرقّاً بالصدْقه تتكلىمونر ،\nفاحْكُموا مُستقيماً ، يا برني البشر .\n\n3 فإنكُم بالقلب تعملونر الإثُْر على الأرض ،\nوأيديكُ م ترصنعُ الظُلْمر .\n4 صار الخطاة غرباءر منذ كانوا في الرحهمه ،\nوضرلُّوا وهُم في البطنه ، وتكلىموا بالكذبه .\n5 فليكنْ لهرم غضبٌ كشهبْه الحيىةه ،\nوكرمهثْله الأفعرى الصمىاءه العديَةه السرمْعه .\n6 التي لا تسمعُ صوتر الرقاةه ،\nولا دواءر يتهيىأُ من حكيمٍ .\n7 اللهُ يسحرقُ أسنانـرهُ م في أفواهم ،\nالربُّ قد حرطىمر أنيابر الأُسوده .\n8 يُرذرلونر مثلر الماءه المسكوبه ،\nيـُوْتهرُ قـروْسرهُ حتَّى يضعفوا .\n9 مثلر الشمعه المُذابه يرهلكونر\nسقطرته النارُ ، فلم يُعاينوا الشمسر .\n11 قبلر أنْ تبتديوا وتعرفوا شروكركُم ،\nفالحسكُ ، كرمهثله الأحياءه ، كما بغضبٍ يبتلعُكُم .\n11 يفرحُ الصدِّيقُ إذا ما أبصر الانتقامر ،\nويغسلُ يردريْه من دمه الخطاة .\n12 ويقولُ الإنسانُ ألار تكونُ ثَرةٌ للصدِّيقه ،\n\nلأنى الله كاينٌ يُدينـُهُ م على الأرض .", "58": "المزمورُ الثامنُ والخَمسونَ\nإلى النهاية لا تـُهْلهك كتابةٌ على عمودٍ لداود ،\nعندما أرسلر شاولُ وأحاطر بهبيته لكى يقتلرهُ .\n2 نجرِّني من أعدايى ، يا اللهُ ،\nومن الذين يقومونر عليّ أرنقهذْني .\n3 نجرِّني من الذين يصنعونر الإثُْر ،\nومن رهجاله الدماءه خرلِّصْني .\n4 فها هُم قد اصطادوا نفسي ،\nوقامر عليّ الأقوياءُ .\nوليس هذا إثمي ولا خطيئتي ، يا ربُ .\n5 فبغريرْه إثٍُْ سعيتُ واستقمتُ\nاهنـْهرضْ إلى لقايى ، وانظُرْ ،\n6 وأنت ، يا ربُّ إلهر القوىاته ، إلهر إسراييلر ،\nاهلترفهتْ ولتفتقدْ كافىةر الأُمرمه ،\nلا تتَأفيْ على كلِّ من يصنعُ الإثُْر . سلام .\n7 يرجعونر عند المساءه وَروعونر مثلر الكلابه\nويُروطونر بالمدينةه .\n\n8 هوذا ينطقونر بأفواهم ، والسيفُ في شهفاهم\nقايلينر من يسمعُ ؟\n9 وأنت ، يا ربُّ ، تضحكُ بِه م ،\nوتُرذهلُ جميع الأُمرمه .\n11 وأنا فأحفظُ عهزِّى لر در يْ كر .\nلأنك أنت هو اللهُ ناصري .\n11 إلهي رحْْتُهُ تسبقُ فتُدركُني\nاللهُ يُريني بأعدايى .\n12 لا تقتلْهُم ، لئلاى ينسوا ناموسركر\nشر تِّتـْهُم بهقوىتهكر\nواطْرحْهُم إلى أسفلُ ، يا ربُّ ناصري .\n13 لأجله خطيئةه أفواهم ، وكلامه شهفاهم ،\nفليُؤخرذوا بهكبِْيايهم\n14 ومن اللعنةه والكذبه يَُْبِرونر بالانقضاءه ،\nبغضبه الانقضاءه ، فلا يُوجردونر\nويعلمونر أنى إلهر يعق وبر يسودُ جَر يعر أقاصى الأرض .سلام .\n15 فيرجعونر عندر المساءه وَروعونر مثلر الكلابه ،\nويُروطونر بالمدينةه\n16 وهُم يتفرىقونر ليأكلوا ،\n\nفإذا شبعوا ، يتقمقمونر .\n17 أما أنا فأُسربِّحُ قوىتركر ،\nوأتُرلىلُ في الصباحه بهرحمتك\nلأنك صهرتر لي ناصراً\nوملجأً في يومه شدىتهى ،\n18 أنت هو مُعيني ، لكر أُرتِّلُ ، يا إلهي\nلأنك أنت هو ناصري ،\nإلهي ورهحْْرتَّه .", "59": "المزمورُ التاسعُ والخَمسونَ\nإلى النهاية على الذين يتغيرىونر ، كتابةٌ على عمودٍ لداود ،\nتعليمٌ ، حين أحر قر ما بـرينْر نْرى سورية وشام شوبال ،\nوعادر يوآبُ وأهلكر في وادى الملحه اه ثـْ نِرْ عشر ألفاً .\n3 يا اللهُ ، أقصيترنا وهردر مترنا ،\nغضبتر ثم ترأفيْتر علينا .\n4 زلْزلتر الأرضر وأقلقترها\nاهشفه كسورها ، لأنْىا قد تزعزعرتْ ،\n5 أريتر شعبركر الشدايدر ،\nأسقيترنا خَرْر الحريـْرةه .\n\n6 أعطيتر علامةً للذين يَرافونركر ،\nليهربوا من ورجه القوسه . سلام .\n7 لكيما ينجو أحباؤُكر ،\nخرلِّصْني بيمينهكر واستجبْ لي .\n8 اللهُ تكلىمر في قدوسه ،\nأتُرلىلُ وأرقْسهمُ شكيمر ،\nوأقيسُ وادى المظاله .\n9 لي هو جلعادُ ، ولي هو منسىى ،\nأفرايمهُ هو عهزُّ رأسي\nيرهوذا مرلهكهى ،\n11 موآبُ هو قوىةُ رجايى\nوعلى أدومر أرمْدُدُ حذايى ،\nلأنى القبايلر الغريبةر خضعرتْ لي .\n11 من يبلغُ بي إلى مدينةٍ حصينةٍ ؟\nأو من يُرشهدُني إلى أدومر ؟\n12 أليسر أن تر ، يا اللهُ ، الذي أقصيترنا ؟\nولم تُرُ جْ معنا ، يا اللهُ ، في قوىاتهنا ؟\n13 أرعْطهنا عروْناً في شهدىتهنا ،\nفباطلٌ هو خلاصُ الإنسانه .\n\n14 بإلهرهنا نصنعُ القوىةر ،\nوهو يُرذلُ كلى من يُُْ زه نُنا .", "60": "المزمورُ الستُّونَ\nإلى النهاية ، في التسابيح لداود\n2 اهسْترمعْ يا اللهُ طلبتَّه ،\nأرصْغه إلى صلاتي .\n3 من أقاصى الأرض صرخت إليك ، عندما تروجىعر قلبِه .\nعلى الصخرةٍ رفـرعْترني ،\n4 أرشدْترني ، صهرتر رجايى ،\nوبـُرْجاً حصيناً في ورجه العدوِّ .\n5 أسكنُ في مسكنهكر إلى ال دهره ،\nوأستظلُ بهسهتَْه جرناحريْكر . سلام .\n6 لأنك أنت ، يا اللهُ ، استرمعتر صلواتهى ،\nأرعْطريتر ميراثاً لخهايفي اسْْهكر .\n7 تُزيدُ المرلهكر أياماً على أيامه ،\nعلى سنينه إلى أيامه جيلٍ وجيلٍ .\n8 ويدومُ إلى الأبده قُدىامر الله\nرحْْتُهُ وحر قُّهُ من يبتغيهُ ما ؟\n\n9 هكذا أُرتِّلُ لاسْْهكر إلى دهره الدهوره ،\nلأرفىه نذورى يوماً فيوماً .", "61": "المزمورُ الحادى والستُّونَ\nإلى النهاية ، عن إيديثونر مزمورٌ لداود\n2 أليسر لله تُرضعُ نفسي ؟\nلأنى مهن قهبرله خلاصى .\n3 لأنه هوإلهي ومُُلِّصى ،\nناصري فلا أتزعزعُ بـر عْ دُ .\n4 إلى متى تريلونر على الإنسانه ؟\nتـرقْتُلونر كُلُّكُ م\nمثلر حايطٍ مايلٍ ، وسياجٍ واقعٍ .\n5 وأيضاً تآمروا على كرامتَّه لكى يطرحوها ،\nكانوا يُسرعونر بالعطشه ،\nيُباركونر بأفواهم ، وبقلبه م يلعنونر . سلام .\n6 بل لله اهخضعهى ، يا نفسي ،\nلأنى من قهبرله اصطبارى .\n7 لأنه هو إلهي ومُُلِّصى ،\nناصري فلا أنتقلُ .\n\n8 خلاصهى ومَرده ى هُُا بإلهره ى\nإلهُ معونتَّه ، وبالله هو رجايى .\n9 ترجُّوه ، يا كافىةر مجمع الشعبه\nاسكبوا قُ دىامرهُ قلوبركُم\nمُعينُنا هو اللهُ . سلام .\n11 إنِىا باطلٌ بنو البشر ،\nأبناءُ البشر كاذبونر في الموازينه ليظلموا ،\nوهُم في الباطل مُتفيقونر .\n11 لا تتكلوا على الظُلْمه ،\nولا تُُبُّوا الخرطْفر\nوإن فاضر الغهنِر فلا تضعوا عليه قلبركُ م .\n12 مرىةً تكلىمر اللهُ ، وهذا سْرعناهُ دُفـْعرتـرينْ ،\nأنى العهزىةر لله ، ولكر يا ربُّ الرحْْرةُ ،\n13 لأنك أنت تَُّازى كُ لى واحدٍ كأعماله .", "62": "المزمورُ الثانِى والستُّونَ\nمزمورٌ لداود ، لرمىا كان في برِّيةه أدومر .\n2 يا اللهُ إلهي ، إليك أُبرك رُ\nلأنى نفسي عرطهشرتْ إليك ،\n\nلكى يـُزْهرُ لكر جسده ى ،\nفي أرضٍ مُقفرةٍ وموضعٍ غريرْه مسلوكٍ ومكانٍ بلا ماءٍ ،\n3 هكذا ظهرتُ لكر في القدسه ،\nلأرى قوىتركر ومَردركر .\n4 لأنى رحْْرتركر مُُتارةٌ أفضرلُ من الحياةه\nشرفرتاىر تُسبِّ حانهكر .\n5 هكذا أُباركُكر في حياتهى ،\nباسْْهكر أرفعُ يدىى .\n6 فتشبعُ نفسي كما من شرحْمٍ ودرسرمٍ ،\nوشفاهُ التهليل تُبارهكُ اسْْركر .\n7 كنتُ أذكُرُكر على فراشى ،\nوفي أوقاته الأسْحاره كنتُ أُرتِّلُ لكر\n8 لأنك صهرتر لي عروْناً ،\nوتحت ظهلِّ جرنا حريْكر أبتهجُ .\n9 اهلْتحقرتْ نفسي وراءركر ،\nويَرينُكر عضى درتْني .\n11 أما الذين طلبوا نفسي باطلًا ،\nفيُدخرلونر إلى أسافهله الأرض .\n11 يُدفرعونر ليده السيفه ،\n\nويكونونر أنصبةً للثعالبه .\n12 أما المرلهكُ فيفرحُ بالله ،\nويفتخرُ كلُّ من يُرلفُ به ه ،\nلأنى أفواهر المتكلِّمينر بالظُلْمه تُسردُّ .", "63": "المزمور الثالثُ والستُّونَ\nإلى النهاية مزمورُ لداود\n2 اسْترمعْ ، يا اللهُ ، صلاتي إذا تضرىعتُ إليك ،\nمن خروْفه العدوِّ أرنْقهذْ نفسي .\n3 ستَرترني من تقلُّبه الأشراره ،\nومن كثرة فاعلى الإثُْه\n4 هؤلاء الذين سنُّوا ألسنترهم كالسيفه ،\nوأوتروا قهسيـى هُ م ، عملٌ مُرٌّ هو ،\n5 ليرشهقوا الذي بلا عريْبٍ (بالسهامه ) في الخفاءه\nيرمونره (بالسهامه ) بغتةً ولا يَرشروْنر .\n6 شردىدوا أنفسهم بكلامٍ ردىءٍ ،\nتشاوروا لهيرخفوا فهخاخاً\nقالوا من يـُبْصهرُنا ؟\n7 فتىشوا عن الإثُْه ،\n\nوبادوا وهُم يُفتِّشونر تفتيشاً\nيأتهى إنسانٌ بقلبٍ عميقٍ ، فيتعالِر اللهُ .\n8 صارتْ ضرباتـُهُ م (كما) بنباله الأطفاله الصغاره ،\nومرهضرتْ ألسنتـُهُ م عليه م .\n9 اضطربر جميع ا لناظرينر إليهمْ ،\nوخرشهيرتْ كُ لُّ الناسه\n11 وأظهروا أعْمالر الله ،\nوتفهىموا صنايعرهُ .\n11 يفرحُ الصدِّيقُ بالربّ ، ويتىكلُ عليه\nويفتخرُ كلُّ المستقيمينر بقلوبِه م .", "64": "المزمورُ الرابعُ والستُّونَ\nإلى النهاية مزمورٌ لداود ، تسبحةٌ .\n2 لكر ينبغى التسبيحُ ، يا اللهُ ، في صهيون ،\nولكر يُوفىر النذرُ في أورشليمر .\n3 اهسْتمعْ يا اللهُ صلاتي ،\nفإليك يأتهى كلُّ بشرٍ .\n4 كلامُ مُُالهفي الناموسه قد قروهىر علينا ،\nوأنت الذي تغفرُ لنا نهفاقاتهنا .\n\n5 طوبى لهمن اهخْتَرترهُ وقر بهلْترهُ ،\nليسكنر في ديارهكر إلى الأبده .\nسنشبعُ من خيرْاته بيتهكر\n6 قُدُّوسٌ هو هيكلُكر ، وعجيبٌ في البِه .\nاهسترجبْ لنا ، يا اللهُ مُُلِّصرنا ،\nيا رجاء جميع أقطار الأرض ، والبرحره البعيده .\n7 المُهيِّئُ الِبالر بهقوّته ،\nالمُتمنطقُ بالاقتداره\n8 الذي يـُ قْلهقُ عُمْقر البحره ، وصوتر أمواجه .\n9 تضطربُ الأُمرمُ ويَرافُ كُلُّ سُكىانه أقطار الأرض\nمن علاماتهكر\nجرعرلْتر مرطالهعر الصباحه والمساءه تبتهجُ .\n11 تعاهردْتر الأرضر فأسكرْتُرا ،\nوأكثـرْتُرا بهغهنِر\nامتلأر نْرُ الله مياهاً\nهريىأْتر طعامرهُ م ، لأنى هذا هو تـرهْيهئرتُ ه .\n11 فـرلْتـُرْور أرتلامُها ،\nولتكثـُرْ أرثَْارُها ،\nوتفرحْ بقطراته فتنمو .\n\n12 تُبارهكُ إكليلر السنةه بصلاحهكر ،\nوبهقاعُكر ترتلئُ من الدسرمه\n13 تردْسُمُ جبالُ البـرِّيةه ،\nوتتمنطقُ الآكامُ بالبـرهْجةه .\n14 اكتسرتْ كهباشُ الغنمه ،\nوالأوديةُ تُكْثهرُ من الحنطةه\nيصرخونر ، لأنْىم يُسربِّحونر .", "65": "المزمورُ الخامسُ والستُّونَ\nإلى النهاية تسبحةُ مزموره القيامةه\n1 هلِّلوا لله يا كُلى الأرض .\n2 رتِّلوا لاسْْه ،\nأعطو ا مَرداً لتسبحته\n3 قولوا لله ما أرهربر أعمالهكر\nمن كثرة قوىتهكر يكذبُ بك أعداؤُ كر .\n4 لتسجُدْ لكر الأرضُ كُلُّها ولهيرُتِّلوا لكر ،\nوليتَرنِروا لاسْْهكر . سلام .\n5 تعالوا ، اُنظروا أعمالر الله ،\nلأنه مَُتلئٌ رهبةً في آرايه أكثـرُ من بر ني البشر .\n\n6 الذي حوىلر البحر إلى يـربرسٍ ،\nوبأرْجُلهم يعبُِونر النهر\nهناكر نفرحُ به ه .\n7 فهو الذي يسودُ بقدرته إلى الدهره ،\nعيناهُ تنظرانه الأُمرمر ،\nالمغضبونر لا يرتفعونر في أنفسهم . سلام .\n8 باركوا إلهرنا أيُها الأممُ ،\nواسْْعوا صوتر تسبحته ،\n9 الذي جعلر نفسي تُريا ،\nولم يُسرلِّمْ قردرمرىى إلى الزلله .\n11 لأنك امترحنْترنا ، يا اللهُ ،\nوسربركْترنا كما ترسْبهكُ الفضىةر .\n11 أدخلترنا في الفخِّ ،\nجعلْتر الشدايدر قُدىامرنا ،\n12 رفعتر الناسر على رؤوسهنا\nجُ زْنا في الناره والماءه ،\nوأخرجْترنا إلى الراحةه .\n13 أدخُلُ إلى بيتهكر بالمُحرقاته ،\n14 وأُوفيكر النذور ، التي نرطرقرتْ بهٍٍها شرفتاىر\n\nوتكلىمر(بِها ) فرمى في شهدىتهى\n15 أُقرِّبُ لكر مُُرقاته شرحْمٍ بلا عرظْمٍ مع بُِورٍ وكهباشٍ ،\nأُقردىٍهمُ لكر بقراً مع تيوسٍ . سلام .\n16 تعالوا اسْْرعوا فأُخْبِهركُم ، يا جميع خايفي الله ،\nبكلِّ ما صرنرعر لنفسي .\n17 صرخت إليه بفمى ،\nوعرظىمْتُ بلساني كثيراً .\n18 إنْ كنتُ أبصرتُ ظُلْماً في قلبِه ،\nفلا يستجيبُ اللهُ .\n19 لذلكر سْرهعرني اللهُ ،\nوالْتـرفرتر إلى صوته طهلْبرتَّه .\n21 مُباركٌ اللهُ الذي لم يـُبْعهدْ صلاتي ولا رحْْترهُ ع .", "66": "المزمورُ السادسُ والستُّونَ\nإلى النهاية ، في التسابيح مزمورٌ لداود\n2 لهيتَاءرفٍْه اللهُ علينا ويُباركْ نا ،\nوليُظهرْ ورجْهرهُ علينا ويرحْرْ نا . سلام .\n3 لهتُعرفر في الأرض طريقُكر ،\nوفي جميع الأُمرمه خلاصُكر .\n\n4 فلْتعتَرفْ لكر الشعوبُ ، يا اللهُ ،\nفلتعتَفْ لكر الشعوبُ كُلُّها .\n5 لهتفرحه الأُمرمُ وتبتهجْ ،\nلأنك تُركُمُ في الشعوبه بالاستقامةه ،\nوتُردى الأُمرمر في الأرض . سلام .\n6 فلتعتَفْ لكر الشعوبُ ، يا اللهُ ،\nفلتعتَفْ لكر الشعوبُ جَريعاً .\n7 الأرضُ أعطرتْ ثَرتُرا\nيُباركُنا اللهُ إلهرُنا ،\n8 يُباركُنا اللهُ ،\nولْترخْشرهُ جميع أقطار الأرض .", "67": "المزمورُ السابعُ والستُّون\nإلى النهاية لداود ، مزمو رُ تسبحةٍ\n2 لهيـرقُمه اللهُ ، ولهيتبدىدْ جميع أعدايه ،\nولْيرهربْ من قُدىامه ورجْه كُلُّ مُبغهضهيه .\n3 ولْيرضْمرحهلُّوا كما يرضْمرحهلُّ الدُخىانُ\nوكما يذوبُ الشرمْعُ قُدىامر الناره ،\nكذلهكر يرهلكُ الخطاة من أمامه ورجْه الله .\n\n4 فلْيفرحه الصدِّيقونر ، سلام .\nوليتهلىلوا أمامر الله ،\nولْيتنعىموا بالسروره .\n5 سربِّحوا الله ، رتِّلوا لاسْْه\nاهصْنرعوا طريقاً للراكبه على المغاربه الربُّ اسُْْهُ\nولْيربتهجوا أمامرهُ .\n6 لهيضْطربوا من ورجْه ،\nأبو اليتامرى وقا ضى الأرامله\nاللهُ في موضهعه المقدىسه .\n7 اللهُ يُسْكهنُ ذوى الشكله الواحده في بيتٍ ،\nيَُرجُ المُقيىدينر بقوىةٍ .\nكذلك المُغْضهبينر ، الساكنهينر في القبوره .\n8 يا اللهُ ، عندما خرجتر أمامر شعبك ،\nعند اهجتيازهكر في البـرِّيةه ، سلام .\n9 ارضُ تزلزلرتْ ، لأنى السماوات قرطرتْ\nمن أمامه ورجْه الله ، أى سيناءُ نفسُها ،\nمن قُدىامه ورجْه إله إسراييلر .\n11 مرطر الرهضا تـُقرسِّمُهُ على ميراثهكر ، يا اللهُ ،\nضرعُفر ، أما أنت فهيىأْترهُ .\n\n11 الأحياءُ لكر يسكنونر فيه ،\nقد هيىأْتر بصلاحهكر للمسكينه يا اللهُ .\n12 الربُّ يُعطى كلمةً للمُبشِّرينر بقوىةٍ عظيمةٍ ،\n13 مرلهكُ القوىاته هو الحبيبُ ،\nوفي بِراءه بيته الحبيبه أرقْسهموا الغنايمر .\n14 إذا نِهْتُمْ في وسطه المواريثه ،\nأجنحةُ حْرامةٍ مُغشىاةٌ بَهُلهىِّ الفضى ةه ،\nومنكهبراها بهصُفْرةه الذهبه . سلام .\n15 عندما يفرزُ الذي فوقر السماء عليها مَرالهكر ،\nيـربـْيرضُّونر مثلر الثلجه في سرلْمونر .\n16 جربرلُ الله الِبلُ الدرسهمُ ،\nالِبلُ المُترجربُِّْ ، الِبلُ السرمينُ .\n17 ما بالُكُم تـُفركِّرونر في جبالٍ مَُربى نةٍ ؟\nالِبلُ الذي سُرى اللهُ أن يسكُنر فيه\nفإنى الربّ يسكُنُ فيه إلى الانقضاءه .\n18 مركبةُ الله ربواتٌ مُضاعرفرةٌ ،\nوألوفُ المُزْهرهينر ،\nاللهُ فيهم ، في سيناءر ، في القدسه .\n19 صرعهدر إلى العلاءه وسربِر سربْياً ،\n\nأرعْطرى الناسر كراماتٍ ،\nوقد كانوا كارهينر أن يسكنوا .\n21 مُباركٌ الربُّ الإلهُ ،\nمُباركٌ الربُّ يوماً فيوماً ،\nيُهيِّئُ طريقنا إلهُ خلاصهنا . سلام .\n21 إلهرُنا هو اللهُ لكى يَُرلِّصرنا ،\nوللربِّ مُرارهجُ الموته .\n22 بل إنى الله يسحقُ رؤوسر أعدايه ،\nوهامةر شعره السالكينر في التواني .\n23 قال الربُّ إنِِّ أرجعُ من بيسانر ،\nأرجعُ من أعماقه البحره\n24 لكى ما تصطبغُ رهجْلُكر بالدمه ،\nلسانُ كهلابك من الأعداءه .\n25 من قهبرله رأوا مسالهكركر ، يا اللهُ ،\nمسالهكر إلهي الملهكه الذي في القدسه .\n26 الرؤساءُ سبقوا وتقدىموا إلى قـُرْبه المُرتِّلينر ،\nفي وسطه فتياتٍ ضارباتٍ بالدفوفه .\n27 بارهكوا الله في الكنايسه ،\nوالربّ من ينابيعه إسراييلر .\n\n28 هناكر بنيامينُ الصغيرُ في درهرشٍ ،\nرؤساءُ يرهوذا ومُدبِّروهُم ،\nرؤساءُ زبولونر ،\nرؤساءُ نفتاليمر .\n29 مُرْ ، يا اللهُ ، بهقوىتهكر ،\nبل ثـربِّتْ ، يا اللهُ ، هذا الذي صنعترهُ لنا ،\n31 من هيكلهكر المُقدىسه فوقر أورشليمر ،\nلكر تـُقرِّبُ الملوكُ هدايا .\n31 اللهُمى انتهرْ وحوشر الغابه\nمَرمعر العجوله مع بقره الشعبه ،\nلكى لا يُر بسوا المُختربِرينر بالفضىةه\nشرتِّته الأُمرمر الذين يريدونر القتالر .\n32 يأتهى الشفعاءُ من مهصْر ،\nالحبشةُ تسبقُ بيدريْها إلى الله ،\n33 يا جميع مَرالهكه الأرض ، سربِّحوا الله ،\nرتِّلوا للربِّ . سلام .\n34 رتِّلوا لله الذي صرعهدر إلى سْراءه ا لسماءه نُرور المشارقه .\nهو ذا يـُعْطهى صروْترهُ صوتر قوىةٍ .\n35 أرعْطُوا مَرداً لله ،\n\nلأنى عهظرمر بِرايه على إسراييلر ،\nوقوىترهُ في السحابه .\n36 عجيبٌ هو اللهُ في قدِّيسه يه\nإلهُ إسراييلر ، هو يُعطى قوىةً وعهزّاً لشعبه\nومُباركٌ هو اللهُ .", "68": "المزمورُ الثامنُ والستُّونَ\nإلى النهاية ، على الذين يتغيرىونر لداود\n2 أرحْيهني ، يا اللهُ ، فإنى المياهر قد دخلرتْ إلى نفسي .\n3 تورىطْتُ في حْرأةه الموته ، وليس استطاعةٌ بـرعْدُ\nذهبْتُ إلى أعماقه البحره ، والعاصفُ غرى قرني .\n4 عريهيتُ مَهىا أصرخُ ، وبُحى حلقى ،\nذربـُلرتْ عيناىر مَهىا أترجىى إلهي .\n5 كرثـُر أكثـر من شرعْره رأسي الذين يُبغضونرني مَرىاناً\nاهعتـرزى أعدايى الذين يطردونرني ظُلْماً\nكنتُ أرُدُّ حينئذٍ ما لم أختلسْهُ .\n6 يا اللهُ ، أنت عر فتر جهالاتهى ،\nوتضجيعاتهى لم تُُْفر عرنْكر .\n7 لا يَرْزر بي الذين ينتظرونركر يا ربُّ ، ربى القوىاته\n\nولا يُعيرىوا من أجلى الذين يلتمسونركر ، يا إلهر إسراييلر .\n8 لأني من أجلهكر قربهلْتُ العار ،\nوغرطىى الخهزْىُ ورجْهى .\n9 صهرْتُ أجنبياً عند إخوتهى ،\nوغريباً عند برني أمي\n11 لأنى غريـْرةر بيتهكر أركرلرتْني ،\nوتعييراتُ مُعيرِّيكر ور قـر عرتْ عليّ .\n11 أحنيْتُ بالصومه نفسي ،\nفصار ذلكر عاراً لِه\n12 جعلْتُ لهباسهى مهسْحاً ،\nوصهرتُ لهرُ م مرثرلاً .\n13 تكلىمر عليّ ا السونر في الأبوابه ،\nوعليّ تـرنَّىر شاربو الخرمْره .\n14 وأنا أصعدتُ صلاتي إليك ، يا ربُّ ،\nزمانُ المسرىةه هو ، يا اللهُ\nبكثْرةه رهحْْرتهكر اهسْترجهبْ لي ، بَهقِّ خلاصهكر .\n15 خرلِّصْني من الطينه لئلا أروْحرلر\nتـُنْقهذُني من الذين يُبغضو نرني ومن عُمقه المياه .\n16 لا يـُغْرهقُني عاصفُ الماءه ،\n\nولا يربتلعُني العُمقُ ،\nولا تُطْبهقُ البئرُ عليّ فراهرا .\n17 اهسْْرعْني ، يا ربُّ ، فإنى رحْْتركر صالحهةٌ\nاُنْظُرْ إلِرى كركثرة رأفاتهكر .\n18 لا ترصرفْ ورجْهركر عن ف تاكر ،\nاهسْ تمعْني سريعاً ، فإنىني في شدىةٍ .\n19 اُنْظُرْ إلى نفسي ونجرِّها ،\nمن أجله أعدايى أرنْقذْني .\n21 لأنك أنت تعرفُ عارى وخهزْيِه وخجلى\nوقدامك جميع الذين يُحزنونني .\n21 توقـىعرتْ نفسي عاراً وشقاءً\nوانتظرتُ من يُرزنُ معى ، فلم يـُوْجردْ ،\nومن يُعزِّيني فلم أجدْهُ .\n22 جعلوا في طعامى مرارةً ،\nوفي عطشى سقوني خلاًّ .\n23 فلتصرْ مايدتـُهُم أمامرهُ م فرخّاً ،\nومَُازاةً وشكّاً\n24 لهتُظْلهمْ عيونـُهُم فلا يـُبْصروا ،\nولْيـرنْحنه ظرهْرُهُ م في كلِّ حينٍ\n\n25 أفهضْ عليه م رهجْزركر ،\nوغضبُ سُخْطهكر فليُدركْهُ م .\n26 لتصرْ دارُهُم خراباً ،\nوفي مساكنه م لا ير كُ نْ ساكنٌ\n27 لأنْىم طردوا الذي ضربتَهُ أنت ،\nوزادوا على أوجاعه جراحاتهى .\n28 زادوا إثَْاً على إثَْه م ،\nفلا يدخلوا في بهرِّكر\n29 لهيُمْحروْا من سفره الأحياءه ،\nومع الصديقين لا يُكتربوا .\n31 أنا مسكينٌ ومُتروجِّعٌ ،\nوخلاصُ ورجهكر ، يا اللهُ ، عرضردرني .\n31 أُسربِّحُ اسمر الله بالتمجيده ،\nوأُرفـِّعُهُ بالتسبيح ،\n32 فيرُضى اللهُ أفضرلر من عجلٍ فتَّر\nيَُرجُ قروناً وأظلافاً .\n33 فلْيُبصرْ ذلكر المساكينُ ولْيفرحوا ،\nاُطلبوا الله فتحيا نفوسُكُ م .\n34 لأنى الربّ قد استجاب للمساكينه ،\n\nولم يُرذهلْ مُقيىدهيه .\n35 فلتُسبِّحْهُ السماواتُ والأرضُ ،\nالبحرُ وكُلُّ ما يدبُّ فيه .\n36 لأنى الله يَُلِّصُ صهيون ،\nوتُبنِر مُدُنُ اليهوديةه ،\nويسكنونر هناكر ويرثونْرا\n37 ونسلُ عبيدهكر يَرتلكونْرا ،\nوالذين يُُبُّونر اسْْركر يسكنونر فيها .", "69": "المزمورُ التاسعُ والستُّونَ\nإلى النهاية تذكارٌ لداود ، لرمىا خلىصرهُ الربُّ\n2 اللهُمى اهلْترفهتْ إلى معونتَّه\nيا ربُّ أسْ رهعْ وأرعنِِّ\n3 لهيرخْزر ويَرجرلْ طالبو نفسي ،\nوليـر رْ تدْ إلى خلفٍ ويَرجرله الذين يبتغون لِهى الشر\n4 ولْيرجهعْ بالخزى سريعاً القايلونر لي : نعمى ا نهعمى ا .\n5 ولْيبتهجْ ويفرحْ بك جميع الذين يلتمسونركر ،\nولْيقُلْ في كُلِّ حينٍ مُُبُّو خلا صهكر : فلْيتعظىمه الربُّ .\n6 وأما أنا فمسكينٌ وفقيرٌ اللهُمى ، أرع\n\nأنت مُعيني ومخلّصهى يا ربُّ ، فلا تـُبْطئْ .", "70": "المزمورُ السبعونَ\nلداود ، لهبرني يوناداب والذين كانوا في مقدمةه المأسورينر\n1 عليكر يا اللهُ توكىلتُ ،\nفلا تُُْزهني يا ربُّ إلى الدهره .\n2 بهبِهِّكر نجرِّني وأرنْقذْني ،\nأرمهلْ إلِرى سْرْعركر وخرلِّصْني .\n3 كُنْ لي إلهراً ناصراً ،\nوموضعاً حصيناً لتُخلِّصرني\nلأنك أنت هو ثباتهى وملجأى .\n4 يا اللهُ ، نجرِّني من يده الخاطئه ،\nومن يده مُُ الهفه الناموسه والظالَه\n5 لأنك أنت ، يا ربُّ ، هو صبِْى\nالربُّ هو رجايى منذ صباىر .\n6 عليكر استندتُ مُذْ كنتُ في الحشاءه ،\nومنذ أنا في بطنه أمي أنت هو ناصري\nبك تسبحتَّه كلى حينٍ .\n7 صهرتُ مثلر آيةٍ للكثيرينر ،\nوأنت مُعينٌ عزيزٌ .\n\n8 فلْيرمتلئْ فمى تسبيحاً ،\nلكى ما أُسبِّحر مَردركر ،\nواليوم كُلىهُ لهعهظرمه جلالهكر .\n9 لا تطرحْني في زمانه الشيخوخةه ،\nولا تتَْكْني عند فناءه قوىتهى .\n11 لأنى أعدايى تقاولوا عليّ ،\nوالذين يرصدونر نفسي تآمروا معاً قايلينر :\n11 إنى الله قد أهُْرلرهُ\nفاطردوهُ وأدركوهُ ،\nلأنى ليس له مُنْ قه ذٌ .\n12 يا إلهي ، لا تتباعدْ عنِِّ ،\nيا إلهي ، اهلْترفهتْ إلى معونتَّه ،\n13 لهيرخْزر وليُبردْ الذين يشتكونر على نفسي ،\nوليـرلْبرسه العار والخهزْىر الذين يلتمسونر لِهر شرّاً .\n14 أما أنا فتَجىيتُكر كُلى حينٍ ،\nوأرزهيدُ على كُلِّ تسبحةٍ لكر .\n15 فمى يَُبِهُ بهبِهِّكر ،\nوالنهار كُلىهُ بِهلاصهكر ،\nلأني لم أعرفه المكتوباته .\n\n16 فأردْخُلُ في قوىةه الرب\nيا ربُّ ، سأذكُرُ بهرىكر وحدركر .\n17 قد علىمْترني ، يا اللهُ ، منذ صباىر ،\nوإلى الآنه أُخْبِهُ بعجايبك ،\n18 وإلى الشيخوخةه والهرمه يا اللهُ ، لا تتَْكْني عنْكر .\nإلى أنْ أُخْبِهر بذراعهكر لجميع الِيله الآتهى ،\n19 بقوىتهكر ، وعدلهكر ،\nالعظايمر التي صنعترها ، يا اللهُ ، حتَّى إلى العلاءه .\nفمن مهثـْلُكر ، يا اللهُ ؟\n21 لأنك أريترني شدايدر وشروراً كثيرةً ،\nثم عُدْتر فأحييترني ،\n21 ومن أعماقه الأرض أيضاً أصعدترني ،\nأرفرضْتر عليّ بهبِهِّكر .\nثم عُدْتر وعزىيترني ،\nومن الأعماقه أيضاً نرشرلْترني .\n22 لأنني أنا أعتَفُ لكر يا ربُّ بآلةه مزموره حرقِّكر ،\nأُرتِّلُ لكر بقيثارٍ ، يا قدوسر إسراييلر .\n23 تبتهجُ شفتاىر إذا ما رتـىلْتُ لكر ،\nونفسي التي خلىصْترها .\n\n24 ولساني أيضاً طولر النهاره يلهَجُ بهبِهِّكر وفخرهكر ،\nإذا ما خرزهىر وخرجهلر الذين يلتمسو نر لِهر الشرور .", "71": "المزمورُ الحادى والسبعونَ\nلهسليمانر\n1 اللهُمى ، أرعْطه حُكْمركر للمرلهكه ،\nوبهرىكر لابنه المرلهكه ،\n2 لهيرحْكُمر لهشعبك بالعدله ولهمساكينهكر بالحُكْمه .\n3 فلتأخُذه الِبالُ سلاماً لهشعبك ، والآكامُ (بهرّاً ) .\n4 ويقضى لهمساكينه ال شعبه بعدلٍ\nويَُلِّصُ برني البايسينر ،\nويُذهلُّ الكذىابر\n5 ويدومُ مع الشمسه ،\nوقهبرلر القمره لأجياله الأجياله .\n6 يـرنْزلُ مثلر المطره على الِهزىةه ،\nومثلر قطراتٍ تـرقْطُرُ على الأرض .\n7 يُشْرهقُ في أيامه البِهُّ ،\nوكرثْرةُ السلامةه إلى أنْ يضمحلر القمرُ .\n8 ويسودُ من البحره إلى البحره ،\n\nومن النهره إلى أقاصى المسكونةه .\n9 تسبقُ الحبشةُ فتجثو أمامرهُ ،\nوجميع أعدايه يلحسونر التَابر\n11 ملوكُ ترسيسر والِزايره يُقدِّمونر له الهدايا ،\nملوكُ العربه وسربرا يُقرِّبونر له ال عطايا .\n11 ويسجُدُ له جميع ملوكه الأرض ،\nوكُلُّ الأُمرمه تتعبىدُ له .\n12 لأنه نجرىى المسكينر من يده القوى ،\nوالفقير الذي ليس له مُعينٌ\n13 يُشْفهقُ على المسكينه والبايسه ،\nويُنقهذُ أنفسر الفقراءه .\n14 يَُلِّصُ أنفسه م من الرياءه والظُلْمه ،\nويكونُ اسُْْهُم كريَاً لر دريْه .\n15 يُريا ويـُعْطرى من ذهبه العرب ،\nويُصرلُّونر من أجله كُلى حينٍ ،\nاليوم كُلىهُ يُبارهكونره .\n16 ويكونُ سرنرداً على الأرض وعلى أركانه الِباله\nترتفعُ ثَرتُهُ أفضرلر من لبنانر ،\nويـُزْهرُ من المدينةه مثلر عُشْبه الأرض .\n\n17 فليكنْ اسُْْهُ مُباركاً إلى الأبده ،\nقبلر الشمسه يدومُ اسُْْهُ\nوتتباركُ به جميع قبايله الأرض ،\nوكُلُّ الأُمرمه تُرجِّدُهُ .\n18 مباركٌ الربُّ إلهُ إسراييلر ،\nالصانعُ العجايبرٍه وحدرهُ ،\n19 ومُباركٌ هو اسمُ مَرْده القدوسُ\nإلى الدهره وإلى دهره الدهوره\nوترتلئُ الأرضُ كُلُّها من مَرده .\nيكونُ يكونُ .\n21 ترىتْ تسابيحُ داود ابن يسىى .", "72": "المزمورُ الثانِى والسبعونَ\nمزمورٌ لآساف\n1 ما أصلرحر إلهر إسراييلر للمستقيمى القلوبه .\n2 أما أنا فكادتْ ترزهلُّ قدماىر ،\nلولا قليلٌ لرزرلهقرتْ خرطرواتهى .\n3 لأني غهرْتُ على مُُالهفي الناموسه ،\nإذ رأيتُ سلامةر الخطاة\n4 لأنى ليس راحةٌ في موتُه م ،\nولا قوىةٌ في سياطه م\n5 ليسوا في تعبه الناسه ،\nومع البشر لا َُْلردونر .\n6 من أجله ذلكر أر خرذرتـْهُم الكبِْياءُ ،\nاشتملوا ظُلْماً ونفاقاً .\n7 يَرجُ مثلُ الشحمه ظُلْمُهُمْ ،\nجازوا وثبىتوا ما لهقلبه م\n8 ترفكىروا ونطقوا بالشرِّ ،\nتكلىموا ظُلْماً حتَّى إلى العلوِّ\n9 جعلوا أفواهرهُمْ حتَّى إلى السماء ،\nولسانُْم جازر على الأرض .\n\n11 من أجله ذلك يرجهعُ شعبِه إلى هنا ،\nوأيامٌ كاملةٌ تُوجردُ فيهمْ ،\n11 وقالوا كيف عرلهمر اللهُ ؟\nأو عند العليِّ معرفةٌ ؟\n12 فها هؤلاء خطاةٌ هُم ومُُْصهبونر\nوقد حازوا الغهنِر إلى الدهره .\n13 وقـُلْتُ تـُرى هل زكىيْتُ قلبِه باطلًا ،\nوغسلتُ بـرينْ الأبرياءه يردرىى ،\n14 وصرتُ مَرلوداً اليوم كُلىهُ ،\nوتوبيخى إلى أوقاته الغدواته .\n15 إنْ كُنْتُ قـُلْتُ (ذلكر ) فإنِِّ هكذا أتكلىمُ ،\nفهوذا جيلُ بنهيكر الذي تعاهدرتُه .\n16 وجعلتُ في قلبِه أن أرعْلرمر\nوهذا هو تعبٌ قُدىامى ،\n17 حتَّى أد خلر إلى موضعه قدسه الله ،\nوأرفـْهرمر الأواخر .\n18 لأنك (حقّاً ) من أجله غهشِّهم ورضرعْتـرهُم ،\nطرحتـرهُم حينر ارتفعوا .\n19 كيف صاروا قفراً بغتةً ؟\n\nبادوا وهلكوا من أجله إثَْهم .\n21 كرمهثْله حُلْمه الذي يستيقظُ ،\nيا ربُّ ، في مدينتهكر تـُرْذهلُ صورتـرهُم .\n21 لأنه قد احتَرقر قلبِه ،\nوتغيـىرتْ كُلْيتاىر\n22 وأنا كُنْتُ مُهاناً ولم أرعْلرمْ ،\nصرتُ كالبهيمةه عندركر .\n23 وأنا في كُلِّ حينٍ معكر\nأرمْسركْتر بيدى اليُمْنِر ،\n24 وبِهشورتهكر هردريـْترني ،\nوبالمرجْده قبلترني .\n25 لأنه ماذا لي في السماء ؟\nوما الذي أُريدُهُ منكر على الأرض ؟\n26 قد فرنِهر قلبِه وجسدى ،\nإلهُ قلبِه ونصيبِه هو اللهُ إلى الأبده .\n27 لأنه هوذا البعيدونر منكر يرهلكونر\nاستأصلتر كُلى الزناةه عنكر .\n28 وأنا فخريـْرٌ لي الالتصاقُ بالله ،\nوأنْ أجعلر ع لى الربّ اتِّكالي ،\n\nلكى أُخْبِهر بكُلِّ تسابيحهكر\nفي أبوابه ابنةه صهيون .", "73": "المزمورُ الثالثُ والسبعونَ\nفـرهْمٌ لآساف\n1 لماذا أقصيترنا ، يا اللهُ ، إلى المنتهى ؟\nاشتدى غضبُكر على غنمه رعيتهكر .\n2 اُذكُرْ جَراعتركر التي اقتنيترها منذُ القهدرمه\nافتديتر قضيبر ميراثهكر ،\nجبلر صهيون هذا الذي سكنتر فيه .\n3 اهرفرعْ يردركر على تكبُِّهم إلى الانقضاءه ،\nكثيرةٌ هى الشرورُ التي صرنـرعرها العدُوُّ بقدِّيسه يكر .\n4 اهفترخر الذين يُبغضونركر في وسطه عيدهكر ،\n5 جعلوا آياتُهم(+) علاماتٍ ، ولم يعلموا ،\nمثلر طريقه المدخله من فوقُ\n6 وكأنـىهُم في غريْضرةه خرشربٍ قرطرعوا بالفؤوسه أبوابِرا\nوبفأسٍ ومهعْورلٍ معاً طرحوها إلى أسفلُ .\n7 أحرقوا موضهعركر المقدىسر بالناره\n\n)+( راياتُُم أو أصنامُهم ، إشارةً إلى ما حدثر عند خرابه أورشليمر .\n\nدنىسوا على الأرض مسكنر اسْْهكر .\n8 قالوا في قلبهم جميع جنسهم معاً :\nهرلُمى فلنبطهلْ أعيادر الربّ من الأرض .\n9 آياتهنا لم نـرها ،\nليس نبِهٌ موجوداً ، ولا يـرعْرهفُنا بـر عْ دُ .\n11 إلى متى ، يا اللهُ ، يـُعريـِّرُ العدُوُّ ؟\nوالمقاومُ لنا يـُغْضهبُ اسْْركر إلى الغايةه ؟\n11 لماذا ترُدى يردركر ،\nويَرينركر من وسطه حضنهكر إلى الانقضاءه ؟\n12 أما اللهُ فهو مرلهكُنا قبلر الدهوره ،\nصرنرعر خلاصاً في وسطه الأرض .\n13 أنت شدىدتر البحر بقوىتهكر ،\nأنت سحقتر رؤوسر التنانينر على المياه\n14 أنت رضرضتر رؤوسر التنِّينه ،\nوأعطيترهُ طعاماً له شعبه الحبشةه .\n15 أنت فجىرتر العيونر والأوديةر ،\nأنت جففيتر الأنْْار الزاخرةر .\n16 لكر هو النهارُ ، ولكر هو الليلُ أيضاً\nأنت هيىأتر الشمسر والقمر .\n\n17 أنت صنعتر جميع حدوده الأرض ،\nالصيفُ والربيعُ أنت خلقتـرهُما\n18 فاذْكُرْ خليقتركر هذه .\nفالعدُوُّ قد عيـىر الربّ ،\nوشعبٌ جاهلٌ أسخرطر اسْْركر .\n19 لا تُسلِّمْ للوحوشه نفساً تعتَفُ لكر ،\nولا تـرنْسر أنفسر البايسينر إلى الانقضاءه .\n21 اُنْظُرْ إلى عرهْدهكر ،\nلأنى مُظْلهمهى (+) الأرض قد ملأوا البيوتر إثَْاً .\n21 لا يرجعُ المتواضهعُ خازياً\nالفقيرُ والبايسُ يُسبِّحانه اسْْركر .\n22 قُمْ ، يا اللهُ ، اهقْضه قضايى\nاُ ذْكُرْ التعييراته التي صرنـرعرها لكر الِاهلُ النهار كُلىهُ .\n23 ولا تـرنْسر صوتر الذين يتوسىلونر إليك ،\nكبِْياءُ مُبْغضهيكر قد ارتفعر إليك كُلى حينٍ .\n\n)+( بَهسبه النصوصه القديَة ، أى الذين أظلرمرتْ نفوسُهم بالإثم .", "74": "المزمورُ الرابعُ والسبعونَ\nإلى النهاية ، لا تـُهْلهكْ ، مزمورُ تسبحةٍ لآسافر\n2 نعتَرفُ لكر ، يا اللهُ ،\nنعتَرفُ لكر وندعو باسْْهكر .\n3 أُحدِّثُ بِهميعه عجايبك ،\nإذا ما أخذتُ وقتاً\nفأنا أرحكُمُ بالاستقامةه .\n4 ذابته الأرضُ وكُ لُّ الساكنين فيها ،\nأنا ثبىتُ أعمدتُرا . سلام .\n5 قـُلْتُ لهمُخالهفي الناموسه لا تُُالهفوا الناموسر ،\nوللذين يَُطئونر لا تـُعرلُّوا قـرْناً ،\n6 لا ترفعوا إلى العلاءه قـرْنركُم ،\nولا تتكلىموا على الله بالظُلْمه\n7 فإنه لا من المشارقه ولا من المغار به\nولا من الِباله المقفرةه ،\n8 لأنى الله هو الديىانُ\nلهذا يرضرعُ ولهذا يرفعُ .\n9 لأنى بيدى الربّ كأساً مَُتلئةً خَرْراً صهرْفاً مَُتزجاً ،\n\nوأمالهرا من هذا إلى هذا (+)\nلكنّ عركرُها لم يـُهْرقْ ،\nيشربُ منه جميع خطاةه الأرض .\n11 أما أنا فأبتهجُ إلى الأبده ،\nوأُرتِّلُ لإلره يعقوب\n11 أُحرطِّمُ جميع قرونه الخطاة ،\nويرتفعُ قرنُ الصدِّيقه ينر .", "75": "المزمورُ الخامسُ والسبعونَ\nإلى النهاية ، في التسابيح مزمورٌ لآسافر .\nتسبحةٌ ، من أجله الأشورى .\n2 اللهُ ظاهرٌاليهوديةه ه ،\nوعظيمٌ هو اسُْْهُ في إسراييلر .\n3 صار موضهعُهُ بسلامٍ ،\nومسكنُهُ في صهيون\n4 هناكر سرحرقر عهزىةر قهسهيِّهم ،\nسلاحاً وسيفاً وحرباً . سلام .\n5 أنت تضىءُ بالعرجربه من الِباله الأبديةه .\n\n)+( بَهسبه النصوصه القديَةه ، أى من هذا (الإنسان) إلى ذاك .\n\n6 اضطربر كُلُّ عديَى الفهمه في قلبه هم\nهرجرعُوا في نومهم ولم َردوا شيئاً ،\nجميع الرجاله الذين الغهنِر بأيديهمْ .\n7 من انتهارهكر يا إلهر يعقوب ،\nنامر الرُكىابُ على الخيله .\n8 أنت هو مرهوبٌ ، فمن يقدرُ أنْ يُقاوهمركر ؟\nمنذُ القهدرمه رهجْزُكر كاينٌ .\n9 من السرماءه أسْْعتر حُكْماً ،\nالأرضُ فـرزرعرتْ وصرمرترتْ ،\n11 عندر قيامه الله للحُكْمه ،\nلهيُخرلِّصر كُلى وُدعاءه الأرض . سلام .\n11 لأنى فكر الإنسانه يعتَرفُ لكر ،\nوبقيىةُ الفكره تُعيِّدُ لكر .\n12 أنذروا وأوفوا للربِّ إلهرهكُمْ\nكُلُّ المحيطين به يُقدِّمونر له القرابينر ،\n13 المرهوبُ والذي ينْزعُ أرواحر الرؤساءه ،\nالمرخوفُ عندر جميع ملوكه الأرض .", "76": "المزمورُ السادسُ والسبعونَ\nإلى النهاية ، عن إيديثونر مزمورٌ لآسافر\n2 بصوتي إلى الربّ صرخت ،\nوصوتي إلى الله ، فأرصْغرى إلِرى .\n3 في يومه شهدىتهى اهلْترمرسْتُ الله ،\nبيدرىى في الليل قُدىامرهُ ولم أرنَْردهعْ\nولم تشأْ نفسي أنْ تـُعرزىى .\n4 ذركرْتُ الله ففرحتُ\nتـرلروْتُ فرصرغُرتْ روحى . سلام .\n5 سربرقر جميع أعدايى فأدركوا مُرارسى\nقرلهقْتُ ولم أتكلىمْ .\n6 تـرفركىرْتُ في الأيامه الأُولِر ،\nوتذكىرْتُ في السنين الأبديةه\n7 فهرذرذْتُ الليل بهقلبِه ،\nتفرىغْتُ وفرحرصْتُ روحى .\n8 هل يُقصيني الربُّ إلى الأبده\nولا يعودُ أنْ يُسرى بـرعْدُ ؟\n9 أو يقطعُ رحْْرترهُ إلى الانقضاءه\nمن جيلٍ إلى جيلٍ ؟\n\n11 هل ينسرى اللهُ أنْ يتَرأفير ،\nأو يَرنعُ في سُخْطه رأفاته ؟ سلام .\n11 فقُلْتُ الآنر ابتدأتُ ،\nهذا هو تغييرُ يَرينه العليِّ .\n12 ترذّكىرْتُ أرعمالر الربّ ،\nلأني أتذكىرُ عجايبركر منذ البدءه ،\n13 وأرهذُّ بسايره أعمالهكر ،\nوبهصنايعهكر أُنا جهى .\n14 يا اللهُ ، في القدسه طريقُكر\nأىُّ إلرهٍ عظيمٌ مثلُ إلهرهنا ؟\n15 أنت هو اللهُ صانعُ العجايبرٍه ،\nأرظْهرْتر في الشعوبه قوىتركر\n16 خرلىصْتر بهذراعهكر شعبركر ،\nبرني يعقوب ويوسفر . سلام .\n17 أربْصرتْكر المياهُ ، يا اللهُ ،\nرأرتْكر المياهُ فـرفرزهعرتْ ،\n18 اضطربرته الأرعماقُ من كثرة دروهىِّ المياه\nأعطرته السُّحُبُ صوتُرا ، لأنى سهامركر تسيرُ\n\n19 صوتُ رُعودهكر في البركْرة (+)ٍه ،\nأضاءرتْ بُروقُكر المسكونةر ،\nتزلزلرته الأرضُ وارتعدرتْ .\n21 يا اللهُ ،في البحره طريقُكر ،\nوسُبـُلُكر في المياه الكثيرةه ،\nوآثارُكر لا تُعرفُ .\n21 هردريْتر شعبركر كالغنمه بيده موسرى وهارونر .", "77": "المزمورُ السابعُ والسبعونَ\nفـرهْمٌ لآسافر\n1 اهصْغر يا شعبِه إلى شريعتَّه ،\nأميلوا آذانركُم إلى كلامه فمى .\n2 أرفتحُ بالأمثاله فمى ،\nوأنطقُ بالخفيىاته منذُ الابتداءه ،\n3 التي سْرعناها وعرفناها ،\nوآباؤنا أرخبِرونا\n4 ولم يَُْفوا عن بنيهم إلى الِيله الآخره ،\nمُُبِهينر بتسابيحه الربّ\n\n)+( أى ”العجلة“ بَهسب النصوص القديَة وفي ترجَرةٍ حديثةٍ : ”الزوبعة“.\n\nوقُدْرته ، والعجايبه التي صرنـرعرها .\n5 أقامر شهادةً في يعقوب ،\nورورضر عر ناموساً في إسراييلر ،\nالذي أوصرى به لآباينا ،\nلكى يـُعرِّفوا بِهما أبناءرهُم\n6 لكى ما يـرعْلرمُ الِيلُ الآخرُ ،\nالبنونُ الذين يُولردونر ،\nفيقومونر ويَُبِهونر بِهما أبناءرهُم\n7 لكى َرعلوا رجاءهُم بالله ،\nولا ينسونر أعمالر الله ،\nويلتمسونر وصاياه\n8 لئلا يصيروا مثلر آبايهم\nجيلاً شرِّيراً مَُرْمهراً ،\nالِيلُ الذي لم يستقمْ قلبُهُ ،\nولا آمرنرتْ روحُهُ بالله .\n9 بنو أفرايمر أوتروا ورموا بالقهسهىِّ ،\nاهنـْهرزموا في يومه الحربه\n11 ولم يُرفظوا عهدر الله ،\nولم يـرهْوروْا أنْ يسلكوا في ناموسه .\n\n11 ونسوا أعمالرهُ الحسنةر ،\nوعجايبرهُ التي أراهُم إياها .\n12 العجايبر التي صرنـرعرها قُدىامر آبايهم ،\nفي أرضه مهصر في حقله صاعان .\n13 شرقى البحر فأجازرهُم فيه ،\nأوقرفر المياهر مثلر زهقٍّ\n14 وهرداهُم بالسحابةه في النهاره ،\nوفي ا لليله كُلِّه بضوءه الناره\n15 شرقى صرخْرةً في البـرِّيةه ،\nوسقاهُم كرما مهنْ عُمقٍ كثيرٍ\n16 وأرخْرجر ماءً من صرخْرةٍ ،\nفرجرته المياهُ كالأنهار .\n17 ثم عادوا أيضاً لهيُخْطئوا إليه\nوأغضبوا العليى في موضعٍ ليس به ماءٌ ،\n18 وجرىبوا الله في قلوبِهم ،\nليرسألوا أطعمةً لأنفسهم .\n19 وتكلىموا على الله\nوقالوا هل يقدرُ اللهُ أنْ يُهيِّئ مايدةً في البـرِّيةه ؟\n21 هوذا ضربر الصرخْرةر فرجرته المياهُ ،\n\nوفاضته الأوديةُ\nفهل يقدرُ أنْ يُعطيـر نرا خُبْزاً أيضاً ؟\nأو يُهيِّئُ مايدةً لهشعبه ؟\n21 من أجله هذا سْرهعر اللهُ وطرحرهُم إلى خرلْفٍ ،\nواشتعلته النارُ في يعقوب ،\nوأترى الرهجْزُ على إسراييلر\n22 لأنْىم لم يؤمنوا بالله ،\nولا اتىكلوا على خلاصه .\n23 فأرمر السحابر من فوقُ ،\nوفـرترحر أبوابر السماء\n24 وأرمْطر عليهم مرنّاً لهيأكلوا ،\nوخُبـْزر السماء أعطاهُم\n25 وأركرلر الإنسانُ خُبـْزر الملايكةه ،\nأرسرلر لهرُم طعاماً للشهبرعه .\n26 حرىكر ريحر الِنوبه من السماء ،\nوأترى بهقوّته (بالريحه ) الغربيةه ،\n27 وأرمْطر عليهم لحُُوماً كالتَُابه ،\nوكرمْله البحره طُيوراً ذواته أجنحةٍ\n28 وسقطرتْ ورسرطر مُرلىتهم ،\n\nحولر مساكنهم .\n29 فأكلوا وشربهعوا جداً ،\nوأتاهُم بهشهوتُهم .\n31 لم يعجزوا(+) من شرهوتُهم\nوإذْ كانر طعامُهُم بـرعْدُ في أفواهم ،\n31 غرضربُ الله أترى عليهم\nوقـرترلر في أكثرهم ،\nوعرْقرلر مُُتارى إسراييلر .\n32 وفي هذه كُلِّها أخطأوا إليه أيضاً ،\nولم يؤمنوا بهعجايبه\n33 فـرفرنهيرتْ أيامُهُم بالباطل ،\nوسهنهيـُّهُم بسرعةٍ .\n34 فلرمىا قـرتـرلرهُم حينئذٍ صاروا يطلبونه ،\nورجهعوا وبركىروا إلى الله\n35 وذركروا أنى الله هو مُعينـُهُم ،\nواللهُ العلهىُّ هو مُُلِّصُهُم .\n36 فأحبُّوهُ بأفواهم ،\nوكرذهبوا عليه بألسنتهم\n\n)+( لم يُسركِّنوا .\n\n37 أما قلبـُهُم فلم يكُنْ مستقيماً معهُ ،\nولا آمنوا بهعهده .\n38 أما هو فرؤوفٌ\nيغفرُ لهرُم خطاياهُم ،\nولا يـُهْلهكُهُم\nويُكثهرُ في أنْ يـرُدى غرضربرهُ ،\nولم يُشْعهلْ كُلى رهجْزه .\n39 ذركر أنـىهُم أجسادٌ ،\nروحٌ إذا خرجرتْ لا تعودُ بـرعْدُ .\n41 كرمْ مهنْ مرىةٍ مرْمروهُ في البـرِّيةه ،\nوأغضبوهُ في مكانٍ بلا ماءٍ ؟\n41 وعادوا وجرىبوا الله ،\nوأغاظوا قدُّوسر إسراييلر .\n42 ولم يذكُروا يردرهُ ،\nفي اليومه الذي أنقذرهُم فيه مهنْ يرده مُضايقهيهم\n43 حيثُ مجّد بِهصْر علاماته ،\nوعجايبرهُ في حقله صاعان .\n44 إذْ حروىلر أنْْارهُم إلى دمٍ ،\nوينابيعرهُم لكى لا يشربوا .\n\n45 أرسرلر عليهم ذُبابر الكلبه فأكلرهُم ،\nوالضفادعر فأفسدرتـْهُم .\n46 أرسْلرمر أثَْارهُم للدوده ،\nوتعبـرهُم للجراده .\n47 أتلفر بالبـرده كُرومرهُم ،\nوجَُِّيزرهُم بالصقيعه\n48 وأرسْلرمر إلى البـرده بِرايمرهُم ،\nوكُلى ما لهرُم للناره\n49 أرْسرلر عليهم سُخْطر غضبه ،\nغرضرباً ورهجْزاً وشهدىةً ،\nأرْسرلرها على يرده ملايكةٍ أشرارٍ\n51 صرنرعر طريقاً لهغرضربه ،\nولم يُشْفهقْ على أنفسهم من الموته ،\nوحربرسر بالموته بِرايمرهُم\n51 وضربر كُلى بهكْرٍ في مهصْر ،\nأوايلر أتعابِهم في مساكنهم .\n52 وساقر مثلر الغنمه شعبرهُ ،\nوأرخْرجرهُم كقطيعه الغنمه إلى البـرِّيةه\n53 هرداهُم بالرجاءه فلم َرزعوا ،\n\nوغرطىى البحرُ أعداءرهُم .\n54 وأدخرلرهُم إلى جربرله موضعه المقدىسه ،\nالِبله الذي اهقـْتـرنرتْ هُ يَرينُهُ\n55 وطردر أُمَراً من قُدىامه ورجْهم ،\nوأعطاهُم ميراثاً بَهربْله ميراثه العطيةه ،\nوأرسْكرنر في مساكنهم قبايلر إسراييلر .\n56 فرجرىبوا ومرْمروا الله العليى ،\nولم يُرفظوا شهاداته\n57 وارتدُّوا وصاروا غريـْر مُوفىقه ينر مثلر آبايهم ،\nوانقلبوا مثلر القوسه المُعوجِّ\n58 وأغضبوهُ بِهُرتفعاتُهم ،\nوبِهرنحوتاته أيدهيهم أغاروهُ .\n59 سْرهعر اللهُ وتغافرلر عنهُم ،\nورذرلر إسراييلر جداً\n61 وأرقْصرى مرظرلىةر شيلومر ،\nومرسْكرنُهُ لم يسكُنْهُ مع الناسه\n61 وأرسْلرمر قوىتـرهُم للسربِِّْ ،\nوجَر الهرُم لهيرده أعدايهم\n62 وسردى أفواهر شعبه بالسيفه ،\n\nوترغافرلر عن ميراثه .\n63 شُبىانـُهُم أكلرتـْهُم النارُ ،\nوعذاراهُم لم يـرنُحْنر\n64 وكهنتـُهُم وقعوا بالسيفه ،\nوأراملُهُم لم يبكه ينر عليهم .\n65 واستيقظر اللهُ كالنايمه ،\nمه ثْ لر الِبىاره المُفيقه من الخرمْره\n66 فرضربر أعداءرهُ إلى ورايهم ،\nوأعطاهُم عاراً أبدياً .\n67 وأقصى مُرلىةر يوسفر ،\nولم يَرْتـرْ قبيلةر أفرايمر\n68 واختار سهبْطر يرهوذا ،\nجربرلر صهيون الذي أرحبىهُ .\n69 وبـرنِرمثلر وحيده القرنه موضهعرهُ المقدىسر ،\nوأسىسرهُ على الأرض إلى الأبده .\n71 واختار داود عربْدرهُ ،\nوأرخرذرهُ من قطيعه الغنمه\n71 من خلفه المُرضهعاته أرخرذرهُ ،\nلهيرعرى يعقوب عربْدرهُ ،\n\nوإسراييلر ميراثرهُ .\n72 فرعاهُم بهدهعرةه قلبه ،\nوبهفرهْمه يردريْه هرداهُم .", "78": "المزمورُ الثامنُ والسبعونَ\nمزمورٌ لآسافر\n1 اللهُمى ، إنى الأُمرمر قد دخلوا ميراثركر ،\nنجرىسوا هيكلركر المقدىسر ،\nجرعرلوا أورشليمر مثلر مُرْرسٍ خرهبٍ\n2 جرعرلوا أمواتر عبيدهكر طعاماً لهطيوره السماء ،\nولحُومر قدِّيسه يكر لهوحوشه الأرض\n3 أهرقوا دماءرهُم مثلر الماءه حولر أورشليمر ،\nوليس من يردْفهنـُهُم .\n4 فصرنا عاراً لِهيرانهنا ،\nهُزْءاً وسُخْريةً للذين حولرنا .\n5 إلى متى ، يا ربُّ ، تسخطُ إلى الانقضاءه ؟\nوتتىقهدُ كالناره غهيرتُكر ؟\n6 أرفهضْ ره جْزركر على الأُمرمه الذين لا يعرفونركر ،\nوعلى المرمالهكه التي لا تدعو باسْْهكر .\n\n7 لأنـىهُم قد أكلوا يعقوب ،\nوأخربوا موضهعرهُ .\n8 لا ترذْكُرْ آثامرنا الأولِر\nفـرلْتُدركْنا رأفاتُكر سريعاً ،\nلأننا قد ترسْكرنىا جداً .\n9 أرعهنىا، يا اللهُ مُُلِّصرنا ،\nمن أجله مَرْده اسْْهكر ، يا ربُّ ، تـُنرجِّينا ،\nوتغفرُ لنا خطايانا من أجله اهسْْهكر\n11 لئلا يُقالر في الأُمرمه أينر هو إلهرُهُم ؟\nولْيـُعْلرمْ في الأُمرمه قُدى امر أعينهنا\nانتقامُ دمه عبيدهكر المسفوكه .\n11 فـرلْيردْخُلْ قُدى امركر تنهُّدُ المُقيىدينر ،\nكعظمةه ذراعهكر اهقـْتَره برني المقتولينر .\n12 جرازه جهيرانرنا سبعةر أضعافٍ في أحضانْهم ،\nبهعارهم الذي عريرىوكر به ، يا ربُّ .\n13 لأننا نُرنُ شعبُكر وغرنرمُ رعيتهكر\nنُرْمردُكر إلى الدهره ،\nمن جيلٍ إلى جيلٍ نَُْبِهُ بتسبحتهكر .", "79": "المزمورُ التاسعُ والسبعونَ\nإلى النهاية ، على الذين يتغيرىونر\nشهادةٌ لآسافر ، مزمورٌ عن الأشوريينر .\n2 يا راعهىر إسراييلر ، أرنْصهتْ ،\nيا مُهدهىر يوسفر كرخروفٍ\nيا جالساً على الشاروبيمر اهظْهرْ ،\n3 قُدىامر أفرايمر وبنيامينر ومنسىى ،\nأرنْْهضْ قوىتركر وهرلُمى لخهلاصهنا .\n4 يا اللهُ اُرْدُدْنا ،\nولْيُ نهرْ ورجْهُكر علينا ، فنخلُصر .\n5 أيُها الربُّ إلهر القوىاته ،\nإلى متى تسخطُ على صلاةه عبدهكر ؟\n6 قد أطعمْترنا خُبـْزر الدموعه ،\nوسقيترنا العربِراته بالكيله .\n7 جرعرلترنا للمناقضةه(عند) جيرانهنا ،\nواستهزأر بنا أعداؤنا .\n8 يا ربُ إلهر القواته ، اُرْدُدْنا\nولْيُنهرْ ورجْهُكر علينا ، فنخلُص . سلام .\n9 نقلتر كرمةً مهنْ مصر ،\n\nأخرجْتر أُمَراً وغرسترها\n11 هيىأتر الطريق أمامرها ،\nوغرستر أصولهر ا فامتلأرته الأرضُ .\n11 غطىى على الِباله ظهلُّها ،\nوأغصانُْا على أرْزه الله\n12 مردىتْ قضبانْرا إلى البحره ،\nوإلى النهره فروعرها .\n13 فلماذا هدرمْتر سياجرها ،\nفيقتطفُها كُلُّ عابرى الطريقه ؟\n14 أفسدرها خهنْزيرُ الِبله من الغابةه ،\nورعاها حْهارُ الورحْشه .\n15 أيُها الربُّ إلهر القوىاته ، اهرْجهعْ الآنر ،\nاهطىلهعْ من السماء وانْظُرْ ،\nوتعهىدْ هذه ه الكرمةر\n16 أرصْلهحْها وثـربِّتْها ، هذه التي غرسرتْها يَرينُكر ،\nوعلى ابن الإنسانه هذا الذي شردىدرتره لكر .\n17 لأنـىهُم قد أحرقوها بالناره وقـرلربوها\nمن انتهاره ورجْهكر يرهلكونر .\n18 فلتكُنْ يردُكر على إنسانه يمينك ،\n\nوعلى ابنه الإنسانه هذا الذي شردىدرتره لكر\n19 فلا نبتعدر عرنْكر\nفتُحيينا ، وندعو باسْهكر .\n21 أيُها الربُّ إلهر القوىاته ، اُرْدُدْنا ،\nور لْيُنهرْ ورجْهُكر علينا ، فنرخْلُصر .", "80": "المزمورُ الثمانونَ\nإلى النهاية ، على المعاصره مزمورٌ لآسافر\n2 اهبتهجوا بالله مُعينهنا ،\nهرلِّلوا لإله يعقوب\n3 خُذوا مزماراً وأُعطوا دُفّاً ،\nمزماراً حسناً مع قيثارٍ\n4 بوِّقوا في رأسه الشهره بالبوق ،\nفي يومه عيدهكُم المشهوره ،\n5 لأنه أمرٌ لإسراييلر هو ،\nوحُكْمٌ لإله يعقوب\n6 مجّدهُ شهادةً في يوسفر ،\nعندر خُروجه من أرضه مهصر .\nلساناً لم يكُنْ يعرفُهُ سْرهعرهُ ،\n\n7 ردى ظرهْرهُ عن الأحْْاله ،\nيداهُ تعبىدر تا بالقُفىةه .\n8 في الشهدىةه دعوترني فنجىيتُكر\nسْرهعتُكر من خفاءه العاصفه ،\nجرىبتُكر على ماءه المقاومةه . سلام .\n9 اهسْْرعْ ، يا شرعْبِه ، فأُكلِّمركر\nويا إسراييلر ، فأشهدر لكر .\n11 إنْ أنت سْرهعْتر لي ،\nلا ير كُ نْ فيكر إلهٌ جديدٌ ،\nولا تسجدْ لإلهٍ آخر غريبٍ .\n11 لأني أنا هو الربُّ إلهرُكر ،\nالذي أرخرجركر من أرضه مهصر\nأروْسهعْ فاكر فأرملأرهُ .\n12 فلم يسمعْ شعبِه لهصوتي ،\nوإسراييلُ لم يلتفتْ إلِرى\n13 فأرسلتُ إليهم كأعماله قلوبِهم ،\nفيسلكونر في صنايهعهم .\n14 فلو أنى شعبِه أطاعرني ،\nوإسراييلُ لو سرلركر في سُبُلهى ،\n\n15 لكُنْتُ إذاً بلا شىءٍ أُذهلُّ أعداءرهُم ،\nوكُنْتُ أرفعُ يدى على الذين يُضيِّقونر عليهم .\n16 أعداءُ الربّ كذبوا عليه ،\nفيكونُ زمانـُهُم إلى الأبده\n17 أرطْعرمرهُم من شرحمه الحنطةه ،\nوأرشْبـر عرهُم عسلاً من الصخرةه .", "81": "المزمورُ الحادى والثمانونَ\nمزمورٌ لآسافر\n1 قامر اللهُ في مَرْمرعه الآلهةه ،\nوفي الوسطه يدينُ الآلهةر .\n2 إلى متى تقضونر بالظُلْمه ،\nوبوجه الخطاة تأخذونر ؟ سلام .\n3 اُحْكُموا لليتيمه والفقيره ،\nزركُّوا المتواضعر والبايسر\n4 أرنْقهذوا المسكينر والضعيفر ،\nوخلِّ صوهُُا من يده الخاطئ .\n5 لم يعلرموا ولم يفهموا ،\nإنـىهُم في الظلمة يسلكونر\n\nتترزعزعُ جميع أساساته المسكونةه .\n6 أنا قـُلْتُ إنكُم آلهةٌ ،\nوبنو العليِّ كُلُّكُم\n7 لكن مثلر البشر أ نتم تروتونر ،\nوكأحده الرؤساءه تسقطونر .\n8 قُمْ ، يا اللهُ ، دهنْ الأرضر\nلأنك أنت ترثُ في جميع الأُمرمه .", "82": "المزمورُ الثانِى والثمانونَ\nتسبحةُ مزمورٍ لآسافر\n2 يا اللهُ ، من يُشْبهُكر ؟\nلا تسكُتْ ولا تُردأْ ، يا اللهُ\n3 فهوذا أعداؤُكر قد صرخوا ،\nوقد رفرعر مُبغضوكر رؤوسرهُم\n4 تشاوروا بالمكره على شعبك ،\nوتآمروا على قدِّيسه يكر\n5 قالوا هلُمى نستأصهلُهُم من الأُمرمه ،\nولا يُذْكرُ اسمُ إسراييلر بـرعْدُ\n6 تآمروا جَريعاً بقلبٍ واحدٍ ،\n\nوتعاهدوا عليكر عرهْداً ،\n7 مساكنُ الأدوميينر والإسْْاعيليينر ،\nمُوآبُ والهاجريونر ،\n8 جيبالُ وعمُّون وعماليقُ ،\nقبايلُ الغرباءه مع سكىانه صور\n9 وأشورُ أيضاً أترى مر عر هُ م ،\nوصاروا نُصْرةً لهبرني لوط .\n11 اهصْنرعْ مرعر هُ م مثلر مديان وسيسرا ،\nومثلر يابن في وادى قيسون\n11 قد استُؤصهلوا في عرينْه دورٍ ،\nوصاروا مثلر ترابه الأرض .\n12 اهجْعرلْ رؤساءرهُم مثلر عوريب وزيب وزاباح وصلمناع ،\nجميع رؤسايهم ،\n13 الذين قالوا فلْنرهثْ لنا مذبرحر الله .\n14 يا إلهي ، اهجْعرلْهُم مثلر بركرةٍ ،\nومثلر قصبةٍ أمامر ورجْه الريحه .\n15 مثلر الناره التي تُُْرهقُ الغريْضرةر ،\nوكاللهيبه الذي يُشْعهلُ الِبالر ،\n16 هكذا تطرُدُهُم بعاصفهكر ،\n\nوبرهجْزهكر تـُقْلهقُهُم.\n17 وترلأُ وُجوهرهُم هواناً ،\nفيطلبون اسْْركر ، يا ربُّ .\n18 فلْيرخْزروْا ويضطربوا إلى أبده الأبده ،\nولْيرخجلوا ويرهلكوا\n19 وليعلموا أن اسْْركر الربُّ ،\nوأنت وحدركر العليُّ على كُلِّ الأرض .", "83": "المزمورُ الثالثُ والثمانونَ\nإلى النهاية ، على المعاصره ، مزمورٌ لهبرني قورحر\n2 مساكنُكر مُربوبةٌ ،\nيا ربُّ إلهر القوىاته .\n3 تشتاقُ وتذوبُ نفسي للدخوله إ دياره الربّ\nقلبِه وجسمى قد ابتهجا بالإله الحىِّ .\n4 لأنى العصفور ورجردر له بيتاً ،\nواليمامةر عُشّاً لتضعر فيه أفراخرها\nمذابَهركر يا ربُّ إلهر القوىاته ، مرلهكى وإلهي .\n5 طوبى لهكُلِّ السكىانه في بيتهكر ،\nيباركونركر إلى أبده الأبده . سلام .\n\n6 طوبى للرجله الذي نُصْرتُهُ من عندهكر ، يا رب\nرتىبر مرصاعهدر في قلبه ،\n7 في وادى البكاءه ، في المكانه الذي قـرىره .\nلأنى البِركاته يُعطيها واضعُ الناموسه\n8 يسيرونر من قوىةٍ إلى قوىةٍ ،\nيظهرُ إلهُ الآلهةه في صهيو نر .\n9 أيُها الربُّ إلهر القوىاته ، اهسْتمعْ صلاتي ،\nأرنْصهتْ ، يا إلهر يعقوب . سلام .\n11 اُنْظُرْ يا اللهُ ناصر نا ،\nواطىلهعْ على ورجْه مسيحهكر .\n11 لأنى يوماً صالحهاً في ديارهكر أفضرلُ من آلافٍ\nاختَتُ لنفسي أن أُطرحر في بيته الله\nأفضرلر من أنْ أسكنر في مظاله الخطاة .\n12 لأنى الربّ الإلهر يُُبُّ الرحْْةر والحق ،\nويُعطى مَرداً ونعمةً للذين يسلكونر بالدهعرةه ،\nولا يدرعُهُم الربُّ مُعورزهينر من الخيرْاته .\n13 يا ربُّ إلهر القوىاته ،\nطوبى للإنسانه المتىكهله عليكر .", "84": "المزمورُ الرابعُ والثمانونَ\nإلى النهاية مزمورٌ لهبرني قورحر\n2 رضهيتر ، يا ربُّ ، عن أرضهكر ،\nردردْتر سربِْر يعقوب\n3 غفرتر آثامر شعبك ،\nسرتـرْتر جميع خطاياهُم . سلام .\n4 حرلرلْتر كُلى رهجْزهكر ،\nرجعتر عن سُخْطه غضبك .\n5 اُرْدُدْنا يا إلهر خلاصهنا ،\nواصْرهفْ غضبركر عنى ا .\n6 فهل إلى الأبده تغضبُ علينا ؟\nأو تُواصهلُ رهجْزركر من جيلٍ إلى جيلٍ ؟\n7 أنت ، يا اللهُ ، تعودُ فـرتُحْيهينا ،\nوشعبُكر يفرحُ بك .\n8 أرهنا ، يا ربُّ ، رحْْتركر ،\nوأرعْطهنا خلاصركر .\n9 سأسْْعُ ما يتكلىمُ به الربُّ الإلهُ فىهى ،\nلأنه يتكلىمُ بالسلامه لهشعبه ولهقدِّيسه يه\nوللذين رجهعوا إليه بكُلِّ قلبهم .\n\n11 بل إنى خلاصرهُ قريبٌ من جميع خايفهيه ،\nليسكنه المر جدُ في أرضهنا .\n11 الرحْْةُ والحقُّ تلاقريا ،\nالبِهُّ والسلامُ تلاثَرا\n12 الحقُّ من الأرض أشرقر ،\nوالبِهُّ من السماء ترطلىعر .\n13 لأنى الربّ يُعطى الصلاحر ،\nوأرضُنا تُعطى ثمرها .\n14 البِهُّ أمامرهُ يَرضى مُتقدِّماً ،\nويضعُ في الطريقه خرطرواته .", "85": "المزمورُ الخامسُ والثمانونَ\nصلاةٌ لداود\n1 أرمهلْ ، ي ا ربُّ ، أُذُنركر واسْتمهعْني ،\nلأني مسكينٌ وبايسٌ أنا .\n2 اهحْفرظْ نفسي لأني بارٌّ ،\nيا إلهي ، خرلِّصْ عبدركر المتىكهلر عليكر .\n3 ارحمني ، يا ربُّ ، فإنِِّ صرخت إليك النهار كُلىهُ .\n4 فـرِّحْ نفسر عبدهكر ،\n\nفإنِِّ إليك ، يا ربُّ ، رفعتُ نفسي .\n5 لأنك أنت صالهحٌ ، يا ربُّ ، أنت وديعٌ ،\nورحْْتُكر كثيرةٌ لهسايره المستغيثينر بك .\n6 أرنْصهتْ ، يا ربُّ ، لهصلاتي ،\nوأرصْغه إلى صوته تضرُّعى .\n7 في يومه شدىتهى إليك صر ر خْ تُ ،\nلأنك أجبْترني .\n8 ليس في الآلهةه من يُشبهُكر ، يا ربُّ ،\nولا من يصنعُ كأعمالهكر .\n9 كُلُّ الأُمرمه الذين خرلرقتـرهُم يأتونر\nويسجدونر أمامركر ، يا ربُّ ،\nويَُجِّدونر اسْْركر\n11 لأنك أنت عظيمٌ وصانعُ العجايبه ،\nأنت وحدركر الإلهُ العظيمُ .\n11 اهْدهني ، يا ربُّ ، في طريقهكر ،\nفأسلُكر في حقِّكر\nفـرلْيفرحْ قلبِه عندر خروْفه من اسْْهكر .\n12 أعتَرفُ لكر ، أيُها الربُّ إلهي ، من كُلِّ قلبِه ،\nوأُمَرِّدُ اسْْركر إلى الأبده\n\n13 لأنى رحْْتركر عظيمةٌ عليّ ،\nوقد نجرىيتر نفسي من الِحيمه السُفلهى .\n14 اللهُمى ، إنى مُُالهفه ى الناموسه قد قاموا عليّ ،\nومَرمعر الأعزىاءه طلبوا نفسي\nولم يسبقوا أنْ َرعلوكر أمامرهُم .\n15 وأنت أيُها الربُّ الإلهُ ، أنت رؤوفٌ ورحيمٌ ،\nأنت طويلُ الروحه وكثيرُ الرحْْةه وصادقٌ .\n16 اُنْظُرْ إلِرى وارْحْرْني ،\nأر عْطه عهزىةً لهعبدهكر ، وخرلِّصْ ابنر أرمرتهكر .\n17 اهصْنرعْ معى آيةً صالحهةً ،\nفـرلْيـر الذين يُبغضونرني ، ورلْيرخْزروْا ،\nلأنك أنت ، يا ربُّ ، أعنترني وعزىيترني .", "86": "المزمورُ السادسُ والثمانونَ\nمزمورُ تسبحةٍ لهبرني قورحر\n1 أساساتُهُ في الِباله ا لمقدىسةه\n2 يُُبُّ الربُّ أبوابر صهيون\nأفضلر من جميع مساكنه يعقوب .\n3 أعمالٌ كريَةٌ قد قهيلرتْ عرنْكه يا مدينةر الله . سلام .\n\n4 أرذْكُرُ راحابر وبابلر اللتـرينْ تعرفاني\nوهو ذا القبايلُ الغريبةُ وصورُ وشعبُ الحبشةه\nهؤلاء كانوا هناكر .\n5 صهيونُ الأُمُّ تقولُ إنى إنساناً ،\nوإنسانٌ صار فيها ،\nوهو العليُّ الذي أسىسها إلى الأبده .\n6 الربُّ يُُدِّثُ في كُتُبه الشعوبه والرؤساءه ،\nأولئكر الذين سكنوا فيها . سلام .\n7 لأنى مسكنر جميع الفرحينر فيكه .", "87": "المزمورُ السابعُ وال ثمانونَ\nتسبحةُ مزمورٍ لهبرني قورحر إلى النهاية ،\nعلى ماحهلاته للجوابه فـرهْمٌ لهنامان الإسراييلى .\n2 يا ربُّ إلهر خلاصى ،\nبالنهار والليل صرخت إليك\n3 فـرلْتدخُلْ قدامك صلاتي ،\nيا ربُّ ، أرمهلْ سْرْعركر إلى طلبتَّه .\n4 فقد اهمتلأرتْ من الش رِّ نفسي ،\nوحياتهى إلى الِحيمه درنرتْ .\n\n5 حُسهبْتُ مع المُنحدهرهينر في الُِبِّ ،\nصهرْتُ مثلر إنسانٍ ليس له مُعينٌ ،\n6 صهرتُ حُرّاً بـرينْ الأمواته\nمثلر قتلرى مرطروحينر راقدينر في القبوره ،\nالذين لا ترذكُرُهُم بـرعْدُ ،\nورهُمْ من ير دريْكر مُقصُونر\n7 جرعلوني في جُبٍّ سُفْلهىٍّ ،\nفي مواضعر مُظْلهمةٍ وظلاله الموته .\n8 اهشْتردى عليّ غرضربُكر ،\nوجميع أهوالهكر أرجرزْتُرا عليّ . سلام .\n9 أربـْعردْتر معارهفىه عرنِِّ ،\nجرعرلوني رذالةً لهرُم\nقد أُسْلهمْتُ ولم أكُنْ أرخْرُجُ .\n11 عيناىر ضرعُفرتا من المسكنةه\nوصرخت إليك ، يا ربُ ، النهار كُلىهُ ،\nبرسرطْتُ نُرْوركر يردرىى .\n11 أرفرلهعرلىكر للأمواته ترصنعُ عجايبركر ؟\nأو أنى الأطبىاءر يُقيمونـرهُم فيعتَرفونر لكر ؟\n12 هل يَُْبِهُ أرحردٌ في قـربٍِْ بهرحْْتهكر ،\n\nأو بَهرقِّكر في الهلاكه ؟\n13 هل تـُعْرفُ في الظلمة عرجايبُكر ،\nوعدلُكر في أرضٍ منسيىةٍ ؟\n14 أما أنا فإليك ، يا ربُّ ، صرخت ،\nوفي الأسْحاره ترسْبهقُ وتبلُغُ إليك صلاتي .\n15 لماذا ، يا ربُّ ، تـُقْصهى صلاتي ،\nوصرفْتر ورجْهر كر عرنِِّ ؟\n16 أنا مسكينٌ أنا ، وفي الأتعابه منذُ حداثتَّه ،\nوحين ارتفعتُ اهتضعتُ وتُريرىتُ .\n17 أرترتْ عليّ سرخرطاتُكر ،\nومُفزعاتُكر أزعر جر تْ ني .\n18 أحاطرتْ بي مثلر المياه ،\nاهكترنفتْني اليوم كُلىهُ معاً .\n19 أربـْعردْتر عرنِِّ الصردهيقر\nومرعارهفىه من شقايى .", "88": "المزمورُ الثامنُ والثمانونَ\nفـرهْمٌ لإيثانر الإسراييلى\n2 مراحْهُكر ، يا ربُّ ، أُسربِّحُ بِها إلى الدرهْره ،\n\nمن جيلٍ إلى جيلٍ أُخْبِهُ بَهرقهكر بفمى .\n3 لأنك قـُلْتر إنى الرحْْةر تـُبـْنِر إلى الأبده ،\nوحرقُّكر في ال سرماواته مُهريىأٌ\n4 قرىرتُ عرهْداً مع مُُتارىى ،\nحرلرفتُ لداود عبده ى ،\n5 إنِِّ أُهيِّئُ زرعركر إلى الأبده ،\nوأربْني كُرسهيىكر من جيلٍ إلى جيلٍ . سلام .\n6 تعتَفُ السماواتُ بهعجايبك ، يا ربُّ ،\nوبَهرقِّكر في كنيسةه القدِّيسه ينر .\n7 لأنه من في السحابه يساوى الربّ ؟\nومن يُشْبهُ الربّ في أبناءه الله ؟\n8 اللهُ المُمجىدُ في مشورة القدِّيسهينر ،\nعظيمٌ هو ومرهوبٌ على جميع الذين حروْلرهُ .\n9 أيُها الربُّ إلهر القوىاته ، من يُشْبهُكر ؟\nقوىٌّ أنت ، يا ربُّ ، وحرقُّكر مُُهيطٌ بك .\n11 أنت تسودُ على عهزىةه البحره ،\nوحركةُ أمواجه أنت تـُهْدِّئُ .\n11 أنت أذلرلْتر المُتكبـِّر مثلر القتيله ،\nوبهذراعه قوىتهكر بدىدتر أعداءركر .\n\n12 لكر هى السماواتُ ، ولكر هى الأرضُ أيضاً\nأنت أسىستر المسكونةر وكرمالهرا .\n13 الشرمالر والبحر أنت خلقتـرهُما ،\nثابورُ وحرمونُ يبتهجانه باسْْهكر .\n14 لكر الساعدُ والقدرةُ\nفـرلْترعتـرزّ يردُكر ، ورلْتَرتفعْ يَرينُكر .\n15 العدلُ والحُكْمُ هُُا استعدادُ كُرسهيِّكر\nالرحْْةُ والحقُّ يتقدىمانه فيسلكانه أمامر ورجْهكر .\n16 طوبى للشعبه الذي يعرفُ التهليلر\nيا ربُّ ، بنوره ورجْهكر يسلكونر ،\n17 وباسْْهكر طولر النهاره يبتهجونر ،\nوبهبِهِّكر يرتفعونر .\n18 لأنك أنت فخرُ قوىتُهم ،\nوبَهقِّكر يعلو قـرْنُنا .\n19 لأنى النُصْرةر هى للربِّ ،\nوقُدُّوسُ إسراييلر هو مرلهكُنا .\n21 حينئذٍ بالرؤيا تكلىمتر مع بنه يكر ،\nوقـُلْتر إنِِّ وضعتُ عروْناً على القوىِّ ،\nرفعتُ مُُتاراً من شعبِه\n\n21 وجدتُ داود عبده ى ،\nمرسرحتُهُ بهدُهْنٍ مُقدىسٍ .\n22 لأنى يردهى تُعضِّدُهُ ،\nوذراعى يُقوِّيه\n23 العدُوُّ لا ينتفعُ به ،\nوابنُ الإثُْه لا يعودُ يفعلُ به شرّاً\n24 أرقطعُ أعداءرهُ من أمامه ورجْه ،\nومُبغضوهُ أرجعلُهُم مرثرلاً .\n25 حرقِّى ورحْْتَّه معه ،\nوباسْْهى يرتفعُ قـرْنُهُ\n26 وأرجعلُ في البحره يردرهُ ،\nوفي الأنهار يَرينرهُ .\n27 هو يدعوني أنت هو أبي ،\nإلهي وناصرُ خلاصى\n28 أنا أيضاً أجعلُهُ بهكْراً ،\nأرعْلرى من كُلِّ ملوكه الأرض .\n29 أرحْفظُ له رحْْتَّه إلى الأبده ،\nوعهده ى صادقٌ له\n31 وأرجعلُ ذُرِّيترهُ إلى دهره الدهوره ،\n\nوكُرْسهيىهُ مثلر أيامه السماء .\n31 فإنْ تـركر بنوهُ نا موسى ،\nولم يسلكوا بأحْكامى\n32 وإنْ هُمْ نجرىسوا حُقوقى ،\nولم يُرفظوا وصاياىر\n33 أرفتقدُ بالعصا آثامرهُم ،\nوبالسوطه خطاياهُم .\n34 أما رحْْتَّه فلا أنْزعُها عرنهُ ،\nولا أظلهمُ بَهقِّى ،\n35 ولا أُدرنِّسُ عرهْده ى ،\nولا أُبْطهلُ ما خرجر من شر فتَّرى ،\n36 مرىةً حرلرفْتُ بهقُدْسى ، أرنىني لا أكذبُ لداود\n37 أنى نسلرهُ إلى الدهره يدومُ ،\nوكُرسهيىهُ مثلر الشمسه أمامي ،\n38 ومثلر القمره المستعده إلى الأبده\nوالشاهدُ في السماوات صادقٌ . سلام .\n39 وأنت أقصيترنا ورذلتر ،\nوطرحتر مسيحر كر إلى خلفٍ\n41 نقضتر عهدر عبدهكر ،\n\nونجرىستر موضعرهُ المقدىسر على الأرض .\n41 هدمتر كُلى سياجاته ،\nوجرعلتر مواضعرهُ الحصينةر فرزهعرةً\n42 اهخْترطرفرهُ كُلُّ عابهرهى الطريقه ،\nصار عاراً لِهيرانه .\n43 رفـرعْتر يَرينر أعدايه ،\nوجرعرلتر جميع أعدايه يفرحونر\n44 ردردْتر مرعونةر سيفه ،\nولم تنصُرْهُ في الحربه .\n45 حرلرلْترهُ من الطهارةه ،\nوقـر لربْ تر كُرْسهيىهُ على الأرض\n46 قـرلىلْتر أيامر زمانه ،\nوأفضتر عليه الخهزْىر . سلام .\n47 حتَّى متى ، يا ربُّ ، تـُعْرهضُ عرنىا إلى الانقضاءه ؟\nويتىقهدُ كالناره غرضربُكر ؟\n48 اُذْكُرْ ، يا ربُّ ، أىى شئٍ هو قـرور امى\nهل باطلًا خرلرقتر برني البشر ؟\n49 من هو الإنسانُ الذي يُر يا ولا يُعايهنُ الموتر ؟\nأو يُنجِّى نفسه من يده الِحيمه ؟ سلام .\n\n51 أينر ه ى مراحُْْكر الأولِر ، يا ربُّ ،\nالتي حرلرفتر بِها لداوده بالحقِّ ؟\n51 اُذْكُرْ ، يا ربُّ ، عار عبيدهكر ،\nالذي ورعردْتر به في حضنه أُمرمٍ كثيرةٍ\n52 الذي عيـىرهُ به أعداؤُكر ، يا ربُّ ،\nالذي عريـىرهُ به عهورضر مسيحهكر .\n53 مُباركٌ الربُّ إ لِ الدهره . يكونُ ، يكونُ .", "89": "المزمورُ التاسعُ والثمانونَ\nصلاةٌ لهموسرى رجله الله\n1 يا ربُّ ، مرلْجأً كُنْتر لرنا\nمن جيلٍ إلى جيلٍ ،\n2 من قـربْله أنْ تكونر الِبالُ ،\nمن قـربْله أنْ تُُلرقر الأرضُ والمسكونةُ ،\nمنذُ الدهره وإلى الأبده أنت هو .\n3 فلا تـرُدى الإنسانر إلى المرذلىةه ،\nفقد قـُلْتر اهرجرعوا يا برني البشر .\n4 لأنى ألفر سنةٍ أمامر عينـريْكر\nمثلُ يومه أمسٍ الذي عربـر ،\nووقتر مُرْرسٍ في الليل .\n5 سهنوهُم تكونُ مرذولةً ،\nباكراً مثلر العُ شْ به تزولُ\n6 باكراً يُزهرُ ويرعبـُرُ ،\nعندر المساءه يسقطُ ، يذبلُ وَرفُّ .\n7 لأننا قد فنينا بهرجْزهكر ،\nوبهسُخْطهكر اضطربرنا\n8 جرعرلْتر آثامرنا أمامركر ،\n\nودهرنا في ضوءه وجهكر .\n9 لأنى كُلى أيامهنا قد فنيتْ ،\nوبهرهجْزهكر فرنهينا\nوسنونا مثلر العنكبوته تُلهير تْ .\n11 أيامُ سنهينا فيها هى سبعونر سنةً ،\nوإنْ كانت بقوىةٍ فهى ثَرانونر ،\nوأكثـرُها تعبٌ هو ووجعٌ\nلأنى دهعرةً أتتْ علينا فتأدىبْنا .\n11 من يرعرفُ قوىةر غضبك ،\nومهن خروفه سُخْطهكر لهيُحصى يَرينركر ؟\n12 هكذا عرِّفْنا ،\nمع الذين تأدىبوا في قلوبِهم بالحكمةه .\n13 اهرْجهعْ ، يا ربُّ ، فإلى متى ؟\nواقبله السؤالر عن عبيدهكر .\n14 قد امتلأنا في الصباحه من رحْْتهكر ،\nابتهجْنا وفرهحْنا جميع أيامهنا ،\n15 عهورضر الأيامه التي أذلرلترنا فيها ،\nوالسنينر التي رأينا فيها الشرور .\n16 اُنْظُرْ إلى عبيدهكر وأعمالهكر ،\n\nواهْده برنهيهم.\n17 وليكُنْ نورُ الربّ إلهرهنا علينا ،\nوأعمالُ أيدينا فسهِّل علينا ،\nوأعمالُ أيدينا تُقوِّمُها .", "90": "المزمورُ التسعونَ\nبركةُ التسبيح ، لداود\n1 الساكنُ في معونة العلي .\nيستريح في ظلّ إله السماء .\n2 يقولُ للربِّ أنت هو ناصري\nإلهي ملجأي ، فأتّكل عليه .\n3 لأنه يُنجِّيني من فخِّ الصياد ،\nومن كلمةٍ مقلقة\n4 في وسطه منكبيه يظللك ،\nوتحت جناحيه تتّكل\nوعدله يحيط بك كالسلاح .\n5 فلا تخشى من خوفه الليل ،\nولا من سهم يطيرُ بالنهار ،\n6 ولا من أمرٍ يسلُكُ في الظلمة ،\n\nولا من وقعة وشيطان الظهيرة .\n7 يسقُطُ عن يسارك أُلوفٌ ،\nوربوات عن يمينك ،\nأما أنت فلا يقتربون إليك\n8 بل بعينيْك تتأملُ ،\nومَُازاةر الخُطاةه تـُبْصهرُ .\n9 لأنك أنت ، يا ربُّ ، مرلْجرأى\nجرعرلْتر العليى مرلْجرأركر .\n11 لا تأتهى عليكر الشرورُ ،\nولا تدنو ضربةٌ من مسكنهكر\n11 لأنه يُوصى ملايكترهُ من أجلهكر\nأنْ يُرفظوكر في سايره طُرُقهكر\n12 وعلى أيدهيهم يُرْملونركر ،\nلئلاى تعثـُر بَهجرٍ رهجْلُكر .\n13 تطأُ الأفعرى ومرلهكر الحيىاته ،\nوترسحقُ الأسدر والتنِّينر .\n14 لأنه عليّ اتىكرلر فأُنجرِّيه\nأستـُرُهُ لأنه عرفر اهسْْى .\n15 يدعوني ، فأستجيبُ له ،\n\nمرعهُ أنا في الشهدىةه ،\nأُنْقهذُهُ وأُمَرِّدُهُ .\n16 مهنْ طوله الأيامه أُشْبهعُهُ\nوأُريهُ خلاصى .", "91": "المزمورُ الحادى والتسعونَ\nمزمورُ تسبحةٍ ليومه السبته\n2 صالهحٌ هو الاعتَهافُ للربِّ ،\nوالتَرتيلُ لاسْْهكر ، أيُها العلهىُّ\n3 أنْ يَُْبـر بهرحْْتهكر بالصباحه ،\nوبَهقِّكر في كُلِّ ليل ةٍ ،\n4 بِهزمارٍ ذى عرشرةه أوتارٍ ،\nمع تسبيحٍ بقيثارٍ\n5 لأنك أرفـْرحْترني ، يا ربُّ ، بصنيعهكر ،\nوبأعماله يردريْكر أبتهجُ .\n6 كما عرظُمرتْ أعمالُكر ، يا ربُّ ،\nعرمُقرتْ أفكارُكر جداً .\n7 الرجلُ الِاهلُ لا يعرفُ ،\nوعديمُ الفهمه لا يفهمُ هذه .\n\n8 عندما يزهو الخُطاةُ مثلر العُشبه ،\nويطلعُ جميع فاعلهى الإثُْه ،\nفلكى يُبادوا إلى أبده الأبده .\n9 أما أنت ، يا ربُّ ،\nفمُتعالٍ إلى الأبده .\n11 لأنه هوذا أعداؤُكر ، يا ربُّ ،\nهوذا أعداؤُكر يرهلكونر ،\nوجميع فاعلهى الإثُْه يتبدى دونر .\n11 ويرتفعُ مثلر وحيده القرنه قرني ،\nوشيخوخرتَّه بهدُهْنٍ درسهمٍ .\n12 أربْصرتْ عريـْنِرى بأعدايى ،\nوبالقايمينر عليّ وبهصانعهى الشرِّ\nتسمعُ أُذُناىر .\n13 الصهدِّيقُ كالنخلةه يـُزْهرُ ،\nوكرمهثله أرزه لبنانر ينمو .\n14 المغروسونر في بيته الر بِّ ،\nوفي دياره بيته إلهرهنا زاهرونر\n15 حينئذٍ يكثُرونر في شيخوخةٍ درسْهةٍ ،\nويكونونر مستَريُينر\n\n16 لهيُخْبِهوا بأنْ الربّ إلهرنا مستقيمٌ ،\nوليس فيه ظُلْمٌ .", "92": "المزمورُ الثانِى والتسعونَ\nلليومه الذي قبلر السبته ، لرمىا عُمِّ رت الأرضُ\nبركةُ تسبحةٍ لداود\n1 الربُّ قد مرلركر ، ولربهسر الِلالر\nلربهسر الربُّ القوىةر وترنطىقر بِها ،\nلأنه ثـربىتر المسكونةر ، فلن تـرترزعزعر .\n2 كُرسهيُّكر ثابتٌ منذُ البدءه\nوأنت هو منذُ الأزله .\n3 رفـرعرته الأنْْارُ ، يا ربُّ ،\nرفـر عرته الأنْْارُ صوتُرا .\n4 ترفعُ الأنْْارُ صوتُرا\nمن صوته مياهٍ كثيرةٍ\nعجيبةٌ هى أهوالُ البحره ،\nوعجيبٌ هو الربُّ في الأعالي .\n5 شهاداتُهُ صارتْ صادقةً جداً ،\nلهبيتهكر ينبغى التقديسُ ، يا ربُّ ،\n\nإلى طوله الأيامه .", "93": "المزمورُ الثالثُ والتسعونَ\nمزمورٌ لداود ، في رابعه السبوت .\n1 إلهُ الانتقامه الربُّ ،\nإلهُ الانتقامه ظرهر .\n2 اهرْترفهعْ يا ديىانر الأرض ،\nأرعْطه مَُازاةً للمستكبِهينر .\n3 إلى متى الخطاة ، يا ربُّ ،\nإلى متى الخطاة يفتخرونر ؟\n4 يتنعىمونر ويتكلىمو نر بالظُلْمه ،\nيتكلىمُ جميع فاعلى الإثُْه\n5 لهشعبك ، يا ربُّ ، أرذّلُّوا ،\nولهميراثهكر أحزنوا\n6 قتلوا الأرملةر واليتيمر ،\nوأماتوا الغريبر\n7 وقالوا إنى الربّ لا يُبصهرُ ،\nولا يفهمُ إلهُ يعقوب .\n8 اهفهموا أيُها الِهلاءُ في الشعبه\n\nويا حْرْقرى متى تعقلونر ؟\n9 هل الذي غرسر الأُذُنر لا يسمعُ ؟\nأو الذي جربرلر العينْر ألا يُبصهرُ ؟\n11 الذي يُؤدِّبُ الأُمرمر ألا يُبكِّتُ ،\nالذي يُعلِّمُ الإنسانر العهلْمر ؟\n11 الربُّ يعرفُ أفكار الإنسانه ،\nأنْىا باطلةٌ .\n12 طوبى ل نسانه الذي أنت تُؤدِّبُهُ ، يا ربُّ ،\nومن ناموسهكر تُعلِّمُهُ ،\n13 لهيـُعْطرى دهعرةً من أيامٍ شرِّيرةٍ ،\nحتَّى تُُفر للخاطئه حُفرةٌ .\n14 لأنى الربّ لا يُقصى شعبرهُ ،\nولا يتَْكر ميراثرهُ ،\n15 حتَّى يعودر العدلُ إلى الحُكْمه ،\nمع جميع القريبينر مهنْهُ المستقيمينر بقلبهم . سلام .\n16 من يـرنـْهرضُ معى على الأشراره ،\nأو من يقومُ معى على فاعلى الإثُْه ؟\n17 لولا أنى الربّ أعانرني ،\nلكانتْ نفسي عرمىا قليلٍ حلىتْ في الِحيمه .\n\n18 كنتُ أقولُ قد زرلىتْ قردرمهى ،\nرحْْتُكر ، يا ربُّ ، أعانـرتْني .\n19 وحسبر كثرة الأحزانه التي في قلبِه ،\nتعزياتُكر ، يا ربُّ ، أبـْهرجرتْ نفسي .\n21 هل يكونُ معكر كُرْسهىُ الإثُْه ،\nالذي يَرلقُ تعباً على الوصيةه ؟\n21 يتصيىدون نفسر الصدِّيقه ،\nويُلقونر إلى الحُكْمه درماً زكيّاً .\n22 والربُّ صار لي مرلْجأً ،\nوإلهي مرعونةر رجايى\n23 وسيـرُدُّ عليهم إثَْرهُم وشرىهُم\nويبيدُهُم الربُّ إلهي .", "94": "المزمورُ الرابعُ والتسعونَ\nبـركةُ تسبحةٍ لداود\n1 تعالوا ، فلنبتهجْ بالربّ ،\nولنُهلِّلْ لله مخلّصهنا\n2 ولنسبهقْ فنبلغْ إلى وجهبالاعتَهافه ،\nلهنُهلِّلْ له بالمزاميره .\n\n3 لأنك أنت يا ربُّ إلهٌ عظيمٌ ،\nومرلهكٌ كبيرٌ على جميع الآلهةه .\n4 لأنى الربّ لا يُقصى شعبرهُ ،\nلأنى بيدريْه أقطار الأرض جميعها\nوأعالي الِباله له هى\n5 لأنى البحر هو له وهو الذ ى صرنـرعرهُ ،\nويداهُ جربـرلرتا اليابسةر .\n6 تعالوا فلنسجُدْ ونَرُرى أمامرهُ ،\nونبكى قُدىامر الربّ الذي خرلرقرنا\n7 لأنه هو إلهرُنا ،\nونُرنُ شعبُ رعيته\nوأغنامُ يدريْه .\n8 اليوم إنْ سْرعتُم صوترهُ ،\nفلا تُقسُّوا قلوبركُم ،\nمثلما كانر في ال غضبه ،\nكيومه التجربةه في البـرِّيةه\n9 حيثُ جرىبرني آباؤُكُم ،\nاهمتحنوا ورأوا أعمالي أربعينر سنةً .\n11 لأجله هذا كرهْتُ ذلكر الِيلر ،\n\nوقـُلْتُ إنـىهُم يرضهلُّونر بقلبهم ،\nوهُم لم يعرفوا سُبُلهى .\n11 كما أقسمتُ في غضبِه\nأنـىهُم لا يدخلونر إلى موضعه راحتَّه .", "95": "المزمورُ الخامسُ والتسعونَ\nحينرما كان البيتُ يـُبـْنِر بعدر السبِْ تسبحةٌ لداود\n1 سبّحوا الربّ تسبيحاً جديداً ،\nسربِّحوا الربّ يا كُلى الأرض\n2 سبّحوا الربّ ، وباركوا اسْْرهُ ،\nبرشِّروا من يومٍ إلى يومٍ بِهلاصه .\n3 حردِّثوا في الأُمرمه بِهرجْده ،\nوبـرينْر جميع الشعوبه بعجايبه .\n4 لأنى الربّ عظيمٌ هو ومُسربىحٌ جداً ،\nمرهوبٌ على كُلِّ الآلهةه .\n5 لأنى كُلى آلهةه الأُمرمه شياطين ،\nأما الربُّ فرصرنرعر السماوات .\n6 الاعتَهافُ والبهاءُ قُدىامرهُ ،\nالطُهْرُ والِلالُ العظيمُ في قدسه .\n\n7 قدِّموا للربِّ ، يا جميع أُبـُوىاته الأُمرمه ،\nقدِّموا للربِّ مَرداً وكرامةً\n8 قدِّموا للربِّ مَرداً لاسْْه ،\nاهحْْلوا الذبايحر وادخلوا ديارهُ .\n9 اُسْجُدوا للربِّ في دياره المقدىسةه\nفلترزلزله الأرضُ كُلُّها من أمامه وجه .\n11 قولوا في الأُمرمه إنى الربّ قد مرلركر على خشبةٍ ،\nوأيضاً ثـربىتر المسكونةر ، فلنْ تتزعزعر\nيردينُ الشعوبر بالاستقامةه .\n11 فلتفرحه السماواتُ وتبتهجه الأرضُ ،\nوليرعجى البحرُ وجميع مهل ئه .\n12 تفرحُ البقاعُ وكُلُّ ما فيها ،\nحينئذٍ يبتهجُ كُلُّ شرجره الغابه\n13 أمامر وجه الربّ ، لأنه يأتهى ،\nإنه يأتهى ليردينر الأرضر\nيردينُ المسكونةر بالعدله ،\nوالشعوبر بَهقِّه .", "96": "المزمورُ السادسُ والتسعونَ\nلداود ، لرمىا ثبُتر تْ أرضُهُ\n1 الربُّ قد مرلركر ، فلتتهلىله الأرضُ ،\nولتفرحه الِزايرُ الكثيرةُ .\n2 سرحابٌ وضبابٌ حروْلرهُ ،\nالعدلُ والقضاءُ قهوامر كُرسهيِّه .\n3 النارُ تسبقُ فتسلكُ أمامرهُ ،\nوبلهيبٍ تُُْرهقُ أعداءرهُ الذين حروْلرهُ\n4 أضاءرتْ بـُرُوقُهُ المسكونةر ،\nنرظرته الأرضُ فترزلزلرتْ .\n5 ذابرته الِبالُ مثلر الشمعه من قُدىامه وجه الربّ ،\nمن قُدىامه وجه ربِّ الأرض كُلِّها .\n6 أرخْبـرته السماواتُ بعدله ،\nوعاينرتْ جميع الشعوبه مَردرهُ .\n7 يَرْزرى جميع الساجدينر لهصنعةه الأيدى ،\nالمُفتخرينر بأ صنامهم\nاُسْجُدوا له يا جميع ملايكته .\n8 سْرهعرتْ صهيونُ ففرحرتْ ،\nوتُرلىلرتْ بناتُ اليهوديةه ،\n\nمن أجله أحكامهكر ، يا رب\n9 لأنك أنت هو الربُّ العلهىُّ على كُلِّ الأرض ،\nاهرتـرفرعْتر جداً فوقر جميع الآلهةه .\n11 يا مُُبِِّ الربّ ، أربْغهضوا الشر\nالربُّ يُرفظُ أنفسر قديسيه ،\nويُنجِّيهم من أيدهى الخُطاةه .\n11 نورٌ أشرقر للصدِّيقهينر ،\nوفرحٌ للمستقيمهى القلوبه .\n12 اهفرحوا ، أيُها الصدِّيقونر ، بالربّ ،\nواعتَرفوا لهذهكْره قدسه .", "97": "المزمورُ السابعُ والتسعونَ\nمزمورٌ لداود\n1 سربِّحوا الربّ تسبيحاً جديداً ،\nلأنى الربّ قد صرنرعر أعمالاً عجيبةً\nأرحْيرتْ له يَرينُهُ وذراعُهُ القدُّوسُ .\n2 أعلرنر الربُّ خلاصرهُ قُدىامر الأُمرمه\nوكرشرفر لهرُم بهرىهُ .\n3 ذركر رحْْترهُ ليعقوب ،\n\nوحقىهُ لبيته إسراييلر\nنرظرتْ أقاصى الأرض جميعها خلاصر إلهرهنا .\n4 هرلِّلوا للربِّ يا كُلى الأرض ،\nسربِّحوا وهرلِّلوا ورتِّلوا .\n5 رتِّلوا للربِّ بالقيثاره ،\nبالقيثاره وصوته المزموره .\n6 بأبواقٍ خافقةٍ وصوته بوقه القرنه\nهرلِّ لوا قُدىامر الملهكه الربّ .\n7 فليعجى البحرُ وكُلُّ ملئه ،\nالمسكونةُ وكُلُّ الساكنين فيها\n8 الأنْْارُ تُصفِّقُ بأيدهيها معاً ،\nوالِبالُ تبتهجُ ، أمامر وجه الربّ ،\n9 لأنه أترى لهيردينر الأرضر\nيردينُ المسكونةر بالعدله ،\nوالشعوبر بالاستقا مةه .", "98": "المزمورُ الثامنُ والتسعونَ\nمزمورٌ لداود\n1 الربُّ قد مرلركر ، فلْتغضبه الشعوبُ\n\nالِالسُ على الشاروبيمر ، فلْترتزلزله الأرضُ .\n2 عظيمٌ هو الربُّ في صهيون ،\nومُتعالٍ على كُلِّ الشعوبه .\n3 فلْيعتَرفوا لاسْْه العظيمه ،\nلأنه مره وبٌ وقدُّوسٌ .\n4 وكرامةُ المرلهكه أن يُُهبى الحُكْمر\nأنت هيىأْتر الاستقامةر ،\nأنت أرجْريْتر القضاءر والعدلر في يعقوب .\n5 ارفعوا الربّ إلهرنا ،\nواسْجُدوا لهموطئه قدرمريْه ،\nلأنه قُدُّوسٌ .\n6 موسى وهرون بـرينْر كرهنته ،\nوصموييلُ بـرينْر الذين يردْعونر باسْْه\nكانوا يردْعونر الربّ ،\nوهو كانر يستجيبُ لهرُم .\n7 بعموده الغمامه كان يُكلِّمُهُم\nلأنـىهُم حفظوا شهاداته ،\nوالأوامر التي أعطاهُم .\n8 أيُها الربُّ إلهرُنا ، أنت استجبتر لهرُم\n\nصهرْتر لهرُم ، يا اللهُ ، غفوراً ،\nومَُازهياً على جميع أعمالهم .\n9 اهرْفرعوا الربّ إلهرنا ،\nواسْجُدوا في جبله المُقدىسه ،\nفإنى الربّ إلهرنا قدُّوسٌ .", "99": "المزمورُ التاسعُ والتسعونَ\nمزمورٌ للاعتَهافه\n1 هلِّلوا للربِّ ، يا كُلى الأرض ،\n2 تعبىدوا للربِّ بالف رحه ،\nأُدخُلوا أمامرهُ بالتهليل .\n3 اهعْلرموا أنى الربّ هو إلهرُنا\nهوصرنـرعرنا وليس نُرنُ ،\nونُرنُ شعبُهُ وغنمُ رعيته .\n4 اُدخُلوا أبوابره بالاعتَهافه ،\nوديارهُ بالتسابيح\nاهعتَرفوا له ،\nوباركوا اسْْرهُ ،\n5 فإنى الربّ صالهحٌ هو ،\n\nوأنى إلى الأبده رحْْترهُ ،\nوإلى جيلٍ فجيلٍ حرقُهُ .", "100": "المزمورُ المائةُ\nمزمورٌ لداود\n1 رحْْةً وحُكْماً أُسربِّحُكر ، يا رب\n2 أترنَّىُ وأترفهىمُ في طريقٍ بلا عريْبٍ\nمرتَّر تأتهى إلِرى ؟\nلقد كُنْتُ أسلُكُ بهدهعرةه قلبِه ، في وسطه بيتَّه .\n3 لم أضعْ أمامر عينِرى أمراً يَُالهفُ الناموسر ،\nصانعهى المعصيةه أبغضتُ\n4 لم يلصقْ بي قلبٌ مُعْورجٌّ ،\nوعند ميلانه الشرِّيره عنِِّ لم أكُنْ أعلرمُ .\n5 الذي يغتابُ قريبرهُ سهرّاً ، كُنْتُ أُطارهدُهُ\nالمُستكبِهُ بعينـريْه والمنتفخُ القلب لم آكُ لْ معه .\n6 عيناىر على جميع أُمرناءه الأرض ، لكى أُجْلهسرهُم معى\nالسالكُ بلا عريْبٍ ، هذا كان يَردُمُني .\n7 المتكبِِّ لم يسكُنْ في وسطه بيتَّه\nالمتكلِّمُ بالظُلْمه لم يستقمْ أمامر عينِرى .\n\n8 في أوقاته الغد واته كُنْتُ أقتلُ جميع خُطاةه الأرض ،\nلأُبيدر من مدينةه الربّ جميع صانعهى الإثُْه .", "101": "المزمور المئةُ والواحدُ\nصلاةٌ لهمسكينٍ إذا أعيا وسكبر توسُّلره أمام الربّ\n2 يا ربُّ ، اهسْتمعْ صلاتي ،\nولْيصعردْ أمامركر صُراخى ،\n3 لا تصرفْ وجهكر ع\nفي اليومه الذي أرحْزرنُ فيه ، أرمهلْ إلِرى سْرْعركر\nفي اليومه الذي أدعوكر فيه ، اهستجبْ لي سريعاً .\n4 لأنى أيامى قد اضمحلىتْ كالدُخىانه ،\nوعظامى فىهى مثلُ وقيدٍ قد اهلْترهبرتْ .\n5 قد ضُرهبْتُ كالعُشْبه ، ويربهسر قلبِه ،\nلأني سرهوتُ عن أكله خُبْزهى .\n6 من صوته تنهُّدهى لرصهقر عظمى بلرحْمهى .\n7 أرشْبهتُ قُوقر البـرِّيةه ،\nوصهرْتُ مثلر بومةٍ في منْزلٍ خرهبٍ .\n8 سرهرْتُ ، وصهرْتُ كعصفورٍ وحيدٍ على سرطْحٍ .\n9 النهار كُلىهُ كان أعدايى يُعيرِّونرني ،\n\nوالذين يَردحونرني كان وا يتحالفونر عليّ .\n11 أكلتُ الرمادر مثلر الخُبْزه ،\nوشرابي مُزهجر لي بالبُكاءه ،\n11 مهنْ وجه رهجْزهكر وغضبك ،\nلأنك رفـرعْترني ثم طرحترني .\n12 مالرتْ أيامهى كالظهلِّ ،\nوأنا مثلُ العُشبه يبستُ .\n13 أما أنت ، يا ربُّ ، دايمٌ إلى الأبده ،\nوذهكْرُكر إلى أجياله الأجياله .\n14 أنت ترجهعُ وتتَأى فُ على صهيون ،\nلأنه وقتُ التَاؤفه عليها ، لأنى الزمانر قد حرضر .\n15 لأنى عبيدركر قد سُرُّوا بَهجارتُها ،\nوعلى تُرابِها يتحنىنونر\n16 وتخشى الأُمرمُ اسْْركر ، يا ربُّ ،\nوكُلُّ المرماله كه من مَردهكر .\n17 لأنى الربّ يبني صهيون ،\nويرظْهرُ بِهرجده .\n18 لأنه نرظر إلى صلاةه المساكينه ،\nولم يُرذهلْ طهلبتـرهُم .\n\n19 فلْتُكتربْ هذه إلى جيلٍ آخر ،\nوالشعبُ الذي يَُلرقُ يُسبِّحُ الربّ\n21 لأنه اهطىلرعر من عُلُوِّ قُ دْسه ،\nالربُّ نرظر من السماء إلى الأرض\n21 لهيسمعر تنهُّدر المُقيىدينر ،\nلهيرحلى برني المقتولينر ،\n22 لكى يَُْبِهوا في صهيون باسْمه الربّ ،\nوبتسبهيحه في أورشليمر .\n23 عندر اهجتهماعه الشعوبه جَريعاً\nوالمرمالهكه ليتعبىدوا للربِّ .\n24 أجابرهُ في طريقه قـُوىته ،\nأرخْبِهْني بهقهلىةه أيامى ،\n25 ولا تأخُذْني في نهصفه أيامى\nمن جيلٍ إلى جيلٍ هى سهنوكر .\n26 أنت ، يا ربُّ ، منذ البدءه أسىستر الأرضر ،\nوالسماواتُ أعمالُ يدريْكر هى\n27 هى تربيدُ وأنت تدومُ\nوكُلُّها كثوبٍ تـربـْلر ى ،\nكرهداءٍ تطويها فتتغيـىرُ\n\n28 أما أنت ، فأنت هو ، وسهنوكر لا تنتهى .\n29 أبناءُ عبيدهكر يسكنونر بِهدوءٍ ،\nوزرعُهُم إلى الأبده يستقيمُ .", "102": "المزمورُ المئةُ والثانِى\nلداود\n1 باركى يا نفسي الربّ ،\nوكُلُّ ما في باطهني لهيُ بارهكْ اسْْرهُ القُدُّوسر .\n2 باركى يا نفسي الربّ ،\nولا تنسى جميع تسابيحه\n3 الذي يغفرُ جميع آثامهكه ،\nالذي يشفي كُلى أمراضهكه\n4 المُنْقهذُ من الفساده حياتركه ،\nالذي يُكلِّلُكه بالمراحهمه والرأفاته ،\n5 المُشبهعُ بالخيرْاته شرهواتهكه ،\nفيتجدىدُ مثلر النسره شبابُكه .\n6 صانعُ الرحْْاته هو الربُّ ،\nوالقضاءر لسايره المظلومينر .\n7 أظهر لهموسى طُرُقرهُ ،\n\nولهبرني إسراييلر مشيئاته .\n8 رحومٌ ورؤوفٌ هو الربُّ ،\nطويلُ الروحه وكثيرُ الرحْْةه .\n9 لا يغضبُ إلى الانقضاءه ،\nو لا يُرقدُ إلى الدهره\n11 لم يصنعْ مرعرنا حسب خطايانا ،\nولا بَهرسربه آثامهنا جازانا .\n11 بل مثلُ اهرتفاعه السماء عن الأرض ،\nقـّوىى الربُّ رحْْترهُ على خايفهيه\n12 وكربـُعْده المشارقه من المغاربه ،\nأربـْعردر عرنىا آثامرنا .\n13 وكما يتَراءفُ ا بُّ على بنيه ،\nكذلك تراءفر الربُّ على خايفهيه ،\n14 لأنه عرفر جُبـْلرترنا\nاُذْكُرْ ، يا ربُّ ، أننا تُرابٌ نُن .\n15 الإنسانُ مثلُ العُشبه أيامُهُ\nوكرزرهْره الحقله هكذا َرفُّ .\n16 لأنى ريُاً إذا عربـرتْ عليه فلا يُوجردُ ،\nولا يعرفُ أيضاً موضعرهُ بعدُ .\n\n17 أما رحْْةُ الربّ فهى من الدهره وإلى الأبده على خايفهيه\nوبهرُّهُ على برني البنينر\n18 الحافظينر عرهْدرهُ ،\nوالذاكرينر وصاياهُ ليعملوا بِها .\n19 الربُّ في السماء ثبىتر كُرْسهيىهُ ،\nومَرلكتُهُ على الكلِّ تسودُ .\n21 باركوا الربّ ، يا جميع ملايكته ،\nالمُقتدرينر بقوىتُهم ، الصانعينر كلمترهُ ،\nعند سْراعه صوته كلامه .\n21 باركوا الربّ ، يا جميع قـُوىاته ،\nخُدىامه العاملينر إرادته .\n22 باركوا الربّ ، يا جميع أعماله\nفي كُلِّ مواضعه قوّته\nباركى يا نفسي الربّ .", "103": "المزمورُ المئةُ والثالثُ\nلداود\n1 باركى يا نفسي الربّ\nأيُها الربُّ الإلهُ ، لقد عرظُمْتر جداً ،\n\nالاعتَهافر وعهظرمر الِلاله تسربلتر ،\n2 اشتملتر بالنوره كالثوبه ،\nالباسطُ السماءر مثلر الخيمةه .\n3 المُسقِّفُ علاليرهُ بالمياه ،\nالِاعلُ مسالهكرهُ على السحابه ،\nالماشى على أجنحةه الرياحه\n4 الذي صرنرعر ملايكترهُ أرواحاً ،\nوخُدىامرهُ ناراً تلتهبُ .\n5 المؤسِّسُ الأرضر على أساسها القوهىِّ ،\nفلا تتزعزعُ إلى أبده الأبده .\n6 رداؤُ ها العُمقُ مثلُ الثوبه ،\nوعلى الِباله تقفُ المياهُ\n7 من انتهارهكر تُربُ ،\nومن صوته رعودهكر تفزعُ .\n8 ترصْعردُ الِبالر ، وتنْزلُ البقاعر ،\nإلى الموضعه الذي أسىسترهُ لهرا .\n9 وضعتر لهرا حردّاً لا تتعدىاهُ ،\nولا ترجهعُ لهتُغطِّىر الأرضر .\n11 الذي يُرسلُ العيونر في الأوديةه ،\n\nوفي وسطه الِباله تَّرى المياهُ\n11 تسقى كُلى وحوشه الحقله ،\nتُقبلُ حْهيرُ الوحشه عند عطشها .\n12 عليها طيورُ السماء تسكنُ ،\nومن وسطه الصخوره تُعطى صوتُرا .\n13 الذي سقى الِبالر من علالهيه ،\nمن ثَرةه أعمالهكر تشبعُ الأ رضُ .\n14 الذي يُنبهتُ عُشْباً للبهايمه ،\nوبقولر الخُضرةه لخهدمةه البشر ،\nلهيُخْرهجر خُبْزاً من الأرض\n15 وخَرْراً يُفرِّحُ قلبر الإنسانه ،\nولهيبتهجر وجهُهُ بالزيته ،\nوالخُبـْزُ يُشدِّدُ قلبر الإنسانه .\n16 ترشْبرعُ جميع أشجاره الحقله ،\nوأرْزُ لبنانر الذي غرسرهُ\n17 هناكر حيثُ تضعُ العصافيرُ فهراخرها ،\nبيتُ اللىقلرقه في رؤوسها .\n18 الِبالُ العاليةُ للأيايله ،\nالصخورُ ملجأٌ للأرانبه .\n\n19 صرنرعر القمر للمواقيته ،\nالشمسُ عرفرتْ مرغْرهبِرا .\n21 مجّد ظُلْمةً فكانر ليلٌ ،\nفيه تعبـُرُ سايرُ وحوشه الغياضه ،\n21 أشبالٌ تزأرُ لهترخْطرفر ،\nوتطلبر من الله طعامرها .\n22 أشرقته الشمسُ فاجتمعتْ ،\nفي مرابضها ترقُدُ\n23 ويَرجُ الإنسانُ إلى عمله ،\nوإلى صناعته حتَّى المساءه .\n24 كرمْ عرظُمرتْ أعمالُكر ، يا ربُّ ،\nكُلُّ شئٍ بَهكمةٍ صرنـرعْتر\nامتلأرته الأرضُ من خليقتهكر .\n25 هذا البحرُ الكبيرُ الواسعُ\nهناكر دبىاباتٌ ليس لهرا عددٌ ،\nحيواناتٌ صغارٌ مع كهبارٍ .\n26 هناكر تعبـُرُ السُفُنُ ،\nوهذا التنينُ الذي خرلقترهُ لهيُضْحركر به .\n27 كُلُّها إيىاكر تتَرجىى ،\n\nلهتُعطيرها طعامرها في حهينه\n28 فإذا أنت أعطيترها اجتمعتْ ،\nوإذا فتحتر يدركر يَرتلئُ الكُلُّ من صلاحهكر .\n29 وإذا صرفتر وجهكر ترتاعُ\nتـرنـْزرعُ أرواحرها فتـرفْنِر ،\nوإلى تُرابِها تعودُ .\n31 تُرسهلُ روحركر فتُخْلرقُ ،\nوتَُّدِّدُ و جهر الأرض دُفـْعرةً أُخرى .\n31 فـرلْيركُنْ مَردُ الربّ إلى الأبده ،\nيفرحُ الربُّ بِهميعه أعماله\n32 الذي ينظُرُ إلى الأرض فيجعلُها ترتعدُ ،\nالذي يَرسُّ الِبالر فتُدرخِّنُ .\n33 أُسبِّحُ الربّ في حياتهى ،\nوأُرتِّلُ لإلهي ما دُمتُ موجوداً\n34 فيلهذُّ له كلامى ،\nوأنا أفرحُ بإلهي .\n35 فلتـرفْنر الخُطاةُ من الأرض ،\nوالذين بلا ناموسٍ كأنـىهُم لم يكونوا بـرعْدُ\nباركى يا نفسي الربّ .", "104": "المزمورُ المئةُ والرابعُ\nهلّلويا\n1 اهعتَرفوا للربِّ وادعوا باسْْه ،\nبرشِّروا في الأُمرمه بأعماله .\n2 سبّحوه ورتِّلوا لرهُ ،\nحردِّثوا بِهميعه عجايبه .\n3 اهفتخهروا باسْْه القُدُّوسه\nوليفرحْ قلبُ الذين يلتمسونر الربّ .\n4 اُطلبوا الربّ واعتـرزُّوا ،\nالتمسوا وجههُ في كُلِّ حينٍ .\n5 اُذْكُروا عجايبرهُ التي صرنـرعرها ،\nآياته وأحكامر فهيه\n6 يا ذُرِّيةر إبراهيمر عبيدرهُ ،\nوبرني يعقوب مُُتارهيه .\n7 هو الربُّ إلهرُنا\nفي كُلِّ الأرض أحكامُهُ .\n8 ذركر إلى الدهره عهدرهُ ،\nالكلمةر التي أوصرى بِها إلى آلافه الأجياله .\n9 الذي قرىرهُ لإبراهيمر عبده ،\n\nوحرلرفر به لإسحقر\n11 وأقامرهُ ليعقوب أمراً ،\nولإسراييلر عهداً إلى الأبده .\n11 قايلاً ، لكر أُعطهى أرضر كنعانر ،\nحربْلر قياسه ميراثهكر\n12 إذ كانوا في عددهم قليلينر ،\nقليلينر وغُرباءر فيها .\n13 اهجتازوا من أُمىةٍ إلى أُمىةٍ ،\nومن مَرلكةٍ إلى شع بٍ آخر\n14 لم يردرعْ إنساناً يظلمُهُم ،\nوبركىتر ملوكاً من أجلهم ،\n15 قايلاً ، لا ترسُّوا مُسرحايى ،\nولا تفعلوا شرّاً بأنبيايى .\n16 ودعا بالِوعه على الأرض ،\nكرسر كُلى قوىةه الخُبْزه .\n17 أرسرلر أمامرهُم رجلاً ،\nبهيعر يوسفُ للعبوديةه .\n18 أرذرلُّوا بالقيوده رهجْلريْه ،\nوبالحديده عبـرتْ نفسُهُ\n\n19 حتَّى أترتْ كلمتُهُ ،\nوكلمةُ الربّ طرحرتْ فيه النار .\n21 أرسرلر الملكُ فرحرلىهُ ،\nومجّدهُ رييساً للشعبه\n21 أقامرهُ سيِّداً على بـريْته ،\nومُدبِّراً على كُلِّ ما لرهُ ،\n22 لهيـُعرلِّمر رؤساءرهُ كنفسه ،\nويُُركِّمر شيوخرهُ .\n23 فجاء إسراييلُ إلى مصر ،\nوتغرىبر يعقوبُ في أرضه حامٍ\n24 مجّد شعبرهُ يكثـُرُ جداً ،\nوشدىدرهُ أكثـر من أعدايه .\n25 حروىلر قلبـرهُم ليُبغضوا شعبرهُ ،\nولْيرمْكروا بعبيده .\n26 أرسرلر موسرى عبدرهُ ،\nوهرونر الذي اهختارهُ\n27 مجّد فيهما أقوالر آياته ،\nوعجايبرهُ في أرضه حامٍ .\n28 أرسرلر ظُلْمةً فأرظلمتْ ،\n\nومرمروا كلامرهُ.\n29 حروىلر مياهرهُم إلى دمٍ ،\nوقـرترلر أسْْاكرهُم\n31 أفاضرتْ أرضُهُم ضفادعر ،\nفي مُرادهعه ملوكهم .\n31 قالر ، فجاء ذُبابُ الكلبه\nوالبعوضُ في جميع تُُومهم .\n32 مجّد أمطارهُم بـرداً ،\nواشتعلتْ نارٌ في أرضهم\n33 ضربر كُرومرهُم وتينـرهُم ،\nوكرسىر كُلى شجرةٍ في تُُومهم .\n34 قالر ، فجاء جرادٌ وجندبٌ بلا عددٍ .\n35 فأركرلر كُلى عُشبٍ في أرضهم ،\nوأركرلر ثَرةر أرضهم .\n36 ضربر كُلى بهكْرٍ في أرضهم ،\nأوايلر كُلِّ تعبهم .\n37 فأخرجرهُم بَهُلهىِّ الفضةه وحُلهىِّ الذهبه ،\nولم يكُنْ في أسباطهم مريضٌ\n38 فرحرتْ مهصرُ بِهروجهم ،\n\nلأنى خروْفـرهُم أترى عليهم .\n39 برسرطر سرحابةً لهتُظرلِّلرهُم ،\nوناراً لهتُضئر لهرُم بالليل .\n41 سألوا ، فأتتـْهُم السلورى ،\nوخُبـْزُ السماء أشبعرهُم به .\n41 شرقى الصخرةر ففاضرته المياهُ ،\nجرتْ في أمكنةٍ عديَةه الماءه أنْْاراً .\n42 لأنه ذركر كلمترهُ المقدىسةر ،\nالتي قرىرها مع إبراهيمر عبده\n43 فأخرجر شعبرهُ بابتهاجٍ ،\nومُُتاريه بفرحٍ .\n44 وأعطاهُم أراضىر الأُمرمه ،\nوتعبُ الشعوبه ورثوهُ ،\n45 لكى يُرفظوا حُقوقرهُ ،\nويلتمسوا ناموسرهُ .", "105": "المزمورُ المئةُ والخامسُ\nهلّلويا\n1 اهعتَرفوا للربِّ ، فإنه صالهحٌ ،\n\nوأنى إلى الأبده رحْْترهُ .\n2 من يقدرُ أن يصفر جبِروتر الربّ ،\nوَرعلر جميع تسابيحه مسموعةً ؟\n3 طوبى للذينر يُرفظونر الحُكْمر ،\nويصنعونر العدلر كُلى حينٍ .\n4 اُذْكُرْنا ، يا ربُّ ، بِهسرةه شعبك ،\nوتر عهىدْنا بِهلاصهكر .\n5 لكى نـرى صلاحر مُُتارهيكر ،\nولهنفرحر بفرحه أُمىتهكر ،\nولهنفتخر مع ميراثهكر .\n6 فإننا أخطأنا مع آبايهنا ،\nوأرثَهنا ، وظرلرمْنا\n7 آباؤنا وهُم في مهصر لم يفهموا عجايبركر ،\nولم يذكروا كثْرةر رحْْتهكر ،\nوأغضبوك عندر صعوده هم في البحره الأحْْره .\n8 فخلىصرهُم من أجله اسْْه ،\nلهيُظْهر قوىترهُ\n9 اهنتهر البحر الأحْْر فيربهسر ،\nوهداهُم في العُمْقه كالقفره\n\n11 وخلىصرهُم من أيدهى مُبغضهيهم ،\nوأنقذرهُم من يده أعدايهم\n11 وغرطىى الماءُ مُضايقه يهم ،\nواحدٌ منهم لم يـربْقر .\n12 فآمنوا بكلمته ،\nوسربىحوا بتسبحته .\n13 ثم أسرعوا ونسوا أعمالرهُ ،\nولم يتمسىكوا بِهشورته\n14 واشتهوا شهوةً في البـرِّيةه ،\nوجرىبوا الله في مكانٍ بلا ماءٍ .\n15 وأعطاهُم الذي سألوهُ ،\nوأرسرلر الشهبرعر لهنفوسهم .\n16 أغضبوا موسرى في المعسكره ،\nوهرونر قديسر الربّ\n17 الأرضُ فتحتْ فاها وابتلعرتْ داثانر ،\nوغرطىتْ على مجمع أبيرونر\n18 واشتعلرته النارُ في مَرْمعهم ،\nواللهيبُ أحرقر الخطاةر .\n19 وصرنرعوا عهجلاً في حوريبر ،\n\nوسرجدوا لهصنايعه اليده\n21 واستبدلوا مَردرهُم\nبِهثاله عهجْلٍ آكله عُشْبٍ .\n21 ونرسوا الإلهر الذي يُنجِّيهم ،\nالذي صرنرعر العظايمر في مهصر ،\n22 والعجايبر في أرضه حامر ،\nوالأعمالر المرخوفةر في البحره الأحْْره .\n23 وقالر ، لأستأصلْ هُم ،\nلولا أنى موسر ى مُُتاره\nقامر قُدىامرهُ في الكسْره ،\nلهيرجهعر عن سُخْطه غضبه ،\nولا يستأصلُهُم .\n24 رذلوا الأرضر الشهيىةر ،\nولم يُؤمنوا بكلمته\n25 وترمروا في خيامهم ،\nولم يسمعوا صوتر الربّ .\n26 فـرفرعر يدرهُ عليهم ،\nلهيرطرحرهُم في البـرِّيةه ،\n27 ويطرحر ذُرِّيتـرهُم في الأُمرمه ،\n\nويُبدِّدرهُم في الأراضى .\n28 أكملوا لهبعله فاغور ،\nوأكلوا ذبايحر الموترى\n29 وأغاظوهُ بأعمالهم ،\nفركرثـُر السقوطُ بينـرهُم .\n31 فقامر فينحاسُ وخلىصرهُم ،\nوكرفىته الضربةُ عنهُم\n31 فحُسهبر لرهُ ذلكر بهرّاً\nإلى جيلٍ فجيلٍ إلى الأبده .\n32 وأسْخطوهُ على ماءه المقاومةه ،\nفتأذىى موسرى من أجلهم ،\n33 لأنـىهُم مرمروا روحرهُ ،\nفأفـْرطر بشفتـريْه .\n34 ولم يـُهْلهكوا الأُمرمر الذين قالر لهرُم الربُّ ،\n35 واختلطوا بالأُمرمه وتعلىموا أعمالهرُم\n36 وتعبىدوا لهمصنوعاته اليده ،\nفصارتْ لهرُم شركاً\n37 وذبَروا بنهيهم وبناتُهم للشياطينه ،\n38 وسفكوا دماً زكيّاً ،\n\nدمر بنهيهم وبناتُهم\nالذين ذبَروهُم لهمنحوتاته كنعانر\nوفسدته الأرضُ بالقتله والدماءه ،\n39 وتنجىسرته الأرضُ بأ عمالهم\nوزنوا بهصنايهعهم .\n41 فغرضهبر الربُّ بهسُخْطٍ على شعبه ،\nورذرلر ميراثرهُ\n41 وأسْلرمرهُم بأيدهى الأُمرمه ،\nوتسلىطر عليهم مُبغضوهُم\n42 وأحزرنـرهُم أعداؤُهُم ،\nوذلُّوا وتحت أيدهيهم .\n43 مهراراً كثيرةً أرنـْقرذرهُم ،\nأما هُم فأغضبوهُ بِهشوراتُهم ،\nوذرلُّوا في آثامهم .\n44 فنرظر الربُّ إلى شهدىتُهم ،\nإذ سْرهعر صُراخرهُم\n45 وذركر عرهْدرهُ ،\nونردهمر حسب كثرة رحْْته ،\n46 وأعطاهُم الرأفاته\n\nقُدىامر الذين سربوهُم .\n47 خرلِّصْنا ، أيُها الرب إلهرُنا ،\nواجَْعْنا من بـرينْه الأُمرمه ،\nلهنعتَرفر باسْْهكر القدُّوسه ،\nونفتخر بتسبيحهكر .\n48 مُباركٌ الربُّ إلهُ إسراييلر ،\nمنذُ الأزله وإلى الأبده\nويقولُ كُلُّ الشعبه : يكونُ يكونُ .", "106": "المزمورُالمئةُ والسادسُ\nهلّلويا\n1 اهعتَرفوا للربِّ ، فإنه صالهحٌ ،\nوأنى إلى الأبده رحْْترهُ .\n2 فليـرقُله الذين نجروْا من قهبرله الربّ ،\nالذين أرنقذرهُم من أيدهى أعدايهم .\n3 ومن البُلدانه جَرعرهُم ،\nمن المشارقه والمغاربه والشهماله والبرحره .\n4 وضرلُّوا في القفره في مكانٍ عديمه الماءه ،\nولم َردوا سبيلاً إلى مدينة مساكنهم\n5 جياعاً وعطاشاً ،\nوقد فنيرتْ نفسُهُم فيهم .\n6 فصرخوا إلى الربّ في ضيقهم ،\nونجرىاهُم من شدايدهم\n7 وهرداهُم في طريقٍ مستقيمٍ ،\nلينطلقوا إلى مدينةه سركرنٍ .\n8 فليعتَرفوا للربِّ على مراحْه\nوعجايبه لهبرني البشر .\n9 لأنه أرشْبرعر نفساً خاويةً ،\n\nوالنفسُ الِايعةُ أرشْبـرعرها من الخيرْاته .\n11 الِلوسُ في الظلمة وظلاله الموته ،\nمُوثرقينر بالفقره والحديده .\n11 لأنـىهُم مرمروا كلامر الله ،\nومشورةر العليِّ أغضبوها\n12 واتضعرقلبـُهُم بالأتعابه ،\nضعفوا ولم يكُنْ لهرم مُعينٌ .\n13 فصرخوا إلى الربّ في ضيقهم ،\nوخرلىصرهُم من شدايدهم\n14 وأخْرجرهُم من الظلمةه وظلاله الموته ،\nوقرطىعر قيودرهُم .\n15 فليعتَرفوا للربِّ على مراحْه\nوعجايبه لهبرني البشر .\n16 لأنه كرسىر أبوابر النُحاسه ،\nوحرطىمر عوارضر الحديده .\n17 وانتشلرهُم من طريقه إثَْهم ،\nلأنـىهُم ذُلُّوا من أجله آثامهم .\n18 مرقرترتْ أنفسُهُم كُلى طعامٍ ،\nواقتَربوا إلى أبوابه الموته .\n\n19 فصرخوا إلى الربّ في ضيقهم ،\nوخرلىصرهُم من ش دايدهم ،\n21 أرسرلر كلمترهُ فشفاهُم ،\nونجرىاهُم من فسادهم .\n21 فليعتَرفوا للربِّ على مراحْه\nوعجايبه لهبرني البشر .\n22 وليرذبَروا لرهُ ذبيحةر التسبيح ،\nوليعتَرفوا بأعماله بالتهليل .\n23 الذين ينْزلونر إلى البحره في السفنه ،\nويعملونر عم لرهُم في المياه الكثيرةه ،\n24 لأنـىهُم عاينوا أعمالر الرب\nوعجايبرهُ في العُمْقه .\n25 قالر ، فقامرتْ ريحٌ عاصفةٌ ،\nوارتفعرتْ أمواجُها\n26 يصعدونر إلى السماوات ،\nويرهبطونر إلى الأعماقه\nفذابتْ أنفسُهُم من الشروره ،\n27 اضطربوا وترنُىوا مثلر ا لسكرانه ،\nوكُلُّ حهكْمتهم اهبـْتُلهعرتْ .\n\n28 فصرخوا إلى الربّ في ضيقهم ،\nومن شدايدهم أرخْرجرهُم .\n29 انتهر العاصفةر فـرهردأرتْ ،\nوسكنرتْ أمواجُها\n31 ففرحوا أنْىا سكنرتْ ،\nوهرداهُم إلى ميناءه مشيئته .\n31 فليعتَرفوا للرب على مراحْه\nوعجايبه لهبرني البشر .\n32 فليرفعوهُ في كنيسةه شعبه ،\nولْيُباركوهُ في مجلس الشيوخه .\n33 مجّد الأنْْار قفراً ،\nومجاري المياه عطشرى ،\n34 الأرضُ المُثمرةُ مجّدها مالحهةً ،\nمن شرِّ ساكنهيها .\n35 مجّد القفر بَُريرْاته ميا هٍ ،\nوأرضاً بلا ماءٍ ينابيعر مياهٍ\n36 وأرسْكرنر هناكر الِياعر ،\nوأرقامر مدينةر سركرنٍ ،\n37 زرعوا حقولاً وغرسوا كُروماً ،\n\nوصنعوا ثَر الغرلىةه.\n38 باركرهُم فكرثُروا جداً ،\nوبِرايمهم لم ترقهلى .\n39 ثم قلُّوا وتأذُّوا\nمن حُزْنه الشروره وورجرعه القلب .\n41 انسكبر الهوانُ على رؤسايهم ،\nوأضلىهُم في التيه ولا طريق .\n41 أعانر المسكينر من فقره ،\nومجّد أُبـُوىةً مثلر الخرافه .\n42 يُبصهرُ المستقيمونر ويفرحونر ،\nوكُلُّ إثٍُْ يرسُدُّ فاهُ .\n43 من هو الحكيمُ له يحفظر هذه\nويفهمر مراحهمر الربّ ؟", "107": "المزمورُ المئةُ والسابعُ\nمزمورٌ تسبحةٌ لداود\n2 مُستعدٌ قلبِه ، يا اللهُ ، مستعدٌ قلبِه ،\nأُسبِّحُ وأُرتِّلُ في ترجيدهى\n3 قُمْ يا مَردهى ، قُمْ أيُها المزمارُ والقيثارُ\n\nأنا أستيقظُ وقتر السرحره .\n4 لأعتَرفر لكر في الشعوبه ، يا ربُ ،\nوأُرتِّلر لكر في الأُمرمه\n5 لأنى رحْْتركر عظيمةٌ هى فوقر السماوات ،\nوإلى السحابه حرقٌّكر .\n6 اهرترفهعْ ، اللهُمى ، على السماوات ،\nوعلى سايره الأرض مَردُكر .\n7 لكى ينجُور أحباؤُكر ،\nخرلِّصْني بهيمينهكر واستجبْ لي .\n8 اللهُ تكلىمر في قُدُّوسه ،\nإنِِّ أرتفعُ وأُقرسِّمُ شكيمر ،\nوأقيسُ وادهى المظلةه .\n9 لي هو جلعادُ ، ولي هو منسىى ،\nإفرايمهُ هو عهزُّ رأسهى\nيهوذا هو مرلهكهى ،\n11 موآبُ آنيةُ رجايى\nعلى أدومر أمدُّ حذايى ،\nلي خرضرعرته ا لقبايلُ الغريبةُ .\n11 من يُبلِّغُني إلى مدينةٍ حصينةٍ ؟\n\nأو من يرهديني إلى الأدوميةه ؟\n12 أليسر أنت هو ، يا اللهُ ، الذي أرقصيترنا ؟\nولم تُرجْ ، يا اللهُ ، معنا في قوىاتهنا ؟\n13 أرعْطهنا عروْناً في الشهدىةه ،\nفباطلٌ هو خلاصُ الإنسانه .\n14 بإلهرهنا نصنعُ القوىةر ،\nوهو يُرذهلُ أعداءرنا .", "108": "المزمورُ المئةُ والثامنُ\nإلى النهايةه مزمورٌ لداود\n1 اللهُمى ، لا تسكتْ عن تسبيحى\n2 لأنى فمر الخاطئه وفمر الغاشِّ قد انفتحا عليّ ،\nوتكلىما عليّ بهلسانٍ غاشٍّ\n3 وبكمه بـُغْضٍ أحاطوا بي ،\nوحاربوني مَرىاناً .\n4 وبدلر أنْ يُُبُّوني سعوا بي ،\nوأنا كُنْتُ أصلِّى\n5 وقرىروا عليّ الشرور بدلر الخيرْاته ،\nوبـُغْضاً بدلر مُربتَّه .\n\n6 تُقيمُ عليه خاطئاً ،\nوليقفْ إبليسُ عن يَرينه\n7 إذا حُوكهمرفلْيرخرجْ مُذْنهباً ،\nوصلاتُهُ تكونُ خطيةً .\n8 ولتكُنْ أيامُهُ قليلةً ،\nأسقفيتُهُ لهيأخُذْها آخرُ\n9 لهيركُنْ بنوهُ أيتاماً ،\nواهمرأتُهُ تصيرُ أرملةً\n11 ليضطربْ بنوهُ ويتنقىلوا ويستعطوا ،\nويُطرحوا من مساكنهم .\n11 يفحصُ الغريمُ عن كُلِّ شىءٍ لرهُ\nويَرطفُ الغرباءُ جميع أتعابه\n12 لا يركُنْ لرهُ ناصرٌ ،\nولا من يتَراءرفُ على يتاماهُ\n13 لهيركُنْ بنوهُ للاستئصاله ،\nفي جيلٍ واحدٍ يَُْحرى اسُْْهُ .\n14 لهيُذْكرْ إثُُْ آبايه لدى الربّ ،\nوخطيةُ أُمِّه لا تُْحرى\n15 وتكونُ أمامر الربّ كُلى حينٍ ،\n\nويُبادُ من على الأرض ذهكْرُهُم .\n16 من أجله أنه لم يرذْكُرْ أنْ يصنعر رحْْةً ،\nوطردر إنساناً فقيراً وضعيفاً ،\nوالمتوجِّعر القلب لكى يقتلرهُ .\n17 أحبى اللعنةر ، فهى تأتهيه\nولم يُرهدْ البـركرةر ، فتربعُدر عنْهُ .\n18 لبسر اللعنةر مثلر الثوبه ،\nفدخلتْ مثلر الماءه في أحشايه ،\nوكرزريْتٍ في عظامه .\n19 لهتركُنْ لرهُ كرثوبٍ يتسربلُهُ ،\nومثلر مهنْطرقرةٍ يتمنطقُ بِها كُلى حينٍ .\n21 هذا هو عرملُ الذين يسعونر بي عندر الربّ ،\nوالذين يتكلىمونر بالشروره على نفسي .\n21 أما أنت ، أيُها الربُّ إلهي ، فاصنرعْ معى رحْْةً\nمن أجله اسْْهكر ،\nفإنى رحْْتركر يا ربُّ هى صالحهةٌ ، فنرجِّني\n22 لأني فقيرٌ وضعيفٌ أنا ،\nوقد اضطربر قلبِه في باطني .\n23 مثلر الظلِّ المايله فرنهيتُ ،\n\nوطفرتُ مثلر الِراده .\n24 ركبتاىر ضرعُفرتا من الصومه ،\nوتغيـىر جسدهى من عدمه الزيته .\n25 وأنا صهرْتُ لهرُم عاراً\nنظروا إلِرى وحرىكوا رؤوسرهُم .\n26 أرعهنِِّ ، أيُها الربُّ إلهرهى ،\nوخرلِّصْني كرحْْتهكر\n27 ولْيـرعْلرموا أنى هذه هى يدُكر ،\nوأنت ، يا ربُّ ، صرنـرعْترها .\n28 هُم يلعنونر ، وأنت تُباركُ\nلهيرخْزر الذين يقومونر عليّ ،\nوأما عبدُكر فيفرحُ .\n29 لهيلْبسه الذين يثلهبونرني العار ،\nوليشتملوا بالخهزْىِّ كالرداءه .\n31 أعتَرفُ لكر يا ربُّ جداً بفمى ،\nوفي وسطه كثيرينر أُسبِّحُكر\n31 لأنه ورقرفر عن يَرينه المسكينه ،\nلهيُخرلِّصر نفسي من الذين يضطهدونرني .", "109": "المزمورُ المئةُ والتاسعُ\nمزمورٌ لداود\n1 قالر الربُّ لهربَِّ اهجْلهسْ عن يَريني\nحتَّى أضعر أعداءركر وتحت موطئه قدرمريْكر .\n2 عصا قوىةٍ يُرسهلُ لكر الربُّ من صه يونر\nوتسودُ في وسطه أعدايهكر .\n3 معكر الرياسةُ في يومه قوىتهكر ،\nفي بِراءه قدِّيسهيكر\nمهنر البطنه قبلر كوكبه الصُبْحه ولدْتُكر .\n4 أقسرمر الربُّ ولا يندمُ ،\nأنكر أنت هو الكاهنُ إلى الأبده\nعلى طقسه ملكيصادق .\n5 الربُّ عن يمينك حرطىمر يومه رهجْزه ملوكاً .\n6 يقضى بـرينْر الأُمرمه ويَرلأُهُم جُثرثاً ،\nيسحقُ رأسر كثيرينر على الأرض .\n7 وفي الطريقه يشربُ الماءر من الوادهى .\nمن أجله هذا يرفعُ رأسرهُ .", "110": "المزمورُ المئةُ والعاشرُ\nهلّلويا\n1 أعتَرفُ لكر ، يا ربُّ ، من كُل قلبِه ،\nفي مشورة المستقيمينر وفي مجمعهم .\n2 عظيمةٌ هى أعمالُ الربّ ،\nومشيئاتُهُ كُلُّها مفحوصةٌ\n3 الاعتَهافُ وعظيمُ البهاءه عرمرلُهُ ،\nوبهرُّهُ دايمٌ إلى أبده الأبده .\n4 ذركر جميع عجايبه ،\nرحومٌ هو الربُّ ورؤوفٌ\n5 أعطرى طعاماً لأتق يايه ،\nيذكُرُ إلى الأبده عرهْدرهُ .\n6 أرخْبـر شعبرهُ بقوىةه أعماله ،\nلهيـُعْطيـرهُم ميراثر الأُمرمه .\n7 أعمالُ يدريْه حقٌّ وحُكْمٌ\nكُلُّ وصاياهُ صادقةٌ ،\n8 ثابتةٌ إلى دهره الدهوره ،\nمصنوعةٌ بالحقِّ والاستقامةه .\n9 أرسرلر خلاصاً لهشعبه\n\nأرمر بهعهده إلى الأبده\nاسُْْهُ قدُّوسٌ مرهوبٌ .\n11 رأسُ الحكمةه مُرافةُ الربّ ،\nوالفهمُ صالهحٌ لهكُلِّ من يرعملُ به\nوتسبيحُهُ يدومُ إلى أبده الأبده .", "111": "المزمورُ المئةُ والحادى عشرَ\nهلّلويا\n1 طوبى للرجله الخايفه ال ربىٍه ،\nويـرهْورى وصاياهُ جداً\n2 يـرقْورى على الأرض زرْعُهُ ،\nجيلُ المستقيمهينر يُباركُ\n3 مَردٌ وغهنِر في بيته ،\nوبهرُّهُ يدومُ إلى الأبده .\n4 نورٌ أشرقر في الظلمةه للمستقيمهينر\nرحيمٌ هو الربُّ اللهُ ورؤوفٌ وبارٌّ .\n5 صالهحٌ هو الرجلُ الذي يتَراءرفُ ويـُقْرهضُ ،\nيُدربـِّرُ أقوالرهُ بالحقِّ\n6 لأنه لا يترزعزعُ إلى الدهره\n\nذهكْرُ الصدِّيقه يدومُ إلى الأبده .\n7 لا يَرشرى من خربِره سوءٍ\nقلبُهُ مستعدٌ أن يتىكهلر على الربّ .\n8 قلبُهُ ثابتٌ لا يترزعزعُ ،\nحتَّى يـر ى بأعدايه .\n9 فـرىقر وأعطرى المساكينر ،\nبهرُّهُ دايمٌ إلى أبده الأبده\nيرتفعُ قـرْنُهُ بالمرجده .\n11 يـُبْصهرُ الخاطئُ فيغتاظُ ،\nيُصهرُّ بأسنانه ويذوبُ\nشهوةُ الخاطئه تبيدُ .", "112": "المزمورُ المئةُ والثانِى عشرَ\nهلّلويا\n1 سربِّحوا الربّ ، أيُها الفتيانُ ،\nسربِّحوا اسمر الربّ .\n2 ليركُنْ اسمُ الربّ مُباركاً\nمن الآنه وإلى الأبده\n3 مهنْ مشارقه الشمسه إلى مغاربِها\n\nباركوا اسمر الرب .\n4 الربُّ عالٍ على كُلِّ الأُمرمه ،\nوفوقر السماوات مَردُهُ .\n5 من مهثْلُ الربٍٍّ إلهرهنا ؟\nالساكنه في الأعالي ،\n6 والناظره إلى المتواضعينر\nفي السماء وعلى الأرض\n7 الذي أقامر المسكينر من التَُابه ،\nويرفعُ البايسر من المرزْبـرلرةه ،\n8 لكى َرلسر مع الرؤساءه ،\nمع رؤساءه شعبه\n9 الذي َرعلُ العاقر ساكنةً في بيتٍ ،\nأُمى أولادٍ فرهحرةً .", "113": "المزمورُ المئةُ والثالثَ عشرَ\nهلّلويا\n1 عند خروجه إسراييلر مهن مهصْر ،\nوبيته يعقوب من شعبٍ أعجمى ،\n2 صارتْ له اليهوديةُ مرقْدهساً ،\n\nوإسراييلُ هو سلطانُهُ .\n3 أبصر البحرُ فـرهرب ،\nوالأردنُ رجعر إلى خلفٍ\n4 تُرلىلرته الِبالُ مثلر الكباشه\nوالآكامُ مثلر حُْْلانه الغنمه .\n5 مرا لركر ، أيُها البحرُ ، قد هربْتر ؟\nوأنت ، أيُها الأردنُ ، قد رجهعْتر إلى خلفٍ ؟\n6 ويا جبالُ ، قد تُرلىلْته مثلر الكباشه ؟\nوأيتها التلالُ ، مثلر حُْْلانه الغنمه ؟\n7 من قُدىامه وجه الربّ تزلزلرته الأرضُ ،\nمن قُدىامه وجه إله يعقوب ،\n8 الذي حروىلر الصخرةر إلى بَُيرْاته مياهٍ ،\nوالحجر الصوىانر إلى ينابيعه مياهٍ .\n9 ليس لنا ، يا ربُّ ، ليس لنا\nبل لاسْْهكر أرعْطه مَرْداً\nعلى رحْْتهكر وحرقِّكر .\n11 لئلا يقولر الأُمرمُ :\nأين هو إلهرُهُم ؟\n11 أما إلهرُنا فهو في السماء فوقُ\n\nفي السماوات وعلى الأرض\nكُلُّ الأشياءه التي أرادرها صرنـرعرها .\n12 أوثانُ الأُمرمه ذهبٌ وفضةٌ ،\nهى أعمالُ أريْدهى الناسه .\n13 لهرا أفواهٌ ولا تتكلىمُ ،\nلهرا أرعْينٌُ ولا تُ بصرُ\n14 لهرا آذانٌ ولا ترسمعُ ،\nلهرا أنفٌ ولا ترشُمُّ\n15 لهرا أيدٍ ولا تـرلْمهسُ ،\nلهرا أرجُلٌ ولا ترشهى\nولا تقدرُ أنْ تُعطىر صوتاً بَهنجرتُها .\n16 مهثـْلرها يكونُ كُلُّ صانهعهيها ،\nوجميع المتوكلين عليها .\n17 بيتُ إسراييلر اهتىكلوا على ال ربِّ\nهو مُعينـُهُم وناصرُهُم .\n18 بيتُ هارونر اهتىكلوا على الرب\nهو مُعينـُهُم وناصرُهُم .\n19 الذين يَرافونر الربّ اهتىكلوا على الرب\nهو مُعينـُهُم وناصرُهُم .\n\n21 الربُّ ذركرنا وباركرنا ،\nباركر بيتر إسراييلر ،\nبار كر بيتر هارونر\n21 باركر خايفي الرب ،\nالصغار مع الكباره .\n22 لهيرزهده الربُّ فينا ،\nفينا وفي أولادهنا\n23 نُرنُ مُباركونر من الربّ ،\nالذي خرلرقر السماءر والأرضر .\n24 سْراءُ السماء هى للربِّ ،\nأما الأرضُ فأعطاها لهبرني البشر .\n25 ليس الأمواتُ يُسبِّحونركر ، يا ربُّ ،\nولا كُلُّ الهابطهينر إلى الِحيمه\n26 بل نُرنُ الأحياءُ نباركُكر ، يا ربُّ ،\nمن الآنه وإلى الأبده .", "114": "المزمورُ المئةُ والرابعَ عشرَ\nهلّلويا\n1 أحببْتُ لأنى الربّ يسمعُ\n\nصوتر تضرُّعهى ،\n2 لأنه أرمالر أُ ذُنرهُ إلِرى ،\nفدرعروْتُهُ في أيامى .\n3 لأنى أوجاعر الموته اهكتنفتْني ،\nشدايدُ الِحيمه صادفتْني\nضهيقاً وحُزْناً ورجدْتُ .\n4 وباسمه الربّ درعروتُ\nيا ربُّ ، نرجِّ نفسي .\n5 رحومٌ هو الربُّ وصهدِّيقٌ ،\nوإلهرُنا يرحرمُ .\n6 الذي يُرفظُ الأطفالر هو الربُّ\nاتىضرعْتُ ، فرخرلىصرني .\n7 اهرْجهعهى يا نفسي ، إلى موضعه راحتهكه ،\nلأنى الربّ قد أحسرنر إلِرى\n8 وأنقذر نفسي من الموته ،\nوعريـْنِرى من الدموعه ،\nورهجْلرىى من الزىلرقه .\n9 أُرْضهى الربّ أمامرهُ\nفي كورةه الأحياءه .", "115": "المزمورُ المئةُ والخامسَ عشرَ\nهلّلويا\n1 آمنْتُ ، لذلكر تكلىمتُ\nأنا اهتىضعْتُ جداً .\n2 أنا قـُلْتُ في حريـْرتهى\nإنى كُلى الناسه كاذبونر .\n3 بِهاذا أُكافئُ الربّ\nعن كُلِّ ما أعْطانهيه ؟\n4 كأسر الخلاصه آخُذُ ،\nوباسمه الربّ أردعو\n5 أُوْفىه نذورى للربِّ\nقُدىامر كُلِّ شعبه .\n6 كريمٌ أمامر الرب\nمروْتُ قديسيه .\n7 يا ربُّ ، أنا هو عبدُكر ،\nأنا هو عبدُكر وابنُ أرمرتهكر\nقرطرعْتر قيودهى .\n8 لكر أذبرحُ ذبيحةر التسبيح ،\nوباسمه الربّ أدعو\n9 أُوْفىه نذورهى للرب\nفىه ديا ره بيته الربّ ،\n11 قُدىامر كُلِّ شعبه ،\nفىه وسطهكه ، يا أورشليمُ .", "116": "المزمورُ المئةُ والسادسَ عشرَ\nهلّلويا\n1 سربِّحوا الربّ ، يا جميع الأُمرمه ،\nولْتُبارهكْهُ جميع الشعوبه\n2 لأنى رحْْترهُ قد قويرتْ علينا ،\nوحقُّ الر بِّ يدومُ إلى الأبده .", "117": "المزمورُ المئةُ والسابعَ عشرَ\nهلّلويا\n1 اهعتَرفوا للربِّ ، فإنه صالهحٌ ،\nوإنى إلى الأبده رحْْترهُ .\n2 فلْيقُلْ بيتُ إسراييلر إنه صالهحٌ ،\nوإنى إلى الأبده رحْْترهُ .\n3 فلْيقُلْ بيتُ هارونر إنه صالهحٌ ،\nوإنى إلى الأبده ر حْْترهُ .\n4 لهيقُلْ أتقياءُ الربّ إنه صالهحٌ ،\nوإنى إلى الأبده رحْْترهُ .\n5 في ضيقتَّه صرخْتُ إلى الربّ ،\nفاستجاب لي وأخرجرني إلى الرُّحْبه .\n\n6 الربُّ هو عروْني ، فلا أخشرى\nماذا يصنعُ بي الإنسانُ ؟\n7 الربُّ هو لي مُعينٌ ،\nوأنا أرى بأعدايى .\n8 جيِّدٌ هو الاتِّكالُ على الرب\nأفضرلُ من الاتِّكاله على البشر\n9 جيِّدٌ هو الرجاءُ بالرب\nأفضرلُ من الرجاءه بالرؤساءه .\n11 كُلُّ الأُمرمه أحاطوا بي ،\nوباسمه الربّ انتقمْتُ منهم\n11 أحاطوا بي واكتنفوني ،\nوباسمه الر بِّ انتقمْتُ منهم\n12 أحاطوا بي مثلر النحله حولر الشرهْده ،\nوالتهبوا كنارٍ في شوكٍ ،\nوباسمه الربّ انتقمْتُ منهم .\n13 دُفهعْتُ لأرسْقُطر ،\nوالربُّ عرضىدرني .\n14 قـُوىتهى وتسبحتَّه هو الربُّ ،\nوقد صار لي خلاصاً .\n\n15 صوتُ التهليل والخلاصه في مساكنه الأبرار .\nيَرينُ الربّ صرنـرعرتْ قـُوىةً .\n16 يَرينُ الربّ رفـرعرتْني ،\nيَرينُ الربّ صرنـرعرتْ قـُوىةً .\n17 لن أموتر بـرعْدُ بل أحيا ،\nوأُحردِّثُ بأعماله الربّ .\n18 تأديباً أردىبرني الربُّ ،\nوإلى الموته لم يُسرلِّمْني .\n19 اهفتحوا لي أبوابر البِهِّ ،\nلكى أدخُلر فيها وأرعتَرفر للربِّ .\n21 هذا هو بابُ الربّ ،\nوالصهدِّيقونر يدخلونر فيه .\n21 أعتَرفُ لكر ، يا ربُّ ، لأنك استرجبْتر لي ،\nوكُنْتر لي مُُرلِّصاً .\n22 الحرجرُ الذي رذرلرهُ البنىاؤونر ،\nهذا صار رأساً للزاويةه\n23 مهنْ قهبرله الربّ كانر هذا ،\nوهو عجيبٌ في أعينهنا .\n24 هذا هو اليومُ الذي صرنـرعرهُ الرب\n\nفلْنبتهجْ ونفرحْ فيه.\n25 يا ربُّ ، خرلِّصْنا ،\nيا ربُّ ، سرهِّلْ طريقنا .\n26 مُباركٌ الآتهى باسمه الرب\nباركناكُم من بيته الربّ .\n27 اللهُ الربُّ أضاءر علينا\nرتِّبوا عيداً في الواصلهينر\nإلى قُرونه المذبرحه .\n28 أنت هو إلهي ، فأعتَرفُ لكر\nإلهي أنت ، فأرفعُكر\nأعتَرفُ لكر يا ربُّ ، لأنك استرجبْتر لِه\nوصهرْتر لي مُُرلِّصاً .\n29 اهعتَرفوا للربِّ ، فإنه صالهحٌ ،\nوأنى إلى الأبده رحْْترهُ .", "118": "المزمورُ المئةُ والثامنَ عشرَ\nهلّلويا\n(1)\n1 طوباهُم الذين بلا عريْبٍ في الطريقه ،\n\nالسالكونر في ناموسه الرب .\n2 طوباهُم الذين يفحصونر عن شهاداته ،\nومن كُلِّ قلوبِهم يطلبونهُ\n3 لأنى صانعهى الإثُْه\nلم يـرهْوروْا أن يسلكوا في سُبُله ،\n4 أنت أمرتر\nأنْ تُُْفرظر وصاياكر جداً .\n5 ليتر طُرُقهى تستقيمُ\nإلى حهفْظه حقوقهكر\n6 حينئذٍ لا أرخْزرى ،\nإذا ما اهطىلرعْتُ على جميع وصاياكر .\n7 أعتَرفُ لكر ، يا ربُّ ، باستقامةه قلبِه ،\nإذا عرفْتُ أحكامر عدلهكر .\n8 وحقوقركر أحفظُ ،\nفلا ترفُضْني إلى الغايةه .\n(2)\n9 بِهاذا يـُقروِّمُ الشابُّ طريقهُ ؟\nبَهفْظه أقوالركر .\n11 من كُلِّ قلبِه طلبتُكر ،\n\nفلا تـُبْعهدْني عن وصاياكر .\n11 أرخْفيتُ أقوالركر في قلبِه ،\nلكى لا أُخْطهئُ إليك .\n12 مُباركٌ أنت ، يا ربُّ ،\nعرلِّمْني حُقوقركر .\n13 بهشرفرتَّرى أرظْهرْتُ\nكُلى أحكامه فرمهكر\n14 وفرهحْتُ بهطريقه شهاداتهكر\nمثلر كُلِّ غهنِر .\n15 بوصاياكر أتكلىمُ ،\nوأترفهىمُ في طُرُقهكر\n16 بَهُقوقهكر أرهذ ،\nولا أنسرى كلامركر .\n(3)\n17 كافىهءْ عربْدركر\nفأحيا ، وأحفظر أقوالركر .\n18 اهكْشهفْ عن عريـْنِرى ،\nفأتأمىلر عجايبركر من ناموسهكر .\n19 غريبٌ أنا في الأرض ،\n\nلا تُُْفه عرنِِّ وصاياكر .\n21 اشتاقرتْ نفسي أنْ ترشترهى\nأحكامركر كُلى حينٍ .\n21 انتهرْتر المتركبِِّينر\nملاعينٌ الذين حادوا عن وصاياكر .\n22 اهنـْزرعْ عرنِِّ العار والخهزْىر ،\nفإنِِّ لهشهاداتهكر اهبتغيْتُ .\n23 جرلرسر الرؤساءُ أيضاً ، وتقاولوا عليّ\nأما عربْدُكر فكانر يرهترمُّ بَهُقوقهكر\n24 لأنى شهاداتهكر هى درْسهى ،\nوحُقوقركر هى مرشوراتهى .\n(4)\n25 لرصهقرتْ بالأرض نفسي\nفأحْيهني حسب كرلهمتهكر .\n26 أرخْبِرتُ بهطُرُقهكر ، فاسترجربْتر لِه\nعرلِّمْني حُقوقركر .\n27 طريق حُقوقهكر فـرهِّمْني إياه ،\nفأهذى في عجايبك .\n28 نرسهيتُ نفسي من الحُ زْنه ،\n\nثـربِّتْني في أقوالك\n29 طريق الظُلْمه أربْعهدْ عرنِِّ ،\nوبهناموسهكر ارحمني .\n31 اهخْتـرْتُ طريق الحق\nوأحكامركر لم أرنْسر .\n31 لرصهقْتُ بهشهاداتهكر\nيا ربُّ ، لا تُُْزهني .\n32 في طريقه وصاياكر أرجْرهى ،\nإذا ما ورسىعْتر قلبِه .\n(5)\n33 ضرعْ لي ، يا ربُّ ، ناموساً في طريقه حُقوقهكر ،\nفأتبعرهُ في كُلِّ حينٍ .\n34 فـرهِّمْني ، فأفحرصر ناموسركر ،\nوأرحْفرظرهُ بهكُلِّ قلبِه .\n35 أرهْدهني في طريقه وصاياكر ،\nفإنِِّ إياها هروريْتُ .\n36 أرمهلْ قلبِه إلى شه اداتهكر ،\nوليس إلى الظُلْمه .\n37 أرْدهدْ عريـْنِرى لئلاى تُعايهنا الأباطيلر ،\n\nوفي سُبُلهكر أحْيهني .\n38 ثـربِّتْ قـروْلركر لهعبدهكر ،\nفي خروْفهكر .\n39 اهنـْزرعْ عرنِِّ العار الذي حرذهرْتُهُ ،\nفإنى أرحكامركر حُلْورةٌ .\n41 ها قد اشتهيتُ وصاياكر\nفلأحيا بهبِهِّكر .\n(6)\n41 لهتأته عليّ رحْْتُكر ، يا ربُّ ،\nوخلاصُكر حسب قـروْلهكر\n42 فأُجاوبر مُعريرِّهىى بكلمةٍ ،\nلأني اتىكرلْتُ على كلامهكر .\n43 لا تـرنـْزرعْ من فرمهى قـروْلر حرقِّكر إلى الغايةه ،\nلأني على أحكامهكر تو كىلْتُ .\n44 وأحفظُ ناموسهكر في كُلِّ حينٍ ،\nإلى الأبده وإلى أبده الأبده .\n45 كُنْتُ أسلُكُ في السهعرةه ،\nلأني لهوصاياكر ابتغيْتُ .\n46 وتكلىمتُ بهشهاداتهكر قُدىامر الملوكه ،\n\nولم أرخْزر\n47 وهرذرذْتُ بهوصاياكر\nالتي أرحبربْتُه ا جداً .\n48 ورفـرعْتُ يردرىى إلى وصاياكر التي وردهدْتُُا جداً\nوتأمىلْتُ في حُقوقهكر .\n(7)\n49 اُذْكُرْ لهعبدهكر كلامركر\nالذي جرعرلْترني عليه أتىكهلُ .\n51 هذا الذي عرزىاني في مرذرلىتَّه ،\nلأنى قـروْلركر أحياني .\n51 المُتركبِِّونر تَّراوزوا الناموسر إلى الغايةه ،\nأما أنا عن ناموسهكر لم أرمهلْ .\n52 ترذركىرْتُ أرحكامركر ، يا ربُّ ، منذُ الدهره\nفترعزىيْتُ .\n53 الكآبةُ مرلركرتْني\nمن أجله الخُطاةه الذين تـركوا عنهُم ناموسركر .\n54 حُقوقُكر كانتْ لي مزامير\nفي مروضهعه مسكني .\n55 ذركرْتُ في الليل اسْْركر ، يا ربُّ ،\n\nوحرفهظْتُ ناموسركر .\n56 هذا صار لي ،\nلأني طرلربْتُ حُقوقركر .\n(8)\n57 نصيبِه أنت ، يا ربُّ ،\nفقُلْتُ أنْ أرحفرظر وصاياكر .\n58 تـرضىيْتُ ورجْهركر بهكُلِّ قلبِه ،\nارحمني حسب قـروْلهكر .\n59 لأني تـرفركىرْتُ في طُرُقهكر ،\nفردردْتُ قردرمرىى إلى شهاداتهكر .\n61 تـرهريىأْتُ ولم أنـْزرعهجْ\nلحهفْظه وصاياكر .\n61 رباطاتُ الخُطاةه اهلْتـرفىتْ عليّ ،\nولم أرنْسر ناموسركر .\n62 في نصفه الليل أرنـْهرضُ لأعتَرفر لكر\nعلى أرحكامه بهرِّكر .\n63 شريكٌ أنا لهكُلِّ الذين يَرافونركر\nولحهافهظهى وصاياكر .\n64 منرحْْتهكر ، يا ربُّ ، اهمترلأرته الأرضُ\n\nعرلِّمْني حُقوقركر .\n(9)\n65 خريرْاً صرنـرعْتر مع عبدهكر ،\nيا ربُّ ، حسب قـروْلهكر .\n66 حلاوةً وأدباً ومعرفةً عرلِّمْني ،\nلأني بهوصاياكر آمنْتُ .\n67 قبلر أنْ أتواضعر أنا تكاسرلْتُ ،\nفرلهذا حرفهظْتُ كلامركر .\n68 حُلْوٌ أنت ، يا ربُّ ،\nفبصلاحهكر عرلِّمْني حُقوقركر .\n69 كرثـُر عليّ ظُلْمُ المتركبِِّينر ،\nوأنا بهكُلِّ قلبِه أبَْرثُ عن وصاياكر .\n71 تَّربْىر مث لر اللربْره قلبـُهُم ،\nأما أنا فـرلرهجْتُ بناموسهكر .\n71 خريـْرٌ لي أنكر أرذْلرلْترني ،\nلكى أرتـرعرلىمر حُقوقركر .\n72 خريـْرٌ لي أيضاً هو ناموسُ فرمهكر ،\nأفضرلُ مهنْ أُلوفه ذرهربٍ وفهضىةٍ .\n\n(11)\n73 يداكر صرنـرعرتاني وجربـرلرتاني\nفـرهِّمْني فأتعلىمر وصاياكر .\n74 الذين يَرافونركر يُبصرونرني ويفرحونر ،\nلأني على كلامهكر توكىلْتُ .\n75 عرلهمْتُ ، يا ربُّ ، أنى أحكامركر حقٌّ هى ،\nوأنت بَهقٍّ أرذْلرلْترني .\n76 فـرلْترأْته عليّ رحْْتُكر لهتُعزِّيني ،\nوكرلهمتُكر لهعبده كر\n77 ورلْترأْتهني رأفتُكر فأحيا ،\nفإنى ناموسركر هو تلاوتهى .\n78 لهيرخْزر المتكبِِّونر ، لأنـىهُم خالرفوا الناموسر عليّ ظُلْماً\nأما أنا فأكونُ مُثابهراً على وصاياكر .\n79 فـرلْيرجهعْ إلِرى الذين يَرافونركر ،\nوالذين يعرفونر عجايبركر .\n81 لهيرصهرْ قلبِه بلا عريْبٍ في حرقِّكر ،\nلكى لا أرخْزرى .\n(11)\n81 فرنهيرتْ نفسي إلى خلاصهكر ،\nوعلى كلمتهكر توكىلْتُ .\n\n82 كرلىتْ عريْناىر إلى كلمتهكر ،\nقايلتـرينْه متى تُعزِّيني ؟\n83 صهرْتُ مثلر زهقٍّ في جليدٍ\nولحهُقوقهكر ما نسيتُ .\n84 كرمْ هى أيامُ عبدهكر ؟\nمرتَّر تصنعُ لي حُكْماً من الذين يضطهدونرني ؟\n85 تكلىمر معى مُُالفو الناموسه بكلامه هرذريانٍ ،\nلكن ليس كناموسهكر ، يا ربُّ .\n86 لأنى كُلى وصاياكر هى حق\nوبهظُلْمٍ قد طردوني ، فأعنِِّ .\n87 لولا قليلٌ لأفنوني من ا رضه ،\nأما أنا فلرم أتركْ وصاياكر .\n88 حسب رحْْتهكر أحيني ،\nفأحفظر شهاداته فرمهكر .\n(12)\n89 كرلهمتُكر ، يا ربُّ ،\nدايمةٌ في السماوات إلى الأبده .\n91 وإلى جيلٍ فجيلٍ حرقُّكر\nأسىسْتر الأرضر فهى ثابتةٌ .\n\n91 بأمرهكر النهارُ أيضاً ثابتٌ ،\nلأنى الكلى عبيدٌ لكر .\n92 لو لم يكُنْ ناموسُكر تلاوتهى ،\nلكُنْتُ قد هرلركْتُ في مذلىتَّه .\n93 إلى الدهره لا أنسرى حُقوقركر ،\nلأنك بِها أحييترني ، يا ربُّ .\n94 لكر أنا ، يا ربُّ ، فرخرلِّصْني ،\nلأني طرلربْتُ حُقوقركر .\n95 إياىر اهنتظر الخُطاةُ لهيـُهْلهكوني ،\nولهشهاداتهكر فرهمْتُ .\n96 لكُلِّ ترامٍ رأيْتُ مُنتهرى ،\nأما وصاياكر فواسعةٌ جداً .\n(13)\n97 كرمْ هو مُربوبٌ اسُْْكر ، يا رب\nهو طولر النهاره تلاوتهى .\n98 عرلىمترني وصاياكر أفضرلر من أعدايى ،\nلأنْىا ثابتةٌ لي إلى الأبده .\n99 أكثـر من جميع الذين يُعلِّمونرني فرهمْتُ ،\nلأنى شهاداتهكر هى تلاوتهى .\n\n111 أكثـر من الشيوخه فرهمْتُ ،\nلأني طرلربْتُ وصاياكر .\n111 من كُلِّ طريقه شرٍّ مرنـرعْتُ رهجْلرىى ،\nلكى أحفظر كلامركر\n112 عن أحكامهكر لم أرحهدْ ،\nلأنك أنت الذي ورضرعْتر لي الناموسر .\n113 كرمْ هى حُلْوةٌ كلماتُكر في حرلْقهى ،\nأحْلرى من العسله والشرهْده في فرمهى .\n114 من وصاياكر تفطىنتُ\nفلهذا أبغضْتُ كُلى طُرُقه الظُلْمه ، لأنك ورضرعْتر لي ناموساً\n.\n(14)\n115 سراجٌ لهرهجْلهى هو ناموسُكر ،\nونورٌ لهسُبُلهى .\n116 حرلرفْتُ وأقرمْتُ\nعلى حهفْظه أحكامه بهرِّكر .\n117 تذلىلْتُ جداً إلى الغايةه\nيا ربُّ ، أرحْيهني حسب قـروْلهكر .\n118 ترعهُّداتُ فرمهى تبارهكُها ، يا ربُّ ،\n\nوعرلِّمْني أحكامركر .\n119 نفسي في يدريْكر كُلى حينٍ ،\nوناموسرك لم أرنْسر .\n111 أرخْفرى الخُطاةُ لي فرخّاً ،\nولم أرضهلى عن وصاياكر .\n111 ورثْتُ شهاداتهكر إلى الأبده ،\nلأنْىا هى بـرهْجرةُ قلبِه .\n112 عرطرفْتُ قلبِه لأصنرعر حُقوقركر ،\nمن أجله المُكافأةه إلى الأبده .\n(15)\n113 لهمُتجاوزى الناموسه أبغضْتُ ،\nوناموسركر أحببْتُهُ .\n114 لأنك أنت مُعيني وناصري ،\nوعلى كلمتهكر توكىلْتُ .\n115 اهبعدوا عنِِّ يا فاعلهى الإثُْر ،\nفأفحصر عن وصايا إلهرهى .\n116 اهقبـرلْني إليك حسب قرولهكر فأحيا ،\nولا تُُْزهني مه ن الذي أنتظرُهُ .\n117 أرعهنِِّ فأخلُصر ،\n\nوأتلور في حُقوقهكر كُلى حينٍ .\n118 رذهلْتر ساير الذين حادوا عن حُقوقهكر ،\nلأنى فهكْرهُم ظُلْمٌ .\n119 عُصاةً حرسهبْتر ساير خُطاةه الأرض ،\nفرلهذا أرحببتُ شهاداتهكر في كُلِّ حينٍ .\n121 سْرْ جسدى في خروْفهكر ،\nلأني من أحكامهكر جرزهعْتُ .\n(16)\n121 قد أجريتُ حُكْماً وعدلاً ،\nفلا تُسرلِّمْني إلى الذين يظلمونرني .\n122 اهقـْبل عبدركر إليك في الخريرْه ،\nلئلا يكذبر عليّ المستكبِهونر .\n123 كرلىتْ عيناىر من انتظاره خلاصهكر ،\nو كلمةه بهرِّكر .\n124 اهصْنرعْ مع عبدهكر حسب رحْْتهكر ،\nوحُقوقركر عرلِّمْني .\n125 عربْدُكر أنا فـرهِّمْني ،\nفأعرفر شهاداتهكر .\n126 إنه وقتٌ يـُعْمرلُ فيه للرب\n\nوقد نقضوا ناموسركر .\n127 لأجله هذا أحبربْتُ وصاياكر\nأفضرلر من ال ذهبه والِوهره .\n128 ولأجله هذا بهإزاءه كُلِّ وصاياكر ترقوىمْتُ ،\nوكُلى طريقه ظُلْمٍ أربغضْتُ .\n(17)\n129 عجيبةٌ هى شهاداتُكر ،\nلذلكر فرحرصرتْها نفسي .\n131 إعلانُ أقوالك يُنيرُ لي ،\nويـُفرهِّمُ الأطفالر الصغار .\n131 فتحتُ فمى واجتذبتُ لي روح اً ،\nلأني لهوصاياكر اشتقتُ .\n132 اُنظُرْ إلِرى وارحْرْني\nكرحْْتهكر للذين يُُبُّونر اسْْركر .\n133 قـروِّمْ خرطرواتهى كرقروْلهكر ،\nولا يتسلىطْ عليّ أىُّ إثٍُْ .\n134 أرنقهذْني من وشايةه الناسه ،\nفأحفظر وصاياكر .\n135 فـرلْيُضئْ وجهُكر على عبدهكر ،\n\nوعرلِّمْني حُقوقركر .\n136 جازرتْ عيناىر مجاري المياه ،\nلأنـىهُم لم يُرفظوا ناموسركر .\n(18)\n137 عادلٌ أنت ، يا ربُّ ،\nوقضاؤُكر مستقيمٌ\n138 أوصريْتر كثيراً بالعدله والحقِّ ،\nاللذريْن هُُا شهاداتُكر .\n139 غريـْرةُ بـريْتهكر أكلرتْني ،\nلأنى أعدايى نسوا وصاياكر .\n141 مَُرحىصٌ قـروْلُكر جداً ،\nوعبدُكر أرحربىهُ .\n141 صغيرٌ أنا ومرذولٌ\nوحُقوقركر لم أرنْسر .\n142 عدلُكر حقٌّ هو إلى الأبده ،\nوكلامُكر حقٌّ هو .\n143 ضهيقٌ وشهدىةٌ أدركاني\nووصاياكر هى تلاوتهى .\n144 عادلةٌ هى شهاداتُكر إلى الدهره\n\nفـرهِّمْني فأحيا .\n(19)\n145 صرخْتُ من كُلِّ قلبِه ، فاسترجهبْ لي ، يا ربُّ ،\nإنِِّ أبتغهى حُقوقركر .\n146 صرخْتُ إليك ، فرخرلِّصْني ،\nوأنا أحفظُ شهاداتهكر .\n147 سربهقْتُ وتـرقردىمْتُ في غريرْه وقتٍ وصرخْتُ ،\nوعلى كلامهكر توكىلْتُ .\n148 سربهقرتْ عيناىر وقتر السرحره ،\nلأرلهْرجر في أقوالك .\n149 استرمعْ صوتي ، يا ربُ ، حسب رحْْتهكر ،\nوبَهرسربه أحكامهكر أحْيهني .\n151 اهقـْتـربر بالإثم الذين يطردونرني ،\nوعن ناموسهكر ابتعدوا .\n151 قريبٌ أنت ، يا ربُّ ،\nوكُلُّ وصاياكر حقٌّ هى .\n152 منذُ البدءه عرفْتُ من شهاداتهكر ،\nأنكر إلى الدهره أسىسترها .\n\n(21)\n153 اُنْظُرْ إلى تواضُعهى وأرنقهذْني ،\nفإنِِّ لم أرنْسر ناموسركر .\n154 اُحْكُمْ لي في دعواىر ونجرِّني\nمن أجله كلمتهكر لأحيا .\n155 بعيدٌ هو الخلاصُ من الخُطاةه ،\nلأنـىهُم لم يطلبوا حُقوقركر .\n156 رأفاتُكر كثيرةٌ جداً ، يا ربُّ ،\nحسب أحكامهكر أرحْيهني .\n157 كثيرون هُم الذين يضطهدونرني ويُُْزهنونرني\nوعن شهاداتهكر لم أرحهدْ .\n158 رأيتُ الذين لا يفهمونر فتـرورجىعر قلبِه ،\nلأنـىهُم لأقوالك لم يُرفظوا .\n159 اُنْظُرْ ، يا ربُّ ، إنِِّ أحبربْتُ وصاياكر\nفبِهحْْتهكر يا ربُّ أرحْيهني .\n161 بدءُ كلامهكر حرق\nوإلى الأبده كُلُّ أحكامه حُقوقهكر .\n(21)\n161 الرؤساءُ اضطهدوني بلا سربر بٍ ،\n\nومن أقوالك جرزهعر قلبِه .\n162 أبتهجُ أنا بهكلامهكر ،\nكرمن ورجردر غنايمر كثيرةً .\n163 أبغضْتُ الظُلْمر ورذهلْتُهُ ،\nأما ناموسُكر فأحْبربْتُهُ .\n164 سربْعر مرىاتٍ في النهاره سربىحْتُكر\nعلى أحكامه عدلهكر .\n165 فـرلْيركُنْ سلامٌ عظيمٌ للذين يُُبُّونر اسْْركر ،\nوليس لهرُم شكٌّ .\n166 انتظرتُ خلاصركر ، يا ربُّ ،\nووصاياكر حرفهظْتُها\n167 حرفهظرتْ نفسي شهاداتهكر ،\nوأرحْبربْتُها جداً\n168 حرفهظْتُ وصاياكر وشهاداتهكر ،\nوكُلُّ طُرُقهى أمامركر ، يا ربُّ .\n(22)\n169 فـرلْيردْنُ ابتهالي قدامك ، يا ربُّ ،\nكرقروْلهكر فـرهِّمْني .\n171 لهيردْخُلْ تـرورسُّلهى إلى حرضْرتهكر\n\nكركلمتهكر أرحْيهني .\n171 تفيضُ شفتاىر تسبيحاً ،\nإذا ما عرلىمترني حُقوقركر .\n172 لساني َُهيبُ بأقوالك ،\nلأنى جميع وصاياكر هى عادلةٌ .\n173 لهتركُنْ يردُكر لهتُخرلِّصرني ،\nلأنىني اهشتهيْتُ وصاياكر .\n174 اهشتـرقْتُ إلى خلاصهكر ، يا ربُّ ،\nوناموسُكر هو تلاوتهى\n175 تُريا نفسي وتُسربِّحُكر ،\nوأحْكامُكر تُعينُني .\n176 ضرلرلْتُ مثلر الخروفه الضال\nفأُطْلُبْ ع بدركر ، فإنِِّ لهوصاياكر لم أرنْسر .", "119": "المزمورُ المئةُ والتاسعَ عشرَ\nتسبحةُ الدرجٍ (1)\n1 إليك يا ربُّ صرخْتُ في ضيقتَّه ،\nفاستجبْتر لي .\n2 يا ربُ ، نرجِّ نفسي من الشفاه الظالهمةه\n\nومن اللسانه الغاش .\n3 ماذا تـُعْطرى وماذا يُز ادُ لكر\nبهإزاءه اللسانه الغاشِّ ؟\n4 سهامُ الأقوياءه مُرْهرفرةٌ مع جَرْره البـرِّيةه.\n5 وريْلهى إنى غُرْبرتَّه قد طالرتْ عليّ ،\nوسركرنْتُ في مساكنه قيدارٍ .\n6 تـرغرىبرتْ نفسي في مواضهعر كثيرةٍ ،\nمع مُبْغهضى السلامه .\n7 كُنْتُ صاحهبر سلامٍ\nوحينر كُنْتُ أُكرلِّمُهُم كانوا يُقاتلونرني مَرىاناً .", "120": "المزمورُ المئةُ والعشرونَ\nتسبحةُ الدرجٍ (2)\n1 رفـرعْتُ عريـْنِرى إلى الِباله\nمن أينر تأتهى مرعونرتَّه ؟\n2 مرعونتَّه أنا هى من عنده الربّ ،\nالذي خرلرقر السماءر والأرضر .\n3 لا تـُعْطه رهجْلركر للزر لرله ،\nولا تردرعْ حافظركر ينامُ .\n\n4 هوذا لا ينعسُ ولا ينامُ\nحارسُ إسراييلر .\n5 الربُّ يُرفظُكر ،\nالربُّ يُظرلِّلُ على يردهكر اليُمنِر\n6 لا تُرقُكر الشرمسُ بالنهار ،\nولا القمرُ بالليل .\n7 الربُّ يُرفظُكر من كُلِّ سوءٍ ،\nالربُّ يُرفظُ نـرفْسركر .\n8 الربُّ يُرفظُ دُخولركر وخُروجركر\nمن الآنه وإلى الدهره .", "121": "المزمورُ المئةُ والحادى والعشرونَ\nتسبحةُ الدرجه (3)\n1 فرهحْتُ بالقايلينر لي :\nإلى بيته الربّ نذهبُ\n2 ورقـرفرتْ أرْجُلُنا\nفي دياره أورشليمر .\n3 أورشليمر التي تـُبـْ نِر مثلر مدينةٍ\nمرسّرىتُُا من هذا إلى هذا .\n\n4 لأنى هناكر صرعردرتْ القبايلُ ، قبايلُ الربّ ،\nشهادةً لإسراييلر ، يعتَرفونر لاسْم الربّ\n5 لأنه هناكر نُصهبرتْ كراسىٌّ للقضاءه ،\nكراسىٌّ على بيته داود .\n6 اهسألي عن أهله سلام تهكه يا أورشليمُ ،\nوالخهصْبر لهمُحبِّيكه .\n7 لهيركُنْ السلامُ في قـُوىتهكه ،\nوالخهصْبُ في أربراجهكه الحصينةه .\n8 من أجله إخوتهى وأقربايى .\nتركلىمْتُ من أجلهكه بالسلامه\n9 من أجله بيته الربّ إلهرهنا ،\nاهلْترمسْتُ لكه الخيرْاته .", "122": "المزمورُ المئةُ والثانِى والعشرونَ\nتسبحة الدرجه (4)\n1 إليك رفـرعْتُ عريـْنِرى ،\nيا ساكنر السماء .\n2 هوذا كرمثله عيونه العبيده إلى أيدهى مرورالهيهم ،\nومثله عريـْنِره الأرمرةه إلى يرده سيِّدتُها ،\n\nهكذا أعينُنا نُرور الربّ إلهرهنا ،\nحتَّى يتَر اءرفر علينا .\n3 اهرْحْرْنا ، يا ربُّ ، اهرْحْرْنا ،\nفإننا كثيراً اهمتلأنا هرواناً\n4 وبالأكثره اهمتلأرتْ نفوسُنا\nالعار أعطه للمُخْصهبهينر\nوالهوانر للمُتعظِّمهينر .", "123": "المزمورُ المئةُ والثالثُ والعشرونَ\nتسبحةُ الدرجه (5)\n1 لولا أنى الربّ كانر فينا ،\nلهيـرقُلْ إسراييلُ ،\n2 لولا أنى الربّ كانر فينا ،\nعندما قامر الناسُ علينا ،\n3 إذاً لابتلعونا ونُرنُ أحياءٌ ،\nعندر سُخْطه غرضربهم علينا .\n4 إذاً لرغرىقرنا الماءُ ،\nوعربـرتْ أنفسُنا السريْلر\n5 أرتـرى جازرتْ نفسُنا الماءر الذي لا نْه ايةر له .\n\n6 مُباركٌ الربُّ ،\nالذي لم يُسرلِّمْنا فريسةً لأسنانْهم .\n7 نجرتْ نفسُنا مثلر العصفوره من فرخِّ الصيادينر\nالفرخُّ انكسر ونُرنُ نجروْنا .\n8 عرونُنا باسمه الربّ ،\nالذي خرلرقر السماءر والأرضر .", "124": "المزمورُ المئةُ و الرابعُ والعشرونَ\nتسبحةُ الدرجه (6)\n1 المتوكِّلونر على الربّ مثلر جربرله صهيون\nلا يزولُ إلى الأبده الساكنُ بأورشليمر .\n2 الِبالُ حروْلهرا ، والربُّ حروْلر شعبه\nمن الآنه وإلى الأبده .\n3 الربُّ لا يتـْرُكُ عرصا الخُطاةه تستقهرُّ على نصيبه الصدِّيقه ينر ،\nلكى لا يَرُدى الصدِّيقونر أيدهيـرهُم إلى الإثُْه .\n4 أرحْسهنْ ، يا ربُّ ، إلى الصالحهينر ،\nوإلى المُستقيمهى القلوبه\n5 أما الذين يَريلونر إلى العثراته\nيـرنْزعُهُم الربُّ مع فاعلهى الإثُْه .\n\nوالسلامُ على إسراييلر .", "125": "المزمورُ المئةُ والخامسُ والعشرونَ\nتسبحةُ الدرجه (7)\n1 إذا ما ردى الربُّ سربِْر صهيون ،\nصهرْنا مثلر المُتعزِّينر .\n2 حينئذٍ اهمتلأر فرمُنا فـرحاً\nولهسانُنا تُرليلاً\nحينئذٍ يُقالُ في الأُمرمه :\nإنى الربّ قد عرظىمر الصنيعر مرعرهُم .\n3 عرظىمر الربُّ الصنيعر مرعرنا ،\nفرصهرْنا فرهحهينر .\nٍه 4 أرْدُدْ ، يا ربُّ ، سربـْيرنا\nمثلر السيوله في الِنوبه .\n5 الذين يزرعونر بالدموعه\nيُرصدونر بالابتهاجه .\n6 سريرْاً كانوا يسيرونر وهُم باكونر حاملينر بهذارهُم\nويعودونر بالفرحه حاملينر أغْمارهُم .", "126": "المزمورُ المئةُ والسادسُ والعشرونَ\nتسبحةُ الدرجه لهسُليمانر (8)\n1 إنْ لم يـربْْه الربُّ البيتر ،\nفباطلًا ترعهبر البناؤونر\nإنْ لم يُرُسه الربُّ المدينةر ،\nفباطلًا سرهر الحُرىاسُ .\n2 باطلٌ هو لكُم التبكيرُ ،\nاهنـْهرضوا من بعده جُ لوسهكُم ،\nيا آكهلهى الخُبـْزر بالهُمومه ،\nإذا أرعْطرى أحباءرهُ نـروْماً .\n3 هوذا ميراثُ الربّ ، هُم البنونُ ،\nأُجْرةُ ثَرةه البطنه .\n4 كالسهامه بيده القوِّىِّ ،\nكذلك أبناءُ المرفوضينر .\n5 مغبوطٌ هو الرجُلُ الذي يَرلأُ شرهْوترهُ منهُم\nحينئذٍ لا يَرْزروْنر ، إذا كلىموا أعداءرهُم في الأبوابه .", "127": "المزمورُ المئةُ والسابعُ والعشرونَ\nتسبحةُ الدرجه (9)\n1 طوبى لجميع الذين يتىقونر الربّ ،\nالسالكهينر في طُرُقه .\n2 تأكُلُ من ثَرةه أتعابك ،\nتصيرُ مرغبوطاً ويكونُ لكر الخر يـْرُ .\n3 اهمرأرتُكر تصيرُ مثلر كرْمةٍ مُُْصهبةٍ في جوانبه بيتهكر .\nبـرنُوكر مثلر غُروسه الزيتونه الُِدده حرولر مايدتهكر .\n4 هوذا هكذا يُباركُ الإنسانُ\nالخايفُ من الربّ .\n5 يبارهكُكر الربُّ من صهيون ،\nوتُبصهرُ خريرْاته أورشليمر جميع أيامه حياته كر ،\n6 وتـرى برني برنهيكر .\nوالسلامُ على إسراييلر .", "128": "المزمورُ المئةُ والثامِنُ والعشرونَ\nتسبحةُ الدرجه (11)\n1 مراراً كثيرةً حاربوني منذُ صهباىر ،\nلهيـرقُلْ إسراييلُ\n\n2 مهراراً كثيرةً قاتلوني منذُ شبابي ،\nوإنـىهُم لم يقدر وا عليّ .\n3 على ظرهْرى جرلردرني الخُطاةُ ،\nوأطالوا إثَْرهُم\n4 الربُّ عادلٌ هو ،\nيقطعُ أعناقر الخُطاةه .\n5 فـرلْيرخْزر ولْيـرْتردى إلى الوراءه\nكُلُّ الذين يُبغضونر صهيون\n6 ورلْيكونوا مثلر عُشْبه السطوحه ،\nالذي يـريْبرسُ قبلر أنْ يُقطرعر\n7 الذي لم يَرلأْ الحاصهدُ منهُ يردرهُ ،\nولا الذي َرْمرعُ الأغْمار حهضْنرهُ\n8 ولم يـرقُله المُجتازونر إنى بـركةر الربّ عليكُم ،\nباركناكُم باسمه الربّ .", "129": "المزمورُ المئةُ والتاسعُ والعشرونَ\nتسبحةُ الدرجه (11)\n1 من الأعماقه صرخْتُ إليك ، يا رب\n2 يا ربُّ ، اهستمعْ صوتي\n\nلهتركُنْ أُذُناكر مُصْغهيرتـرينْه إلى صوته تضرُّعى .\n3 إنْ كُنْتر للآثامه راصداً ، يا ربُّ ،\nيا ربُّ ، من يـرثْبُتُ ؟\n4 لأنى من عندهكر هى المغفرةر .\n5 من أجله اسْْهكر ، صربِهْتُ لكر ، يا ربُّ ،\nصر بِهرتْ نفسي لهناموسهكر .\n6 توكىلرتْ نفسي على الرب\nمن مُرسه الصُبْحه إلى الليل .\n7 من مُرْرسه الصُبْحه فـرلْينتظرْ إسراييلُ الربّ\nلأنى الرحْْةر هى من عنده الربّ ، وعظيمٌ هو خلاصُهُ ،\n8 وهو الذي يُنقهذُ إسراييلر\nمن جميع آثامه .", "130": "المزمورُ المئةُ والثلاثونَ\nتسبحةُ الدرجه (12)\n1 يا ربُّ ، لم يرترفعْ قلبِه ،\nولم تستعله عيناىر\nولم أسلكْ في العظايمه\nولا في العجايبه التي هى أرعْلرى مهنِِّ ،\n\n2 فإنْ كُنْتُ لم أرتىضهعْ ،\nلكن اهرتفعر صوتي\nمثلر الفطيمه من اللربْره يأتهى إلى أًمِّه ،\nكذلك المُجازاةه إلى نفسي .\n3 فـرلْيتىكهلْ إسراييلُ على الرب\nمن الآنه وإلى الأبده .", "131": "المزمورُ المئةُ والحادى والثلاثونَ\nتسبحةُ الدرجه (13)\n1 اُذْكُرْ ، يا ربُّ ، داود وكُلى دهعرته\n2 كما أرقْسرمر للربِّ ، ونرذر لإله يعقوب\n3 إنِِّ لا أدخلُ إلى مسكنه بيتَّه ،\nولا أرصعدُ إلى سريره فراشى ،\n4 ولا أُعْطهى لهعريـْنِرى نـروْماً ولأجفاني نُعاساً\nولا راحةً لهصهدْغى ،\n5 حتَّى أجدر مروضعاً للربِّ ،\nومسكناً لإله يعقوب .\n6 ها قد سْرعنا بِها في أفراتا ،\nوورجردْناها في موضعه الغابةه .\n\n7 فـرلْنردخُلْ إلى مساكنه ،\nونرسجُدْ في الموضعه الذي فهيه قامتْ قدماهُ .\n8 قُمْ ، يا ربُّ ، إلى راحتهكر ،\nأنت وتابوتُ موضعه قدسهكر\n9 كرهرنرتُكر يلبسونر البِهى ،\nوقدِّيسوكر يبتهجونر .\n11 من أجله داود عبدهكر ،\nلا تـرُدى وجهكر عن مسيحهكر .\n11 حرلرفر الربُّ لداود حرقّاً ، ولا يَرلفُ\nأنه من ثَرةه بطنهكر أجعلُ على كُرسهيِّكر .\n12 إن حرفرظر بـرنُوكر عهدهى وشهاداتهى ،\nالتي أنا أُعرلِّمُهُم إياها ،\nفبنوهُم إلى الأبده َرلسونر على كُرسهيِّكر .\n13 لأنى الربّ اهختار صهيون ،\nاهختارها مسكناً له .\n14 هذا هو موضعُ راحرتَّه إلى أبده الأبده\nهُنا أسكُنُ ، لأني أردتُهُ .\n15 لهصريدها أُبارهكُ تبِْيكاً ،\nلهمساكهينها أُشْبهعُ خُبْزاً\n\n16 لهكرهرنرتها أُلْبهسُ الخلاصر ،\nوأبْرارُها يبتهجونر ابتهاجاً .\n17 هناكر أُقيمُ قـرْناً لداود ،\nهيىأْتُ سهراجاً لهمسيحى\n18 لأعدايه أُلْبهسُ الخهزْىر ،\nوعليه يـُزْهرُ قدسهى .", "132": "المزمورُ المئةُ والثانِى والثلاثونَ\nتسبحةُ الدرجه (14)\n1 هوذا ما أرحْسرنر وما أرحْلرى ،\nأنْ يسكُنر الإخوةُ مع اً .\n2 كالطيبه الكاينه على الرأسه ،\nالذي يـرنْزهلُ على اللحيةه ، لحهيةه هارونر ،\nالنازله على جريْبه قميصه\n3 مثلر نردرى حرْمونر النازله على جربرله صهيون\nلأنه هناكر أرمر الربُّ بالبِركةه والحياةه إلى الأبده .", "133": "المزمورُ المئةُ والثالثُ والثلاثونَ\nتسبحةُ الدرجه (15)\n1 ها باركوا الربّ ، يا عبيدر الربّ ،\nالقايمينر في بيته الربّ ، في دياره بيته إلهرهنا\n2 في الليالي ارفعوا أيديركُم إلى القدسه ،\nوباركوا الربّ .\n3 يُبارهكُكر الربُّ من صهيون ،\nالذي خرلرقر السماءر والأرضر .", "134": "المزمورُ المئةُ والرابِعُ والثلاثونَ\nهلّلويا\n1 سربِّحوا اسمر الربّ ،\nسربِّحوا الربّ يا عبيدر الربّ ،\n2 الواقفينر في بيته الربّ ،\nفي دياره بيته إلهرهنا .\n3 سربِّحوا الربّ ، فإن الربّ صالهحٌ\nرتِّلوا لاسْْه فإنه حُلْوٌ\n4 لأنى الربّ اهختار يعقوب لهذاته ،\nوإسراييلر ميراثاً له .\n\n5 لأني أنا قد عرلهمْتُ أنى الربّ عظيمٌ هو ،\nوربُّنا فوقر جميع الآلهةه\n6 كُلُّ ما شاءر الربُّ صرنرعر\nفي السماء وعلى الأرض ،\nفي البحاره والأعماقه\n7 الذي يُصْعهدُ ال سحابر من أقاصى الأرض ،\nوصرنرعر البُِوقر للمطره\nالذي يَُْرهجُ الرياحر من كنوزه .\n8 الذي ضربر أبكار مهصْر\nمن الناسه إلى البهايمه\n9 أرسلر آياتٍ وعجايبر في وسطهكه ، يا مهصْر ،\nعلى فرعونر وعلى كُلِّ عبيده .\n11 الذي ضربر أُمَراً كثيرةً ،\nوقـرترلر مُلوكاً أعزىاءر ،\n11 سيحونر مرلهكر الأموريينر ،\nوعوجر مرلهكر باشانر ،\nوجميع مَرالهكه كنعانر .\n12 وأعْطرى أرضرهُم ميراثاً ،\nميراثاً لإسراييلر عبده .\n\n13 اهسُْْكر يا ربُّ دايمٌ إلى الأبده ،\nوذهكْرُكر إلى أجياله الأجياله .\n14 لأنى الربّ يتَراءرفُ على شعبه ،\nوعبيدُهُ يردْعونرهُ .\n15 آلهةُ الأُمرمه فهضىةٌ وذرهربٌ ،\nوهى أعمالُ أيدهى الناسه .\n16 لهرا أفواهٌ ولا تتكلىمُ ،\nلهرا أعينٌُ ولا تـُبْصهرُ\n17 لهرا آذانٌ ولا تسمعُ ،\nلهرا أنفٌ ولا ترشهمُّ .\nلهرا أيدٍ ولا تلمسُ ، لهرا أرجُلٌ ولا ترشى .\nلا تصيحُ بهصوتٍ من حرنجرتُها ،\nوليس في أفواها روحٌ .\n18 يُشْبهُها الذين يصنعونْرا ،\nوجميع المتوكلين عليها .\n19 يا بيتر إسراييلر ، باركوا الربّ ،\nيا بيتر هارونر ، باركوا الربّ ،\n21 يا بيتر لاوى ، باركوا الربّ ،\nيا خايفي الربّ ، باركوا الربّ .\n\n21 مُباركٌ الربُّ من صهيون ،\nالساكنُ في أورشليمر .", "135": "المزمورُ المئةُ والخامسُ والثلاثونَ\nهلّلويا\n1 اهعتَرفوا للربِّ فإنه صالهحٌ ،\nوأنى إلى الأبده رحْْترهُ .\n2 اهعتَرفوا لإله الآلهةه ،\nلأنى إلى الأبده رحْْترهُ .\n3 اهعتَرفوا لهربِّ الأربابه ،\nلأنى إلى الأبده رحْْترهُ\n4 الذي يصنعُ العجايبر وحْدرهُ ،\nلأنى إلى الأبده رحْْترهُ\n5 الذي خرلرقر السماوات بهفرهْمٍ ،\nلأنى إلى الأبده رحْْترهُ\n6 الذي ثـربىتر الأرضر على المياه ،\nلأنى إلى الأبده رحْْترهُ\n7 الذي خرلرقر الأنوار العظيمةر وحدرهُ ،\nلأنى إلى الأبده رحْْترهُ\n\n8 الشمسر لهسُلطانه النهاره ،\nلأنى إلى الأبده رحْْترهُ\n9 القمر والنجومر لهسُلطانه الليل ،\nلأنى إلى الأبده رحْْترهُ\n11 الذي ضر ربر المصريينر مع أبكارهم ،\nلأنى إلى الأبده رحْْترهُ\n11 وأرخْرجر إسراييلر من ورسرطهم ،\nلأنى إلى الأبده رحْْترهُ\n12 بيدٍ عزيزةٍ وذراعٍ عاليةٍ ،\nلأنى إلى الأبده رحْْترهُ\n13 الذي شرقى البحر الأحْْر إلى أقسامٍ ،\nلأنى إلى الأبده ر حْْترهُ\n14 وأرخْرجر إسراييلر من ورسرطه ،\nلأنى إلى الأبده رحْْترهُ\n15 وطرحر فرعونر وجميع قـُوىته في البحره الأحْْره ،\nلأنى إلى الأبده رحْْترهُ\n16 الذي أرخْرجر شرعبرهُ إلى البـرِّيةه ،\nلأنى إلى الأبده رحْْترهُ\n17 الذي أرخْرجر الماءر من صخرةٍ صرمىاءر ،\n\nلأنى إلى الأبده رحْْترهُ\n18 الذي ضربر ملوكاً عُظرماءر ،\nلأنى إلى الأبده رحْْترهُ\n19 وقـرترلر ملوكاً عجيبهينر ،\nلأنى إلى الأبده رحْْترهُ\n21 سيحونر مرلهكر الأموريهينر ،\nلأنى إلى الأبده رحْْترهُ\n21 وعوجر مرلهكر باشانر ،\nلأنى إلى الأبده رحْْترهُ\n22 وأعطى أرضرهُم ميراثاً ،\nلأنى إلى الأبده رحْْترهُ\n23 ميراثاً لإسراييلر عبده ،\nلأنى إلى الأبده رحْْترهُ\n24 في تواضُعهنا ذركرنا الربُّ ،\nلأنى إلى الأبده رحْْترهُ\n25 وخرلىصرنا من أيدهى أعدايهنا ،\nلأنى إلى الأبده رحْْترهُ\n26 الذي يُعطى طعاماً لهكُلِّ ذهى جرسردٍ ،\nلأنى إلى الأبده رحْْترهُ\n\n27 اهعتَرفوا لإله السماء ،\nلأنى إلى الأبده رحْْترهُ\n28 اهعتَرفوا لهربِّ الأربابه ، لأنى إلى الأبده ر حْْترهُ .", "136": "المزمورُ المئةُ والسادسُ والثلاثونَ\nلداود وأرميا\n1 على أنْْاره بابلر هناكر جرلرسْنا ،\nوبركريْنا عندما ترذركىرْنا صهيون\n2 على الصفيْصافه في ورسرطها ،\nعرلىقْنا قيثاراتهنا .\n3 لأنه هناكر سرأرلرنا الذين سربـروْنا أقوالر التسبيح ،\nوالذين استاقونا إلى هناكر قالوا :\nسربِّحوا لنا تسبيحةً من تسابيحه صهيون .\n4 كيف نُسربِّحُ تسبحةر الرب\nفي أرضٍ غريبةٍ ؟\n5 إنْ نرسهيْتُكه ، يا أورشليمُ ،\nأرنْسرى يَريني\n6 يلتصقُ لساني بَهرنركهى إنْ لم أرذْكُرْكه ،\nإنْ لم أرسْبهقْ فأُرتِّبر أور شليمر في اهبتداءه فـرحى .\n\n7 أُذْكُرْ ، يا ربُّ ، برني أدومر في يومه أورشليمر ،\nالقايلينر : انقضوا ، انقضوا ، حتَّى الأساسر منها .\n8 يا بنتر بابلر الشقيىةرٍه ،\nطوبى لهمن يُكافهئُكه مُكافأتركه التي جرازريْتهنا\nطوبى لهمن يَرسكُ أطفالركه ويدفنـُهُم عندر الصخرةه .", "137": "المزمورُ المئةُ والسابعُ والثلاثونَ\nلداود وزكريا\n1 أعتَرفُ لكر ، يا ربُّ ، من كُلِّ قلبِه ،\nلأنك استمعتر كُلى كلماته فمى\nأمامر الملايكةه أُرتِّلُ لكر .\n2 وأسجُدُ قُدىامر هيكرلهكر المقدىسه ، وأرعتَرفُ سْْهكر\nعلى رحْْتهكر وحرقِّكر ،\nلأنك قد عرظىمْتر اسْْركر القدُّوسر على الكُلِّ .\n3 في اليومه الذي أردعوكر فيه ، أرجهبْني بهسُرعةٍ\nتُكْثهرُ التطلُّعر على نفسي بهقوىةٍ .\n4 فـرلْيرعتَرفْ لكر ، يا ربُّ ، كُلُّ ملوكه الأرض ،\nلأنـىهُم سْرعوا ساير كلماته فرمهكر\n5 وليُسبّحوا في طُرُقه الربّ ،\n\nلأنى مَرْدر الربّ عظيمٌ\n6 الربُّ عالٍ ، ويُعاينُ المتواضعاته ،\nوالكايناتُ يرعرهفُها من بـُعْدٍ .\n7 إنْ سلكتُ في وسطه الشهدىةه تُُْيهيني\nعلى رهجْزه الأعداءه مردردّتر يردركر ،\nوخرلىصرتْني يَرينُكر .\n8 الربُّ يُكافئُ ع\nيا ربُ ، رحْْتُكر دايمةٌ إلى الأبده ،\nيا ربُّ ، أعمالُ يردريْكر لا تـرتَْكْها عنكر .", "138": "المزمورُ المئةُ والثامنُ والثلاثونَ\nإلى النهاية مزمورٌ لداود ولهزكريا في الشتاته\n1 يا ربُّ ، قد اهختربِرترني وعرفـْترني\n2 أنت تعرفُ جُلوسى وقيامى ،\nفرهمْتر أفكارى من بعيدٍ\n3 سبيلى وسرجهيىتَّه أنت فرحرصْتـرهُما ،\nوكُلى طُرُقى سربـرقْتر ورأريْتر .\n4 لأنه ليس كلامُ ظُلْمٍ في لساني\n5 ها أنت ، يا ربُّ ، قد عرفْتر الكُلى\n\nالأخيراته والأوىلاته\nأنت جربـرلْترني وورضرعْتر يردركر عليّ .\n6 صار عهلْمُكر عجيباً عندهى ،\nاهعْتـرزى ، فلرم أقدهرْ عليه .\n7 أينر أرذهبُ من روحهكر ؟\nومن وجهكر أينر أرهْرُبُ ؟\n8 إنْ صرعدتُ إلى السماء ، فأنت هناكر\nوإنْ نرزلْتُ إلى الِحيمه ، فهنا كر أنت أيضاً\n9 إنْ أرخرذْتُ لي جناحرينْه في الصباحه وأرقرمتـُهُما\nوسكنتُ في أقاصهى البحره ،\n11 فهناكر أيضاً يردُكر تـرهْدهيني ،\nويَرينُكر تُْسهكُني .\n11 فـرقُلْتُ لعلى الظلمةر تُغطِّيني ،\nوالليلُ هو ضياءٌ في ترنعُّمى\n12 لأنى الظُلمةر لا تُظله مُ لديكر\nوالليلُ مثلر النهاره يُضىءُ\nمثلُ ظُلمته هكذا نورُهُ .\n13 لأنك أنت يا ربُّ اهقتنيتر كُلْيرتَّرى ،\nوقربهلْترني مُذْ كُنْتُ في بطنه أمي .\n\n14 أرعتَرفُ لكر ، يا ربُّ ، لأنـىهُم يتعجىبونر منكر بهرهْبةٍ\nعجيبةٌ هى أعم الُكر ، ونفسي عرلهمرتْ ذلكر جداً .\n15 لم يَرتفه عنكر عرظمى الذي صرنـرعْتره في الخفاءه ،\nوأُقنومى في أرسافهله الأرض\n16 وما لم يُعمرلُ مَهىا هو لكر رأرتْهُ عيناكر ،\nوفي سهفْرهكر جميعهُم يُكتربونر\nبالنهار يَُلرقونر (إذ) لم يركُنْ فيهم أحدٌ .\n17 أما أنا فما أكرمر أحباءركر عندى ، يا اللهُ\nاهعْتـرزىتْ رياساتـُهُم جداً\n18 أُحصهيهُم فيكثُرونر أكثـر من الرمله ،\nقُمتُ وأنا أيضاً معكر ،\n19 إنْ أنت أرهلكْتر الخُطاةر ، يا اللهُ\nيا رهجالر الدماءه ، حهيدوا عنِِّ .\n21 لأنـىهُم يقولون مُت فكِّرينر\nأنْ يأخُذوا مُدُنركر بالباطل .\n21 أليسر لهمُبغضهيكر يا ربُّ أبغضْتُ\nوعلى أرعدايهكر كُنْتُ أذوبُ ؟\n22 بـُغْضاً تامّاً أربـْغرضْتـُهُم ،\nصاروا لي أعداءً .\n\n23 اهخْتربِهني ، يا اللهُ ، واعْرهفْ قلبِه\nاهمْترحهنِِّ واعْرهفْ طُرُقى\n24 وانْظُرْ إنْ كُنْتر تـرى فىهى إثَْاً ،\nواهْدهني طريقاً أبديّاً .", "139": "المزمورُ المئةُ والتاسعُ والثلاثونَ\nإلى النهاية مزمورٌ لداود\n2 نجرِّني ، يا ربُّ ، من إنسانٍ شرِّيرٍ ،\nومن رهجُلٍ ظالَهٍ خرلِّصْني .\n3 الذين تفكىروا بالظلمه في ق لبهم ،\nالنهار كُلىهُ يستعدُّونر للقتاله\n4 سرنُّوا لسانـرهُم كالحيىةه ،\nسُمُّ الأفعرى وتحت شهفاهم . سلام .\n5 اهحفظْني ، يا ربُّ ، من يده الخاطئه ،\nومن إنسانٍ ظالَهٍ نجرِّني ،\nالذين تشاوروا أن يـُعرْقهلوا خرطرواتهى .\n6 أرخْفرى لي المُتك ونر فرخّاً ،\nورباطاتٍ مردُّوها فرخّاً لهرهجْلهىى\nأرخْفوا لي بهقُرْبه الطريقه عرثـْرةً . سلام .\n\n7 قـُلْتُ للربِّ أنت هو إلهي\nأرنْصهتْ ، يا ربُّ ، لهصوته تضرُّعى .\n8 يا ربُّ يا ربُّ ، قوىةر خلاصى ،\nأنت ظرلىلْتر على رأسي في يومه القتاله .\n9 لا تُسرلِّمْني ، يا ربُّ ، للخاطئه من قهبرله شرهوتهى\nتشاوروا عليّ ، فلا تـرتـْرُكْني عنكر ،\nلئلا يرتفعوا . سلام .\n11 رأسُ فسادٍهٍم وشرقاءُ شهفاهم يـُغرطِّيهم.\n11 يسقطُ عليهم جَرُ نارٍ على الأرض\nترطرحُهُم في الشقاءه ،\nفلا يستطيعونر القيامر .\n12 رجُلٌ يَرتدُّ لسانُهُ لا يستقيمُ على الأرض\nالرجلُ الظالَهُ تُصهيدُهُ الشرورُ إلى الهلاكه .\n13 قد عرلهمْتُ أنى الربّ يصنعُ حُكْماً للمساكينه\nوانتقاماً للبايسينر .\n14 إنِىا الصدِّيقونر يعتَرفونر لاسْْهكر ،\nويسكنُ المس تقيمونر مع وجهكر .", "140": "المزمورُ المئةُ والأربعونَ\nمزمورٌ لداود\n1 يا ربُّ ، إليك صرخْتُ فاستمعْ لِه\nأرنْصهتْ إلى صوته تضرُّعى ، إذا ما صرخْتُ إليك .\n2 لهتسترقهمْ صلاتي كالبخوره قدامك ،\nرفْعُ يردرىى ذبيحةٌ مساييةٌ هو .\n3 ضرعْ ، يا ربُّ ، حافظاً لهفمى ،\nوباباً حصيناً لهشرفرتَّرى .\n4 ولا تُهلْ قلبِه إلى كلامه الشرِّ ،\nفيتعلىلر بهعهلرلٍ في الخطايا ،\nمع الناسه فاعلهى الإثُْه ،\nولا أرتفيقُ مع مُُتارهيهم .\n5 فـرلْيـُؤردِّبْني الصهدِّيقُ برحْْةٍ ويـُوربِِّْني ،\nزيتُ الخ اطئه لا يردْهنُ رأسهى\nلأنى صلاتي أيضاً بِهرسرىةٍ .\n6 قد اُبـْتُلهعر أقوياؤُهُم عندر الصخرةه\nيسمعونر كلماتهى لأنـىهُم استـرلرذُّوا (بِها ) .\n7 مثلر شرحْمه الأرض ، اهنشقُّوا على الأرض ،\nتبدىدرتْ عظامُهُم عندر الِحيمه .\n\n8 لأنى عيونرنا إليك ، يا ربُّ ،\nيا ربُّ عليكر توكىلْتُ ، فلا تقتلْ نفسي .\n9 اهحْفرظْني من الفخِّ الذي قد نرصربوهُ لي ،\nومن شكوكه فاعلهى الإثُْه .\n11 يسقطُ الخُطاةُ في شربركرته ،\nوأكونُ أنا وحدى حتَّى َروزر الإثُُْ .", "141": "المزمورُ المئةُ والحادى والأربعونَ\nفـرهْمٌ لداود لرمىا كانر في المغارةه صلاةٌ\n2 بهصوتي إلى الربّ صرخْتُ ،\nبهصوتي إلى الربّ ترضرىعْتُ .\n3 أرسْكُبُ أمامرهُ توسُّلهى ،\nأربُثُّ لردريْه ضيقهى .\n4 عندر فناءه روحى مهنِِّ ،\nوأنت عرلهمْتر سُبُلهى\nفي الطريقه التي كُنْتُ أسلُكُ فيها أرخْفوا لي فرخّاً .\n5 تأمىلْتُ عن اليمينه وأبصرتُ ،\nفلم يركُنْ من يـرعْرهفُني\nضاعر المرهْربُ مهنِِّ ،\n\nوليسر من يسألُ عن نفسي .\n6 فصرخْتُ إليك ، يا ربُّ ، وقـُلْتُ أنت هو رجايى ،\nونصيبِه في أرضه الأحياءه .\n7 أرنْصهتْ إلى طهلبتَّه ،\nفإنِِّ قد ترذرلىلْتُ جداً\nنجرِّني من الذين يضطهدونرني ،\nلأنـىهُم قد اهعْتـرزُّوا أركثـر مهنِِّ .\n8 أرخْرهجْ من الحربْسه نفسي ،\nلكى أعتَرفر لاسْْهكر ، يا ربُّ\nإياىر ينتظرُ الصدِّيقونر حتَّى تَُّازيني .", "142": "المزمورُ المئةُ والثانِى والأربعونَ\nمزمورٌ لداود ، إذْ كانر ابنُهُ يُطارهدُهُ .\n1 يا ربُّ ، اهسْْرعْ صلاتي ،\nأرنْصهتْ إلى طهلبتَّه بَهرقِّكر ،\nاهسترجهبْ لي بهعدلهكر\n2 لا تردخُلْ في المُحاكرمةه مع عبدهكر ،\nفإنه لنْ يترزكىى قدامك كُلُّ حرىٍّ .\n3 لأنى ا لعدوى قد اضطهدر نفسي\n\nأرذرلى في الأرض حياتهى\nوأرجْلرسرني في الظلماته مثلر الموترى منذه الدهره\n4 أرضْجر عليّ روحى ،\nاهضْطربر فىهى قلبِه .\n5 ترذركىرْتُ الأيامر الأولِر ،\nولهرهجْتُ في كُلِّ أعمالهكر ،\nوفي صنايعه يردر يْكر كُنْتُ أتأرمىلُ .\n6 برسرطْتُ إليك يردرىى ،\nصارتْ نفسي لكر مثلر أرضٍ بلا ماءٍ . سلام .\n7 اهسترجهبْ لي ، يا ربُّ ، عاجلاً ،\nفقد فرنهيرتْ روحى\nلا ترصْرهفْ وجهكر عنِِّ ،\nفأُشابهر الهابطينر في الُِبِّ .\n8 فلأسْْرعْ الغداةه رهحْْتركر ،\nفإنِِّ عليكر توكىلْتُ\nعرِّفْني ، يا ربُّ ، الطريق التي أسلُكُ فيها ،\nلأني إليك رفـرعْتُ نفسي .\n9 أرنْقهذْني من أعدايى ، يا ربُّ ،\nفإنِِّ لِرأْتُ إليك .\n\n11 عرلِّمْني أنْ أصنعر مشيئتركر ،\nلأنك أنت هو إلهرهى\nروحُ كر القُدُّوسُ فـرلْيـُهْدهني إلى الاستقامةه .\n11 من أجله اسْْهكر ، يا ربُّ ، أرحْيهني بَهرقِّكر ،\nتُُْرهجُ من الشهدىةه نفسي\n12 وبهرحْْتهكر تستأصلُ أعدايى ،\nوتـُهْلهكُ جميع مُضايهقهى نفسي\nلأني أنا هو عبدُكر أنا .", "143": "المزمورُ المئةُ والثالثُ والأ ربعونَ\nلداود ، على جليات\n1 مُباركٌ الربُّ إلهي ،\nالذي يـُعرلِّمُ يردرىى ترتيبر القتاله ،\nوأصابعى الحرْبر .\n2 رحْْتَّه ومرلْجرأى ،\nناصري ومُنقهذى ،\nالمُقاتهلُ عنِِّ وعليه توكىلْتُ ،\nالذي أرخْضرعر لي شعبِه .\n3 يا ربُّ ، من هو الإنسانُ أنكر ظرهرْتر له ،\n\nأو ابنُ الإنسانه أنكر عردردْترهُ ؟\n4 الإنسانُ أرشْبرهر الباطل ،\nأيامُهُ مثلُ الظهلِّ تـرعْبـُرُ .\n5 يا ربُّ ، طرأطهئه السماوات وانْزهلْ ،\nاهلْمهسه الِبالر فـرلْتُدرخِّنْ\n6 لهيربـْرُقه البِرقُ فـرتُبردِّدرهُم ،\nأرْسهلْ سه هامركر فـرتـُقْلهقرهُم .\n7 أرْسهلْ يردركر من العلاءه ،\nأرنْقهذْني ونجرِّني من المياه الكثيرةه ،\nومن أيدى برني الغرباءه ،\n8 الذين تكلىمرتْ أفواهُهُم بالباطل ،\nويَرينـُهُم يَرينُ ظُلْمٍ .\n9 أُسبِّحُكر ، يا اللهُ ، تسبحةً جديدةً ،\nبِهزمارٍ ذى عرشر رةه أوتارٍ أُرتِّلُ لكر .\n11 الذي يُعطى الملوكر الخلاصر ،\nالذي يـُنْقهذُ داود عبدرهُ .\n11 نجرِّني من سيفٍ شرِّيرٍ ،\nوخرلِّصْني من يده برني الغرباءه ،\nالذين تكلىمرتْ أفواهُهُم بالباطل ،\n\nويَرهينـُهُم يَرينُ ظُلْمٍ\n12 هؤءه الذين بنوهُم مثلُ غُروسٍ جُدُدٍ\nأقوياءُ في شربيبتهم ،\nبناتـُهُم يُُرسِّنوهُن مُترزيِّناتٍ\nمثلر شهبْه الهيكله\n13 مُرازهنـُهُم ملآنةٌ تفيضُ من هذا إلى هذا\nأغنامُهُم كثيرةُ الأولاده تترزايدُ في منافذهم .\n14 أبقارُهُم سْرينةٌ\nلا يُوجردُ هر دْمٌ بأسوارهم ولا مرنـْفرذر\nولا صُراخر في ديارهم .\n15 يرغبطونر الشعبر الذي يكونُ له هذا ،\nطوبى للشعبه الذي الربُّ إلهرُهُ .", "144": "المزمورُ المئةُ والرابعُ والأربعونَ\nتسبيحٌ لداود\n1 أرْفـرعُكر ، يا إلهي ومرلهكهى ،\nوأُبارهكُ اسْْركر إلى الأبده وإلى أ بده الأبده\n2 في كُلِّ يومٍ أُبارهكُكر ،\nوأُسبِّحُ اسْْركر إلى الأبده وإلى أبده الأبده .\n\n3 عظيمٌ هو الربُّ ومُسبىحٌ جداً ،\nوليس لهعظمته مُنتهرى .\n4 جيلٌ فجيلٌ يُبارهكونر أعمالركر ،\nويَُْبِهونر بهقوىتهكر\n5 وبهعظرمه بِراءه مَرده قُ دْسهكر يتكلىمونر ،\nوبعجايبك يتحدىثونر\n6 بقوىةه مُرهباتهكر ينطقونر ،\nوبهعظمتهكر يَُْبِهونر ،\nويتحدىثونر بِهبِروتهكر .\n7 يفيضونر بهذهكْره كرثـْرةه صلاحهكر ،\nوبهعدلهكر يتهلىلونر .\n8 رؤوفٌ ورحومٌ هو الربُّ ،\nطويلُ الروحه وكثيرُ الرحْْةه\n9 صالهحٌ هو الربُّ للذين يصبِهونر ،\nورأفاتُهُ على جميع أعماله .\n11 فـرلْتعتَرفْ لكر ، يا ربُّ ، جميع أعمالهكر ،\nويُبارهكُكر قدِّيسُوكر\n11 بِهرجده ملكوتهكر يتكلىمونر ،\nوبهقوىتهكر ينطقونر ،\n\n12 لهيُظْهروا لهبرني البشر قُدْرتركر ،\nومَردر عظمةه بِراءه مُلْكهكر .\n13 مُلْكُكر مُلْكُ جميع الدهوره ،\nوربوبيتُكر في كُلِّ جيلٍ وجيلٍ .\n14 الربُّ صادقٌ في أقواله ،\nوقُدُّوسٌ في سايره أعماله .\nالربُّ يُقوِّى كُلى الذين يسقطونر ،\nويُقيمُ كُلى المطروحهينر .\n15 لأنى أرعينُر ا لكُلِّ تتَرجىاكر ،\nوأنت تُعطيهُم طعامرهُم في حينٍ حسنٍ\n16 تفتحُ يردريْكر فتملأُ كُلى حرىٍّ بالمسرىةه .\n17 الربُّ بارٌّ في كُلِّ طُرُقه ،\nوقُدُّوسٌ في سايره أعماله .\n18 الربُّ قريبٌ لهكُلِّ من يصرخُ إليه ،\nكُلِّ الذين يدعونرهُ بالحقِّ\n19 يصنعُ مشيئةر خايفهيه ،\nيسمعُ تضرُّعرهُم ويَُرلِّصُهُم .\n21 يُرفظُ الربُّ جميع مُُبِّيه ،\nويستأصهلُ جميع الخُطاةه .\n\n21 بتسبيحه الربّ ينطقُ فمى ،\nفـرلْيُبارهكْ كُلُّ ذهى جرسردٍ اهسْْرهُ القُدُّوسر\nإلى الأبده وإلى أبده الآبدينر .", "145": "المزمورُ المئةُ والخامسُ والأربعونَ\nهلّلويا ، لحهجِّى وزكريا\n1 سبِّحى يا نفسي الربّ\n2 أُسبِّحُ الربّ في حياتهى ،\nوأُرتِّلُ لإلهي ما دُمْتُ موجوداً .\n3 لا تتىكلوا على الرؤساءه ولا على برني البشر ،\nالذين ليس عندهُم خلاصٌ\n4 تُرجُ ر وحُهُم فيعودونر إلى تُرابِهم\nفي ذلكر اليومه تـرهْلركُ كافةُ أفكارهم .\n5 طوبى لهمن إلهُ يعقوب مُعينُهُ ،\nورجاؤُهُ علىالربّ إلهره\n6 الذي صرنرعر السماءر والأرضر ،\nوالبحر وكُلى ما فهيه\n7 الذي يُرفظُ العدلر إلى الدهره ،\nالصانعُ الحُكْمر للمظلومينر ،\n\nالمُعْطهى الِياعر الطعامر .\n8 الربُّ يُرهلُّ المُقيىدهينر\nالربُّ يُقيمُ الساقطهينر\nالربُّ يُُركِّمُ العُمْيانر\nالربُّ يُُبُّ الصهدِّيقهينر\n9 الربُّ يُرفظُ الغرباءر ،\nويـرعْضُدُ اليتهيمر والأرملةر ،\nويُ بيدُ طريق الخُطاةه .\n11 يَرلكُ الربُّ إلى الأبده ،\nوإلهرُكه يا صهيون من جيلٍ إلى جيلٍ .", "146": "المزمورُ المئةُ والسادسُ والأربعونَ\nهلّلويا لحهجِّى وزكريـا\n1 سبّحوا الربّ ، فإنى المزمور جيِّدٌ\nلإلهرهنا يلذُّ التسبيحُ .\n2 الربُّ يـربْني أورشليمر ،\nالربُّ َرمعُ مُتفرِّقهى إسراييلر\n3 الذي يشفي المُنكسرى القلوبه ،\nوَرْبـُرُ جميع كرسْرهم\n\n4 الذي يُُْصى كرثْرةر الكواكبه ،\nولهكافىتها يـُعْطهى أسْْاءً .\n5 عظيمٌ هو الربُّ ، وعظيمةٌ هى قوىتُهُ ،\nولا إحصاءر لهفرهْمه .\n6 الربُّ يقبلُ الوُدعاءر ،\nويرذهلُّ الخُطاةر إلى الأرض .\n7 اهبتديوا للربِّ بالاعتَهافه ،\nرتِّلوا لإلهرهنا بالقيثارةه ،\n8 الذي َُلِّلُ السماءر بالسحابه ،\nالذي يـُهريِّئُ المرطر للأرضه ،\nالذي يـُنْبهتُ العُشْبر على الِباله\nوالخُضْرةر لخهدْمةه البشر ،\n9 ويـُعْطهى البهايمر طعامرها\nولهفراخه الغربانه التي تدعوهُ .\n11 لا يُؤثهرُ قوىةر الفرسه ،\nولا يُسرُّ بساقر ىه الرىجُله\n11 يُسرُّ الربُّ بِهايفهيه\nوبالذين يتَرجُّونر رحْْترهُ .", "147": "المزمورُ المئةُ والسابعُ والأربعونَ\nهلّلويا لحهجِّى وزكريـا\n1 سبِّحى الربّ يا أورشليمُ ،\nسبِّحى إلهركه يا صهيونُ\n2 لأنه قد قوىى مغاليقر أبوابهكه ،\nوباركر برنهيكه فهيكه .\n3 الذي مجّد تُُومركه في سلامٍ ،\nويَرلأُكه من شرحْمه الحهنْطةه\n4 الذي يـُرْسهلُ كلمترهُ للأرضه ،\nفيُسْرهعُ قـروْ لُهُ عاجلاً جداً .\n5 المُعْطى الثلجر كالصوفه ،\nالمُذرِّى الضبابر كالرماده\n6 يـُلْقى الِليدر مثلر الفُتاته ،\nقُدىامر وجه بـرده من يرقومُ ؟\n7 يـًرْسهلُ كلمترهُ فتُذهيبُهُ\nتـرهُبُّ رهيُُهُ فتسيلُ المياهُ .\n8 المُخربـِّرُ كلمترهُ لهيعقوب ،\nوحُ قوقرهُ وأحكامرهُ لإسراييلر .\n9 لم يصنعْ هكذا بكُلِّ الأُمرمه ،\n\nوأحكامُهُ لم يـُورضِّحْها لهرُم.", "148": "المزمورُ المئةُ والثامنُ والأربعونَ\nهلّلويا لحهجِّى وزكريـا\n1 سبّحوا الربّ من السماوات ،\nسبّحوه في الأعالي .\n2 سبّحوه ، يا جميع ملايكته\nسبّحوه ، يا جميع قوىاته .\n3 سبِّحهيه ، أيتها الشمسُ والقمرُ\nسبِّحهيه ، يا جميع الكواكبه والنورُ .\n4 سبِّحهيه ، يا سْراواته السماوات ،\nوالمياهُ التي فوقر السماوات .\n5 لهتُسبِّحْ جميعها لاسمه الرب\nلأنه قالر فكانتْ ،\nوهو أرمر فرخُلهقرتْ .\n6 أقامرها إلى الأبده\nوإلى أبده الأبده\nورضرعر لهرا أرمْراً ، فلن تتجاورزرهُ .\n7 سبِّحى الربّ من الأرض ،\n\nأيتها التنانينُ وجميع الأعماقه\n8 النارُ ، والبـردُ ، والثلجُ ، والِليدُ ،\nوالرياحُ العاصفةُ ، الصانعةُ كلمترهُ\n9 الِبالُ العاليةُ وجميع الآكامه ،\nالأشجارُ المُثمرةُ وكُلُّ الأرزه\n11 الوُحوشُ وكُلُّ البهايمه ،\nالدبىاباتُ والطيورُ ذواتُ الأجنحةه\n11 ملوكُ الأرض وكُلُّ الشعوبه ،\nالرؤساءُ وكُلُّ قضاةه الأرض\n12 الشبابُ والعذ ارى ،\nالشيوخُ مع الأحداثه\n13 فـرلْيُسبّحوا جَريعاً اسمر الربّ ،\nلأنه قد ترعالِر اسُْْهُ ورحْدرهُ ،\nواعتَهافُهُ كاينٌ على الأرض وفي السماء\n14 يهرفعُ قـرْنر شرعْبه ،\nسُبْحاً لِهرميعه قديسيه ،\nلهبرني إسراييلر ، الشعبه القريبه إليه .", "149": "المزمورُ المئةُ والتاسعُ والأربعونَ\nهلّلويا\n1 أرنْشهدوا للربِّ نشيداً جديداً ،\nلأنى تسبحترهُ في كنيسةه القدِّيسهينر .\n2 فـرلْيفرحْ إسراييلُ بِهالهقه ،\nورلْيبتهجْ بنو صهيون بِهلهكهم\n3 فـرلْيُسبّحوا اسْْرهُ القُدُّوسر في الصفوفه ،\nبهدُفٍّ ومزمارٍ لهيرُتِّلوا لرهُ .\n4 لأنى الربّ يُسرُّ بهشعبه ،\nويرفعُ الوُدعاءر بالخلاصه .\n5 يفتخرُ الأبرارُ بالمرجْده ،\nويتهلىلونر على مضاجهعهم .\n6 تـرعْلهياتُ الله في حنجرتُهم ،\nوسيوفٌ ذاتُ حردىيْن في أيدهيهم .\n7 لكى يصنعوا انتقاماً في الأُمرمه ،\nوتوبيخاتٍ في الشعوبه ،\n8 لهيوثهقوا ملوكرهُم بالقيوده ،\nوأشرافـرهُم بأغلالٍ للأيدهى من حديدٍ ،\n9 لهيصنعوا بِهم حُكْماً مكتوباً\n\nهذا المرجدُ كانر في جميع قديسيه .", "150": "المزمورُ المئةُ والخمسونَ\nهلّلويا\n1 سبّحوا الله في قدسيه،\nسبّحوه في جلد قوّته.\n2 سبّحوه على مقتدراته،\nسبّحوه حسب كثرة عظمته.\n3 سبّحوه بصوت البوق،\nسبّحوه بالمزمار والقيثارة.\n4 سبّحوه بالدفّ والرقص،\nسبّحوه بالأوتار والأرغن.\n5 سبّحوه بصنوج حسنة الصوت،\nسبّحوه بصنوج التهليل.\n6 كل نسمة فلتسبّح الربّ. هلّلويا.", "151": "المزمورُ المئةُ والواحدُ والخَمسونَ\nمزمورٌ لداود ، حينر تُراربر ورحدرهُ مع جليات\n1 أنا الصغيرُ في إخوتهى ،\n\nوالحردرثُ في بيته أبَه\nكُنْتُ أرعرى غرنرمر أبي .\n2 يداىر صرنـرعرتا الأرغنر ،\nوأصابعى أرلهفرته المزمار . هلّلويا .\n3 من هو الذي يَُْبِهُ سيِّدهى ؟\nهو الربُّ ، وهو يستمعُ لهكُلِّ من يصرخُ إليه .\n4 هو أرسرلر ملاكرهُ ،\nوأرخرذرني من غرنرمه أبي ،\nومر سرحرني بهدُهْنه مهسْحرته .\n5 إخوتهى حسانٌ وهم أركبـرُ مهنِِّ ،\nوالربُّ لم يُسرى بِهم .\n6 خرجْتُ لهلقاءه الفلسطيني ،\nفـرلرعرنرني بأوثانه\n7 أما أنا فسرلرلْتُ سريـْفرهُ الذي بهيرده وقرطرعْتُ رأسرهُ ،\nونـرزرعْتُ العار عن برني إسراييلر . هلّلويا .\n\n+"};
